window.IDIOM_BANK = [
  { w: "一世之雄", p: ["yī", "shì", "zhī", "xióng"], e: "雄英雄豪杰。一个时代的英雄人物。", s: "《宋书·武帝纪》刘讳足为一世之雄。”宋·苏轼《前赤壁赋》固一世之雄也，而今安在哉！”" },
  { w: "一举一动", p: ["yī", "jǔ", "yī", "dòng"], e: "指人的每一个动作。", s: "清·李汝珍《镜花缘》第七十四回可见古人一举一动，莫不令人归于正道，就是游戏之中，也都寓著劝世之意。”" },
  { w: "一之为甚", p: ["yī", "zhī", "wéi", "shèn"], e: "做了一次，已经过分。比喻错误不能重犯。同一之谓甚”。", s: "元·侯克中《归兴》诗一之为甚其能再，二者何由可得兼。”" },
  { w: "一之已甚", p: ["yī", "zhī", "yǐ", "shèn"], e: "做了一次，已经过分。比喻错误不能重犯。同一之谓甚”。", s: "唐·任蕃《梦游录·张生》酒至白面少年，复请歌。张妻曰‘一之已甚，其可再乎？’”" },
  { w: "一之谓甚", p: ["yī", "zhī", "wèi", "shèn"], e: "甚过分。做了一次，已经过分。比喻错误不能重犯。", s: "《左传·僖公五年》晋不可启，寇不可玩。一之谓甚，其可再乎？”" },
  { w: "一事不知", p: ["yī", "shì", "bù", "zhī"], e: "比喻知识尚有欠缺。同一物不知”。", s: "《南史·隐逸传·陶弘景》读书万余卷，一事不知，以为深耻。”" },
  { w: "一事无成", p: ["yī", "shì", "wú", "chéng"], e: "连一样事情也没有做成。指什么事情都做不成。形容毫无成就。", s: "唐·白居易《除夜寄微之》诗鬓毛不觉白毵毵，一事无成百不堪。”" },
  { w: "一五一十", p: ["yī", "wú", "yī", "shí"], e: "五、十计数单位。五个十个地将数目点清。比喻叙述从头到尾，源源本本，没有遗漏。也形容查点数目。", s: "明·施耐庵《水浒全传》第二十五回这妇人听了这话，也不回言，却踅过来，一五一十，都对王婆和西门庆说了。”" },
  { w: "一人之交", p: ["yī", "rén", "zhī", "jiāo"], e: "亲密得象一个人。形容交情深。", s: "清·吴敬梓《儒林外史》第五十四回那时我家先父就和娄氏弟兄是一人之交。”" },
  { w: "一人有庆", p: ["yī", "rén", "yǒu", "qìng"], e: "常用为歌颂帝王德政之词。", s: "《尚书·吕刑》一人有庆，兆民赖之，其宁惟永。”" },
  { w: "一介不取", p: ["yī", "jiè", "bù", "qǔ"], e: "一介一粒芥菜子，形容微小。一点儿小东西也不拿。形容廉洁、守法，不是自己应该得到的一点都不要。", s: "《孟子·万章上》其非义也，非其道也，一介不以与人，一介不以取诸人。”" },
  { w: "一以当十", p: ["yī", "yǐ", "dāng", "shí"], e: "当相当。一个人抵挡十个人。形容军队英勇善战。", s: "《战国策·齐策一》一而当十，十而当百，百而当千。”《史记·项羽本纪》楚战士无不一以当十，楚兵呼声动天，诸侯军无不人人惴恐。”" },
  { w: "一以当百", p: ["yī", "yǐ", "dāng", "bǎi"], e: "一人抵过百人。极言勇猛。", s: "清·李渔《比目鱼》第十四回楚玉也自领全军杀将前去。及至两不相对，真个人强马壮，一以当百。杀得那些山贼，抱头而窜。”" },
  { w: "一以贯之", p: ["yī", "yǐ", "guàn", "zhī"], e: "贯贯穿。用一个根本性的事理贯通事情的始末或全部的道理。", s: "《论语·里仁》子曰‘参乎！吾道一以贯之’曾子曰‘唯。’子出，门人问曰‘何谓也？’曾子曰‘夫子之道，忠恕而已矣。’”" },
  { w: "一体同心", p: ["yī", "tǐ", "tóng", "xīn"], e: "一体一个整体；同心齐心。比喻关系密切，共同一心。", s: "《仪礼·丧服》父子一体也，夫妻一体也，昆弟一体也。”《周易·系辞上》二人凡心，其利断金；同心之言，其臭如兰。”" },
  { w: "一偏之见", p: ["yī", "piān", "zhī", "jiàn"], e: "偏于一面的见解。", s: "《宋史·刘述传》安石任一偏之见，改立新议，以害天下大公。”" },
  { w: "一偏之论", p: ["yī", "piān", "zhī", "lùn"], e: "偏于一面的议论。", s: "宋·朱熹《答沈叔晦书》前日务为学而不观书，此固一偏之论。”" },
  { w: "一元大武", p: ["yī", "yuán", "dà", "wǔ"], e: "指古时祭祀用的牛。", s: "《礼记·曲礼下》凡祭宗庙之礼，牛曰一元大武。”" },
  { w: "一分一毫", p: ["yī", "fēn", "yī", "háo"], e: "形容很少的数量。", s: "朱自清《给亡妇》那里有一分一毫想着你自己。”" },
  { w: "一卧不起", p: ["yī", "wò", "bù", "qǐ"], e: "指一生病就没有好转。", s: "元·郑光祖《倩女离魂》第二折自从倩女孩儿在折柳亭与王秀才送路，辞别回家，得其疾病，一卧不起。”" },
  { w: "一反其道", p: ["yī", "fǎn", "qí", "dào"], e: "一整个，完全；反相反；其他的；道轨道。完全与以前的轨道相反。", s: "" },
  { w: "一口一声", p: ["yī", "kǒu", "yī", "shēng"], e: "犹口口声声。", s: "《金瓶梅词话》第七回西门庆那里肯，一口一声只叫‘姑娘请受礼。’”" },
  { w: "一国三公", p: ["yī", "guó", "sān", "gōng"], e: "公古代诸侯国君的通称。一个国家有三个主持政事的人。比喻事权不统一，使人不知道听谁的话好。", s: "《左传·僖公五年》一国三公，吾谁适从？”" },
  { w: "一坐一起", p: ["yī", "zuò", "yī", "qǐ"], e: "犹言一举一动。指人的每一个动作。", s: "《吴子·论将》观敌之来，一坐一起，其政以理，其追北佯为不及，其见利佯为不知，如此将者，名为智将。”" },
  { w: "一天一地", p: ["yī", "tiān", "yī", "dì"], e: "满天满地。形容到处都是。", s: "清·西周生《醒世姻缘传》第三十四回又兼狄家的觅汉伙伴不曾分得银钱的，心里气他不过，到处去彰扬，不止他本村扬说的一天一地，就是邻庄外县，都当了一件异事传说。”" },
  { w: "一夫之勇", p: ["yī", "fū", "zhī", "yǒng"], e: "犹言匹夫之勇。指不用智谋单凭个人的勇力。", s: "《三国志·魏志·荀彧传》颜良、文丑，一夫之勇耳，可一战而禽也。”" },
  { w: "一夫之用", p: ["yī", "fū", "zhī", "yòng"], e: "指仅能当一人之用，而无兼人之能。", s: "《后汉书·冯异传》异一夫之用，不足为强弱。”" },
  { w: "一孔不达", p: ["yī", "kǒng", "bù", "dá"], e: "指一窍不通。", s: "" },
  { w: "一孔之见", p: ["yī", "kǒng", "zhī", "jiàn"], e: "从一个小窟窿里所看到的。比喻狭隘片面的见解。", s: "汉·桓宽《盐铁论·相刺》持规而非矩，执准而非绳，通一孔，晓一理，而不知权衡。”" },
  { w: "一字不易", p: ["yī", "zì", "bù", "yì"], e: "文字精醇，一个字也不能更改。也用于指抄袭者一字不改地照抄别人的文章。", s: "《新唐书·文艺传中·孙逖》开元间，苏飂、齐澣、苏晋、贾曾、韩休、许景先及狄典诏诰，为代言最；而逖尤精密，张九龄视其草，欲易一字，卒不能也。”" },
  { w: "一字之师", p: ["yī", "zì", "zhī", "shī"], e: "改正一个字的老师。有些好诗文，经旁人改换一个字后更为完美，往往称改字的人为一字师”或一字之师”。", s: "宋·计有功《唐诗纪事》郑谷改僧齐己《早梅》诗‘数枝开’作‘一枝开’。齐己下拜，人以谷为一字师。”" },
  { w: "一定不易", p: ["yī", "dìng", "bù", "yì"], e: "易改变。原指一定下来就不变更，后形容事理正确，不可改变。", s: "《淮南子·主术训》今夫权衡规矩，一定而不易，不为秦楚变节，不为胡越改容。”" },
  { w: "一定不移", p: ["yī", "dìng", "bù", "yí"], e: "原指一定下来就不变更，后形容事理正确，不可改变。同一定不易”。", s: "清·李渔《闲情偶寄·词曲·音律》至于填词一道，则句之长短，字之多寡，声之平、上、去、入，韵之清浊阴阳，皆有一定不移之格。”" },
  { w: "一定之规", p: ["yī", "dìng", "zhī", "guī"], e: "一定的规律或规则。比喻已打定的主意。", s: "郭小川《新路歌》历史的发展，有它新陈代谢的一定之规。”" },
  { w: "一家一火", p: ["yī", "jiā", "yī", "huǒ"], e: "指所有家当什物。", s: "明·冯梦龙《古今小说》第五卷王媪嫁了马周，把自己一家一火，都搬到马家来了。”" },
  { w: "一家一计", p: ["yī", "jiā", "yī", "jì"], e: "指一夫一妻的家庭生活或财产。亦引申为一家人。", s: "元·关汉卿《窦娥冤》第二折别人怎生替得，寿数非于今世。相守三朝五夕，说甚一家一计。”" },
  { w: "一家之作", p: ["yī", "jiā", "zhī", "zuò"], e: "自成一家的著作。", s: "《宋书·范晔传》不得志，乃删众家《后汉书》为一家之作。”" },
  { w: "一家之学", p: ["yī", "jiā", "zhī", "xué"], e: "自成一家的学派。", s: "汉·司马迁《报任少卿书》亦欲以究天人之际，通古今之变，成一家之言。”汉·班固《典引》司马迁著书成一家之言。”" },
  { w: "一家之言", p: ["yī", "jiā", "zhī", "yán"], e: "指有独特见解自成体系的论著。", s: "汉·司马迁《报任少卿书》亦欲以究天人之际，通古今之变，成一家之言。”汉·班固《典引》司马迁著书成一家之言。”" },
  { w: "一家之计", p: ["yī", "jiā", "zhī", "jì"], e: "指一夫一妻的家庭。", s: "元·关汉卿《窦娥冤》第二折人命关天地，别人怎生替得？寿数非于今世，相守三朝五夕，说甚一家一计。”" },
  { w: "一家之辞", p: ["yī", "jiā", "zhī", "cí"], e: "指有独特见解自成体系的论著。同一家之言”。", s: "《晋书·裴顀传》观《老子》之书，虽博有所经，而云‘有生于无’，以虚为主，偏立一家之辞，岂有以而然哉！”" },
  { w: "一家无二", p: ["yī", "jiā", "wú", "èr"], e: "指一家之人没有两样。", s: "元·杨显之《潇湘雨》第一折这个女孩儿，也是有缘，我认了做义女，她自到我家来，倒也亲热，一家无二。”" },
  { w: "一射之地", p: ["yī", "shè", "zhī", "dì"], e: "一箭所能达到的距离，约当一百二十至一百五十步。", s: "元·王实甫《西厢记》第二本第二折将军若要做女婿呵，可按甲束兵，退一射之地。”" },
  { w: "一尘不到", p: ["yī", "chén", "bù", "dào"], e: "形容清净纯洁。", s: "唐·唐彦谦《游清凉寺》诗一尘不到心源净，万有俱空眼界清。”" },
  { w: "一己之私", p: ["yī", "jǐ", "zhī", "sī"], e: "指个人的私心、私利。", s: "宋·李格非《书洛阳名园记后》放乎一己之私，自为之而忘天下之治，忽欲退享此得乎？”" },
  { w: "一己之见", p: ["yī", "jǐ", "zhī", "jiàn"], e: "指一个人的意见。", s: "宋·周煇《清波杂志》卷八近时曾公端伯亦编皇宋百家诗选，去取任一己之见。”" },
  { w: "一席之地", p: ["yī", "xí", "zhī", "dì"], e: "放一个席位的地方。比喻应有的一个位置。", s: "《旧唐书·后妃传上》妇人智识不远，有忤盛情，然贵妃久承恩顾，何惜宫中一席之地，使其京戮，安忍取辱于外哉！”" },
  { w: "一年一度", p: ["yī", "nián", "yī", "dù"], e: "指每年一次。", s: "宋·王安石《送吴显道》诗之五惟有春风应最惜，一年一度一归来。”" },
  { w: "一式一样", p: ["yī", "shì", "yī", "yàng"], e: "完全是一个式样。形容完全相同。", s: "清·李宝嘉《官场现形记》第二十九回佘道台见了这副神气，更觉得同花小红一式一样，毫无二致。”" },
  { w: "一往无前", p: ["yī", "wǎng", "wú", "qián"], e: "一直往前，无所阻挡。形容勇猛无畏地前进。", s: "毛泽东《论联合政府》这个军队具有一往无前的精神，它要压倒一切敌人，而决不被敌人所屈服。”" },
  { w: "一得之功", p: ["yī", "dé", "zhī", "gōng"], e: "一得一点心得，一点收获；功成绩。一点微小的成绩。", s: "" },
  { w: "一得之愚", p: ["yī", "dé", "zhī", "yú"], e: "指自己对某件事的一点看法。", s: "《史记·淮阴侯列传》智者千虑，必有一失，愚者千虑，必有一得。”" },
  { w: "一得之见", p: ["yī", "dé", "zhī", "jiàn"], e: "见见解。谦虚的说法，指自己对某个问题的见解。", s: "《史记·淮阴侯列传》臣闻智者千虑，必有一失；愚者千虑，必有一得。”" },
  { w: "一德一心", p: ["yī", "dé", "yī", "xīn"], e: "德心意。大家一条心，为一个共同目标而努力。", s: "《尚书·泰誓中》乃一德一心，立定厥功，惟克永世。”" },
  { w: "一心一力", p: ["yī", "xīn", "yī", "lì"], e: "犹同心协力。团结一致，共同努力。", s: "清·魏源《圣武记》卷九自阖营将弁，以及士卒，无不一心一力。”" },
  { w: "一心一德", p: ["yī", "xīn", "yī", "dé"], e: "大家一条心，为一个共同目标而努力。", s: "《书·泰誓中》乃一德一心，立定厥功，惟克永世。”" },
  { w: "一心一意", p: ["yī", "xīn", "yī", "yì"], e: "只有一个心眼儿，没有别的考虑。", s: "《三国志·魏志·杜恕传》免为庶人，徙章武郡，是岁嘉平元年。”裴松之注引《杜氏新书》故推一心，任一意，直而行之耳。”" },
  { w: "一心一腹", p: ["yī", "xīn", "yī", "fù"], e: "指一条心。", s: "赵树理《三里湾》十六你们那家里不论什么时候都是一心一腹的——也不论公公、婆婆、弟兄们、小姑子，忙起来大家忙，吃起来大家吃，穿起来大家穿，谁也不偏这个不为那个。”" },
  { w: "一心一计", p: ["yī", "xīn", "yī", "jì"], e: "一心一意。", s: "《三国志·魏志·杜恕传》免为庶人，徙章武郡，是岁嘉平元年。”裴松之注引《杜氏新书》故推一心，任一意，直而行之耳。”" },
  { w: "一心一路", p: ["yī", "xīn", "yī", "lù"], e: "犹一心一意。只有一个心眼儿，没有别的考虑。", s: "明·冯梦龙《挂枝儿·多心》初相交，指望你一心一路；到如今，眼面上做工夫。”" },
  { w: "一心同体", p: ["yī", "xīn", "tóng", "tǐ"], e: "犹言同心同德。指思想统一，信念一致。", s: "明·吴承恩《西游记》第三十二回话说唐僧复得了孙行者，师徒们一心同体，共诣西方。”" },
  { w: "一心同功", p: ["yī", "xīn", "tóng", "gōng"], e: "同心协力，共赴事功。", s: "《战国策·中山策》当此之时，秦中士卒，以军中为家，将帅为父母，不约而亲，不谋而信，一心同功，死不旋踵。”" },
  { w: "一心同归", p: ["yī", "xīn", "tóng", "guī"], e: "齐心趋向同一目的。", s: "《淮南子·泰族训》上唱而民和，上动而下随，四海之内，一心同归。”" },
  { w: "一心无二", p: ["yī", "xīn", "wú", "èr"], e: "指一心一意地做某种事情，没有杂念。", s: "《旧唐书·张巡传》诸公为国家戮力守城，一心无二，经年乏食，忠义不衰。”" },
  { w: "一成一旅", p: ["yī", "chéng", "yī", "lǚ"], e: "成古时以方圆十里为一成；旅古时以兵士五百人为一旅。形容地窄人少，力量单薄。", s: "《左传·哀公元年》有田一成，有众一旅，能布其德，而兆其谋，以收夏众，抚其官职。”" },
  { w: "一成不变", p: ["yī", "chéng", "bù", "biàn"], e: "成制定，形成。一经形成，不再改变。", s: "《礼记·王制》一成而不可变，故君子尽心焉。”" },
  { w: "一成不易", p: ["yī", "chéng", "bù", "yì"], e: "一经形成，不再改变。同一成不变”。", s: "《明史·历志一》夫天之行度多端，而人之智力有限……惟合古今人之心思，踵事增修，庶几符合。故不能为一成不易之法也。”" },
  { w: "一手一足", p: ["yī", "shǒu", "yī", "zú"], e: "一个人的手足。指单薄的力量。", s: "《礼记·表记》后稷天下之为烈也，岂一手一足哉？”" },
  { w: "一技之长", p: ["yī", "jì", "zhī", "cháng"], e: "技技能，本领；长擅长、长处。指有某种技能或特长。", s: "清·郑燮《郑板桥集·家书·淮安舟中寄舍弟墨》愚兄平生漫骂无礼，然人有一才一技之长，一行一言之美，未尝不啧啧称道。”" },
  { w: "一拥而上", p: ["yī", "yōng", "ér", "shàng"], e: "一下子全都围上去。形容周围的人同时向一个目标猛挤过去。", s: "明·罗贯中《三国演义》第六十七回吕蒙亲自擂鼓，士卒皆一拥而上，乱刀砍死朱光。”" },
  { w: "一文不值", p: ["yī", "wén", "bù", "zhí"], e: "指毫无价值。", s: "明·毕魏《三报恩·骂佞》最可悲年少科名，弄得一文不值。”" },
  { w: "一文不名", p: ["yī", "wén", "bù", "míng"], e: "名占有。一个钱都没有。形容非常贫困。", s: "西汉·司马迁《史记·佞幸列传》竟不得名一钱，寄死人家。”" },
  { w: "一文如命", p: ["yī", "wén", "rú", "mìng"], e: "把一文钱看得象性命那样重。比喻极端吝啬。同一钱如命”。", s: "清·吴敬梓《儒林外史》第五十二回此人有个毛病，啬细非常，一文如命。”" },
  { w: "一方之任", p: ["yī", "fāng", "zhī", "rèn"], e: "负一方面责任的职务。", s: "《汉书·终军传》不足以亢一方之任，窃不胜愤懑。”" },
  { w: "一无可取", p: ["yī", "wú", "kě", "qǔ"], e: "没有一点儿可以肯定的地方。", s: "明·冯梦龙《醒世恒言·卢太学诗酒傲王侯》心中大怒道‘原来这俗物，一无可取，都只管来缠帐，几乎错认了。”" },
  { w: "一无所取", p: ["yī", "wú", "suǒ", "qǔ"], e: "原指一点都没拿◇也形容什么都未得到。", s: "《三国志·魏志·钟会传》裴松之注会前后赐钱帛数百万计，悉送供公家之用，一无所取。”" },
  { w: "一无所得", p: ["yī", "wú", "suǒ", "dé"], e: "什么也没有得到。形容毫无收获。", s: "五代·王定保《唐摭言》卷八然日势既暮，寿儿且寄院中止宿，颢亦怀疑，因命寿儿怀袖，一无所得，颢不得已遂躬自操觚。”" },
  { w: "一无所成", p: ["yī", "wú", "suǒ", "chéng"], e: "一点没有成就。", s: "清·黄遵楷《跋》读先兄病笃之书，谓平生怀抱，一无所成，惟近古体诗能自立耳。”" },
  { w: "一无所有", p: ["yī", "wú", "suǒ", "yǒu"], e: "什么也没有。指钱财，也指成绩、知识。", s: "《敦煌变文集·庐山远公话》如水中之月，空里之风，万法皆无，一无所有。”" },
  { w: "一无所求", p: ["yī", "wú", "suǒ", "qiú"], e: "指没有什么要求或需要。", s: "清·文康《儿女英雄传》第16回要我给她遮掩个门户；此外一无所求。”" },
  { w: "一无所知", p: ["yī", "wú", "suǒ", "zhī"], e: "什么也不知道。", s: "明·冯梦龙《警世通言》卷十五小学生望后便倒，扶起，良久方醒。问之一无所知。”" },
  { w: "一无所能", p: ["yī", "wú", "suǒ", "néng"], e: "什么能耐也没有。", s: "清·钱泳《履园丛话·杂记上·定数》又苏州叶某者，性迂拙，一无所能，其父死，既无产业，且有逋负。”" },
  { w: "一无所获", p: ["yī", "wú", "suǒ", "huò"], e: "一无全无。什么东西都没有获得。", s: "五代·王定保《唐摭言》然日势既暮，寿儿且寄院中止宿，颢亦怀疑，因命搜寿儿怀袖，一无所得，颢不得已遂躬自操觚。”" },
  { w: "一无所长", p: ["yī", "wú", "suǒ", "cháng"], e: "没有一点儿专长。", s: "清·吴趼人《二十年目睹之怪现状》第九十回那日记当中，提到他那位叶妹夫，便说他年轻而纨裤习气太重，除应酬外，乃一无所长，又性根未定，喜怒无常云云。”" },
  { w: "一无所闻", p: ["yī", "wú", "suǒ", "wén"], e: "一点也没有听说，丝毫也不知道。", s: "" },
  { w: "一无是处", p: ["yī", "wú", "shì", "chù"], e: "是对，正确。没有一点儿对的或好的地方。", s: "明·张岱《与胡季望》是犹三家村子，使之治山珍海错，烹饪燔炙，一无是处。明眼观之，只发一粲。”" },
  { w: "一无长物", p: ["yī", "wú", "cháng", "wù"], e: "一无全无；长物多余的东西。除一身之外再没有多余的东西。原指生活俭朴。现形容贫穷。", s: "《晋书·王恭传》吾平生无长物。”" },
  { w: "一日之长", p: ["yī", "rì", "zhī", "zhǎng"], e: "年龄大或资格老的自谦说法。", s: "《论语·先进》子路、曾晳、冉有、公西华侍坐，子曰‘以吾一日长乎尔，毋吾以也。’”" },
  { w: "一日之雅", p: ["yī", "rì", "zhī", "yǎ"], e: "雅交往。指短暂的交往。指交情不深。", s: "《汉书·谷永传》永奏书谢凤曰‘永斗筲之材，质薄学朽，无一日之雅，左右之介。’”" },
  { w: "一时三刻", p: ["yī", "shí", "sān", "kè"], e: "指很短的时间。", s: "清·李渔《凰求凤·夥媒》机缘凑，把愁肠暂丢，便难成，也一时三刻展眉头。”" },
  { w: "一时之权", p: ["yī", "shí", "zhī", "quán"], e: "暂时的权宜。", s: "《韩非子·难一》文公之霸也宜哉！既知一时之权，又知万世之利。”《淮南子·人间训》文公曰‘咎犯之言，一时之权也；雍季之言，万世之利也，吾岂可以先一时之权而后万世之利哉！’”" },
  { w: "一时之秀", p: ["yī", "shí", "zhī", "xiù"], e: "一个时期的优秀人物。亦作一时之选”。", s: "《周书·唐瑾传》时六尚书皆一时之秀，周文自谓得人，号为六俊。”明·冯梦龙《醒世恒言》第二十四卷后主问帝‘萧妃何如此人？’帝曰‘春兰秋菊，各一时之秀也。’”" },
  { w: "一时之选", p: ["yī", "shí", "zhī", "xuǎn"], e: "指某一时期的优秀人才。", s: "《新唐书·韦抗传》它所辟举，如王维、王缙、崔殷等，皆一时选云。”宋·曾巩《〈范宽之奏议集〉序》其所引拔以言为职者，如公，皆一时之选。”" },
  { w: "一晦一明", p: ["yī", "huì", "yī", "míng"], e: "一暗一明。常指昼夜循环。", s: "《庄子·田子方》消息满虚，一晦一明，日改月化。”《淮南子·兵略训》一晦一明，孰知其端绪。”" },
  { w: "一望而知", p: ["yī", "wàng", "ér", "zhī"], e: "一看就明白。", s: "清·李绿园《歧路灯》又说了一回话，大约言语甜俗，意味粗浅，中藏早是一望而知的。”" },
  { w: "一朝之患", p: ["yī", "zhāo", "zhī", "huàn"], e: "突然发生的祸患。", s: "《礼记·檀弓上》故君子有终身之忧，而无一朝之患，故忌日不乐。”汉·赵晔《吴越春秋·阖闾内传》楚国苦之，群臣皆怨，咸言费无忌谗杀伍奢、白州犁而吴侵境不绝于寇，楚国群臣有一朝之患。”" },
  { w: "一来一往", p: ["yī", "lái", "yī", "wǎng"], e: "形容动作的反复或交替。", s: "明·吴承恩《西游记》第六十七回行者暗笑道‘好是耳聋口哑！不要走！看棍！’那怪更不怕，乱舞枪遮拦。在那半空中，一来一往，一上一下，斗到三更时分，未见胜败。”" },
  { w: "一来二去", p: ["yī", "lái", "èr", "qù"], e: "指一回又一回，经过一段时间。表示逐渐的意思。", s: "清·曹雪芹《红楼梦》第五十八回一来二去，两个人就装糊涂了，倒象真的一样儿。”" },
  { w: "一死一生", p: ["yī", "sǐ", "yī", "shēng"], e: "指有关生死的关键时刻。", s: "《史记·汲郑列传》太史公曰始翟公为廷尉，宾客阗门；及废，门外可设雀罗。翟公复为廷尉，宾客欲往，翟公乃大署其门曰‘一死一生，乃知交情。’”" },
  { w: "一清二白", p: ["yī", "qīng", "èr", "bái"], e: "比喻十分清白。亦比喻非常清楚。", s: "茅盾《劫后拾遗》四你还不相信我吗？我在这里混了这半年，素来一清二白。”周立波《暴风骤雨》第一部七我姓韩的桥是桥，路是路，一清二白的，怕谁来歪我不成。”" },
  { w: "一清如水", p: ["yī", "qīng", "rú", "shuǐ"], e: "清·清澈。像流水一样清澈。形容为官廉洁，不贪污、不受贿。也形容十分清洁。", s: "明·周楫《西湖二集·祖统制显灵救驾》你在衙门中一清如水，朝廷知你是个个廉吏，异日定来聘你为官。”" },
  { w: "一物不知", p: ["yī", "wù", "bù", "zhī"], e: "对某一事物有所不知。比喻知识尚有欠缺。", s: "汉·扬雄《法言·君子》圣人之于天下，耻一物之不知。”" },
  { w: "一生一世", p: ["yī", "shēng", "yī", "shì"], e: "一辈子。", s: "清·曹雪芹《红楼梦》第九十三回他倒拿定一个主意说是人生婚配，关系一生一世的事，不是混闹得的。”" },
  { w: "一生一代", p: ["yī", "shēng", "yī", "dài"], e: "指一辈子。同一生一世”。", s: "唐·骆宾王《代女道士王灵妃赠道士李荣》诗相怜相念倍相亲，一生一代一双人。”" },
  { w: "一病不起", p: ["yī", "bìng", "bù", "qǐ"], e: "得病后就再也起不了床。比喻得病后病情一天天恶化，终至死亡。", s: "宋·洪迈《夷坚乙志·光禄寺》蒋安礼为光禄丞，斋宿寺舍，因喷嚏，鼻涕堕桌上，皆成小木人，雕刻之工极精，揽取之则已失矣，顷之复尔。凡堕木人千百，蒋一病不起。”" },
  { w: "一目之士", p: ["yī", "mù", "zhī", "shì"], e: "指见解片面，不能看到事物整体的人。", s: "清·李慈铭《越缦堂读书记·志雅堂杂抄》此书成于元代，道学之风甚盛，而能为是言，此是非之公也。近世一目之士，动以诋斥宋儒为莫逭之罪，亦愚甚矣。”" },
  { w: "一目十行", p: ["yī", "mù", "shí", "háng"], e: "看书时同时可以看十行。形容看书非常快。", s: "《梁书·简文帝纪》读书十行俱下。”宋·刘克庄《杂记六言五首》诗五更三点待漏，一目十行读书。”" },
  { w: "一相情原", p: ["yī", "xiāng", "qíng", "yuán"], e: "指单方面的愿望或不考虑客观实际情况的主观意愿。亦作一厢情原”。", s: "" },
  { w: "一笑了事", p: ["yī", "xiào", "le", "shì"], e: "笑一笑就算了事，指不予重视。同一笑了之”。", s: "清·李宝嘉《官场现形记》第四十六回抚台听了，先还摸不着头脑，还以为某人办事不诚实，所以钦差才加了他这个考语；后来别位司、道说起，晓得是为带着表，方才付之一笑了事。”" },
  { w: "一箭之地", p: ["yī", "jiàn", "zhī", "dì"], e: "相当于一箭射程的距离。比喻相距不远。", s: "明·施耐庵《水浒全传》第九十回宋江上得马来，前行的众头领，已去了一箭之地，见宋江和贯忠说话，都勒马伺候。”" },
  { w: "一缘一会", p: ["yī", "yuán", "yī", "huì"], e: "指有缘相合。", s: "明·冯梦龙《古今小说·新桥市韩五卖春情》吴山道‘拜问娘子青春？’小妇人道‘与官人一缘一会，奴家也是二十四岁。’”" },
  { w: "一臂之力", p: ["yī", "bì", "zhī", "lì"], e: "臂胳膊。指一部分力量或不大的力量。表示从旁帮一点忙。", s: "元·李寿卿《伍员吹箫》第三折若得此人助我一臂之力，愁甚冤仇不报。”" },
  { w: "一至于此", p: ["yī", "zhì", "yú", "cǐ"], e: "竟到如此地步。", s: "南朝·梁·简文帝《与湘东王书》笔札无情，任其摇礸。甚矣哉！文之横流，一至于此！”" },
  { w: "一般无二", p: ["yī", "bān", "wú", "èr"], e: "完全一样，没有不同的地方。", s: "明·吴承恩《西游记》第三十五回纵是一根藤上结的，也有个大小不同，偏正不一，却怎么一般无二？”" },
  { w: "一虎不河", p: ["yī", "hǔ", "bù", "hé"], e: "原指空手搏虎，徒步渡河，比喻有勇无谋，冒险行事◇在元剧中比喻不顾一切。", s: "《诗·小雅·小昮》不敢暴虎，不敢冯河。”《论语·述而》暴虎冯河，死而无悔者，吾不与也。必也临事而惧，好谋而成者也。”" },
  { w: "一表人才", p: ["yī", "biǎo", "rén", "cái"], e: "表指外貌。形容人容貌俊秀端正。", s: "元·关汉卿《望江亭》第一折夫人，放着你这一表人物，怕没有中意的丈夫？”" },
  { w: "一表人材", p: ["yī", "biǎo", "rén", "cái"], e: "形容容貌英俊。表，仪表。", s: "明·刘璋《飞花艳想》第一回友梅生得一表人材，美如冠玉，又且颖悟过人，做的文章，便篇篇锦绣，字字珠玑，十五岁上，就领了钱塘县学批首。”" },
  { w: "一表人物", p: ["yī", "biǎo", "rén", "wù"], e: "形容容貌英俊。表，仪表。", s: "元·郑光祖《倩女离魂》第一折（梅香云）姐姐，那王秀才生的一表人物，聪明浪子，论姐姐这个模样，正和王秀才是一对儿。”元·关汉卿《望江亭》第一折夫人，放着你这一表人物，怕没有中意的丈夫？”" },
  { w: "一见了然", p: ["yī", "jiàn", "liǎo", "rán"], e: "犹一目了然。一眼就看得很清楚。", s: "元·陈栎《勤有堂随录》程泰之《禹贡图》，不惬人意，不能使人一见了然。”" },
  { w: "一见如故", p: ["yī", "jiàn", "rú", "gù"], e: "故老朋友。初次见面就象老朋友一样合得来。", s: "《左传·襄公二十九年》见子产，如旧相识。”宋·张洎《贾氏谭录》李邺侯（泌）为相日，吴人顾况西游长安，邺侯一见如故。”" },
  { w: "一见如旧", p: ["yī", "jiàn", "rú", "jiù"], e: "初次见面就情投意合，如同老朋友一样。", s: "《新唐书·房玄龄传》太宗以敦煌公徇渭北，策杖上谒军门，一见如旧。”" },
  { w: "一言不发", p: ["yī", "yán", "bù", "fā"], e: "一句话也不说。", s: "明·冯梦龙《喻世明言》卷一三巧儿听说丈夫把她休了，一言不发，啼哭起来。”" },
  { w: "一言两语", p: ["yī", "yán", "liǎng", "yǔ"], e: "为数不多的几句话。", s: "《玉娇梨》第二回倒只愁儿子无真实之才，恐怕一言两语露出马脚。”" },
  { w: "一语中人", p: ["yī", "yǔ", "zhòng", "rén"], e: "中中伤。以一句话中伤人。", s: "" },
  { w: "一身五心", p: ["yī", "shēn", "wǔ", "xīn"], e: "比喻杂念很多。", s: "汉·焦延寿《易林》卷一三人异趋，反复迷惑。一身五心，乱无所得。”" },
  { w: "一迎一和", p: ["yī", "yíng", "yī", "hé"], e: "指一味迎合。", s: "元·无名氏《盆儿鬼》第二折也是你不合去杀人处，一迎一合。”" },
  { w: "一钱不名", p: ["yī", "qián", "bù", "míng"], e: "指身无分文。常以形容囊橐一空或甚为贫穷。", s: "清·吴趼人《糊涂世界》第十二回岑其身道‘我也本来打算早办，只是大嫂同舍妹要在家多停几日。又兼我是一钱不名，还要张罗几文才能办事，因此耽搁下来。’”" },
  { w: "一长一短", p: ["yī", "cháng", "yī", "duǎn"], e: "形容说话絮叨，琐谈不休。", s: "清·曹雪芹《红楼梦》第25回王夫人便一长一短问他今日是那几位堂客，戏文好歹，酒席如何。”" },
  { w: "一门同气", p: ["yī", "mén", "tóng", "qì"], e: "指同门兄弟。", s: "明·吴承恩《西游记》第六十三回他是我一门同气，我怎么不与他出力辨明冤枉。”" },
  { w: "一隅之地", p: ["yī", "yú", "zhī", "dì"], e: "隅角落。形容地域狭小。", s: "《南史·王弘传论》晋自中原沸腾，介居江左，以一隅之地，抗衡上国。”" },
  { w: "一隅之见", p: ["yī", "yú", "zhī", "jiàn"], e: "见见解。偏于一方面的见解。", s: "《论语·述尔》举一隅不以三隅反，则不复也。”" },
  { w: "一隅之说", p: ["yī", "yú", "zhī", "shuō"], e: "片面的说法；偏见。", s: "《后汉书·王充等传论》数子之言当世失得皆究矣，然多谬通方之训，好申一隅之说。”李贤注一隅谓一方偏见也。”" },
  { w: "一面之交", p: ["yī", "miàn", "zhī", "jiāo"], e: "只见过一面的交情。比喻交情很浅。", s: "汉·崔寔《本论》且观世人之相论也，徒以一面之交，定臧否之决。”" },
  { w: "一面之缘", p: ["yī", "miàn", "zhī", "yuán"], e: "见一面的缘分。", s: "清·曹雪芹《红楼梦》第一回若问此物，倒有一面之缘。”" },
  { w: "一面之识", p: ["yī", "miàn", "zhī", "shí"], e: "指只见过一面，略有认识。", s: "《宋史·范纯仁传》范纯仁，得一面识足矣。”" },
  { w: "一面之词", p: ["yī", "miàn", "zhī", "cí"], e: "争执的双方中一方所说的话。", s: "明·罗贯中《三国演义》第一百五回今日若听此一面之词，杨仪等必投魏矣。”" },
  { w: "一面之辞", p: ["yī", "miàn", "zhī", "cí"], e: "争执的双方中一方所说的话。指单方面的话，版面的看法。", s: "明·罗贯中《三国演义》第一百五回今日若听此一面之词，杨仪等必投魏矣。”" },
  { w: "一面之雅", p: ["yī", "miàn", "zhī", "yǎ"], e: "只见过一面的交情。比喻交情很浅。同一面之交”。", s: "田汉《关汉卿》第七场女的我不认识，跟这关汉卿倒有一面之雅。”" },
  { w: "一饭之德", p: ["yī", "fàn", "zhī", "dé"], e: "比喻微小的恩德。", s: "西汉·司马迁《史记·范雎蔡泽列传》范雎于是散家财物，尽以报所尝困厄者。一饭之德必偿，睚眦之怨必报。”" },
  { w: "万不失一", p: ["wàn", "bù", "shī", "yī"], e: "形容绝对不会出差错。同万无一失”。", s: "《韩非子·解老》治乡治邦莅天下者，各以此科适观息耗则万不失一。”《史记·淮阴侯列传》韩信曰‘先生相人何如？’对曰‘贵贱在于骨法，忧喜在于容色，成败在于决断，以此参之，万不失一。’”" },
  { w: "万不得已", p: ["wàn", "bù", "dé", "yǐ"], e: "表示无可奈何，不得不如此。", s: "明·冯梦龙《喻世明言》第十八卷娘子不须挂怀，三载夫妻，恩情不浅，此去也是万不得已，一年半载，便得相逢也。”" },
  { w: "万世一时", p: ["wàn", "shì", "yī", "shí"], e: "万世才有这么一个机会。形容机会难得。", s: "《史记·吴王濞列传》慧星出，蝗虫数起，此万世一时，而愁劳圣人之所起也。”" },
  { w: "万人之敌", p: ["wàn", "rén", "zhī", "dí"], e: "敌对抗。指武艺高强可敌强敌。也指善于统帅军队以抵御强敌。亦作万人敌”。", s: "" },
  { w: "万无一失", p: ["wàn", "wú", "yī", "shī"], e: "失差错。指非常有把握，绝对不会出差错。", s: "《史记·淮队侯列传》以此参之，万不失一。”汉·枚乘《七发》孔老览观，孟子持筹而算之，万不失一。”" },
  { w: "万象更新", p: ["wàn", "xiàng", "gēng", "xīn"], e: "万象宇宙间一切景象；更变更。事物或景象改换了样子，出现了一番新气象。", s: "清·曹雪芹《红楼梦》第七十回如今正是初春时节，万物更新，正该鼓舞另立起来才好。”" },
  { w: "三人为众", p: ["sān", "rén", "wéi", "zhòng"], e: "数目达到三人即可称为众人，已不算少数。", s: "《汉书·高惠高后文功臣表序》三人为众，虽难尽继，宜从尤功。”" },
  { w: "三人成虎", p: ["sān", "rén", "chéng", "hǔ"], e: "三个人谎报城市里有老虎，听的人就信以为真。比喻说的人多了，就能使人们把谣言当事实。", s: "《战国策·魏策二》夫市之无虎明矣，然而三人言而成虎。”" },
  { w: "三十三天", p: ["sān", "shí", "sān", "tiān"], e: "佛教称欲界第六天为三十三天，即忉利天◇形容最高的地方。", s: "《胜鬾宝窟》卷下此言三十三天者，中国言悉怛梨余恶卫陵，此中唯取怛梨二字为忉利天也。怛梨，忉利，彼国音不同耳。”" },
  { w: "三十而立", p: ["sān", "shí", "ér", "lì"], e: "指人在三十岁前后有所成就。", s: "《论语·为政》吾十有五而志于学，三十而立。”" },
  { w: "三夫之对", p: ["sān", "fū", "zhī", "duì"], e: "泛指经过多人传播的流言。同三夫之言”。", s: "《晋书·王瀎传》今臣之信行，未若曾参之著；而谗构沸腾，非徒三夫之对，外内扇助，为二五之应。”" },
  { w: "三夫之言", p: ["sān", "fū", "zhī", "yán"], e: "泛指经过多人传播的流言。", s: "《战国策·秦策二》昔者曾子处费，费人有与曾子同名族者而杀人，人告曾子母曰‘曾参杀人。’曾子母曰‘吾子不杀人。’织自若。有顷焉，人又曰‘曾参杀人。’其母尚织自若。顷之，一人又告之曰‘曾参杀人。’其母惧……”" },
  { w: "三心二意", p: ["sān", "xīn", "èr", "yì"], e: "又想这样又想那样，犹豫不定。常指不安心，不专一。", s: "元·关汉卿《救风尘》第一折争奈是匪妓，都三心二意。”" },
  { w: "上下一心", p: ["shàng", "xià", "yī", "xīn"], e: "上上下下一条心。", s: "《淮南子·诠言训》上下一心，君臣同志。”" },
  { w: "上下同心", p: ["shàng", "xià", "tóng", "xīn"], e: "上下一心。", s: "姚雪垠《李自成》第一卷第十七章自成虽然新遭大败，但此人百折不挠，锐意进取，加之重要将领均在，上下同心，亲密无向，又善于整饬军纪，救民之急，所以只要他喘息一下，重振旗鼓不难。”" },
  { w: "上下同门", p: ["shàng", "xià", "tóng", "mén"], e: "上下指上一辈与下一辈。姑婿与侄婿的互称。", s: "唐·赵璾《因话录》卷三杨仆射於陵在考功时，与李师稷及第。至其子相国嗣复知举，门生集候仆射，而李公在坐，时人谓之杨家上下门生。”自注代有姑之婿与侄之婿，谓之上下同门。”" },
  { w: "下落不明", p: ["xià", "luò", "bù", "míng"], e: "下落着落，去处。指不知道要寻找的人或物在什么地方。", s: "" },
  { w: "不一而足", p: ["bù", "yī", "ér", "zú"], e: "足充足。指同类的事物不只一个而是很多，无法列举齐全。", s: "《公羊传·文公九年》始有大夫，则何以不氏？许夷狄者，不一而足也。”" },
  { w: "不三不四", p: ["bù", "sān", "bù", "sì"], e: "指不正派，也指不象样子。", s: "明·施耐庵《水浒全传》第七回这伙人不三不四，又不肯近前来，莫不要攧洒家。”" },
  { w: "不上不下", p: ["bù", "shàng", "bù", "xià"], e: "上不去，下不来。形容进退两难。", s: "《庄子·达生》上而不下，则使人善怒；下而不上，则使人善忘；不上不下，中身当心，则为病。”" },
  { w: "不上不落", p: ["bù", "shàng", "bù", "luò"], e: "形容事情无着落，处境为难。", s: "《二刻拍案惊奇》卷九姐姐……何苦把这个书生哄得他不上不落的，呆呆地百事皆废了。”" },
  { w: "不世之业", p: ["bù", "shì", "zhī", "yè"], e: "不世非常、非凡。稀世罕有的功业。", s: "明·陈忱《水浒后传》第四十回宗兄威行海外，文武忠良成救驾之功，建不世之业。”" },
  { w: "不世之功", p: ["bù", "shì", "zhī", "gōng"], e: "不世不是每代都有的，即非常、非凡。形容功劳极大。", s: "《后汉书·隗嚣传》足下将建伊吕之业，弘不世之功。”" },
  { w: "不丰不杀", p: ["bù", "fēng", "bù", "shā"], e: "丰厚；杀减少。不奢侈也不啬俭。不增加也不减少。", s: "《礼记·礼器》礼不同，不丰不杀。”" },
  { w: "不义之财", p: ["bù", "yì", "zhī", "cái"], e: "不义不正当，不合理。不应该得到的或以不正当的手段获得的钱财。", s: "汉·刘向《列女传·齐田稷母传》不义之财，非吾有也，不孝之子，非吾子也。”" },
  { w: "不乏其人", p: ["bù", "fá", "qí", "rén"], e: "乏缺少；其那，那些。那样的人并不少。", s: "鲁迅《朝花夕拾·后记》但这种意见，恐怕是怀抱者不乏其人，而且由来已久的，不过大抵不敢毅然删改，笔之于书。”" },
  { w: "不二法门", p: ["bù", "èr", "fǎ", "mén"], e: "不二指不是两极端；法门佧行入道的门径。原为佛家语，意为直接入道，不可言传的法门◇比喻最好的或独一无二的方法。", s: "《维摩诘经·入不二法门品》如我意者，于一切法无言无说，无示无识，离诸问答，是为入不二法门。”" },
  { w: "不仁不义", p: ["bù", "rén", "bù", "yì"], e: "仁仁爱；义道义。不讲仁德，不讲道义。形容品性卑劣、残忍。", s: "宋·朱熹《朱子语类·大学三》害人与穿窬，因为不仁不义。”" },
  { w: "不今不古", p: ["bù", "jīn", "bù", "gǔ"], e: "指事物不正常，古代现代都不曾有过。原讥讽人学无所得却故作诡异◇常比喻折衷。", s: "汉·扬雄《太玄经·更》童牛角马，不今不古。”" },
  { w: "不伦不类", p: ["bù", "lún", "bù", "lèi"], e: "不伦不同类。既非这一类，又非那一类，形容成样子或没有道理。", s: "明·吴炳《疗炉羹·絮影》眼中人不伦不类，阱中人不伶不俐。”" },
  { w: "不偏不党", p: ["bù", "piān", "bù", "dǎng"], e: "不偏向任何一方。", s: "《吕氏春秋·士容论·士容》士不偏不党。”" },
  { w: "不做不休", p: ["bù", "zuò", "bù", "xiū"], e: "指事情既然开了头，就索性干到底。", s: "元·无名氏《马陵道》第四折俺如今拚的个不做不休，这就是至诚心为人为彻。”" },
  { w: "不僧不俗", p: ["bù", "sēng", "bù", "sú"], e: "犹言不三不四，不伦不类。", s: "《醒世恒言·张廷秀逃生救父》倘一时没眼色，配着个不僧不俗如醉如痴蠢物，岂不添了终身？”" },
  { w: "不冷不热", p: ["bù", "lěng", "bù", "rè"], e: "指温度不高不低，冷热适中。亦比喻对人态度一般。", s: "清·文康《儿女英雄传》第三十五回便见他一只手高高儿的举了一碗熬得透、得到不冷不热、温凉适中、可口儿的普洱茶来。”巴金《寒夜》三这一天是这个山城里少有的不冷不热的好天。”" },
  { w: "不刊之书", p: ["bù", "kān", "zhī", "shū"], e: "指不能更改或磨灭的有关帝王的记载、钦定典制。", s: "汉·扬雄《答刘歆书》是悬诸日月不刊之书也。”" },
  { w: "不刊之论", p: ["bù", "kān", "zhī", "lùn"], e: "刊削除，古代把字写在竹简上，有错误就削去。指正确的、不可修改的言论。", s: "宋·吴曾《能改斋漫录·议论》故中兴难于创业，是谓不刊之说”。" },
  { w: "不刊之说", p: ["bù", "kān", "zhī", "shuō"], e: "指正确的、不可修改的言论。", s: "宋·吴曾《能改斋漫录·议论》故中兴难于创业，是谓不刊之说”。" },
  { w: "不劳而成", p: ["bù", "láo", "ér", "chéng"], e: "不须劳苦就能有成就。", s: "《韩非子·外储说右下》因事之理则不劳而成，故兹郑之踞辕而歌以上高梁也。”" },
  { w: "不即不离", p: ["bù", "jí", "bù", "lí"], e: "即接近，靠近；离疏远，离开。指对人既不接近，也不疏远。多指对人似亲非亲、似疏非疏的关系。", s: "唐·羪宾《圆觉经》卷上不即不离，无缚无脱”" },
  { w: "不及之法", p: ["bù", "jí", "zhī", "fǎ"], e: "指不适用的法规。", s: "《庄子·拼拇》使天下簧鼓，以奉不及之法，非乎？”" },
  { w: "不古不今", p: ["bù", "gǔ", "bù", "jīn"], e: "指事物不正常，古代现代都不曾有过。原讥讽人学无所得却故作诡异◇常比喻折衷。", s: "汉·扬雄《太玄经·更》童牛角马，不今不古。”" },
  { w: "不可一世", p: ["bù", "kě", "yī", "shì"], e: "一世一时。认为当代的人都不行。形容目空一切、狂妄自大到了极点。", s: "宋·罗大经《鹤林玉露补遗》卷十五荆公少年，不可一世。”" },
  { w: "不可告人", p: ["bù", "kě", "gào", "rén"], e: "不能告诉别人。指见不得人。", s: "清·王无生《论小说与改变社会之关系》著诸书者，其人皆深极哀苦，有不可告人之隐，乃以委曲譬喻出之。”" },
  { w: "不可多得", p: ["bù", "kě", "duō", "dé"], e: "形容非常稀少，很难得到（多指人才或稀有物品）。", s: "汉·王充《论衡·超奇篇》譬珠玉不可多得，以其珍也。”" },
  { w: "不可思议", p: ["bù", "kě", "sī", "yì"], e: "原有神秘奥妙的意思。现多指无法想象，难以理解。", s: "《维摩诘所说经·不思议品》诸佛菩萨有解脱名不可思议。”" },
  { w: "不可理喻", p: ["bù", "kě", "lǐ", "yù"], e: "喻开导，晓喻。没法跟他讲道理。形容蛮横或固执。", s: "明·沈德符《万历野获编·褐盖》此辈不可理喻，亦不足深诘也。”" },
  { w: "不可终日", p: ["bù", "kě", "zhōng", "rì"], e: "终日从早到晚，一天。一天都过不下去。形容局势危急或心中极其恐慌不安。", s: "《礼记·表记》君子不以一日使其躬儳焉，如不终日。" },
  { w: "不可胜言", p: ["bù", "kě", "shèng", "yán"], e: "说不尽。形容非常多或到达极点。", s: "《史记·大宛列传》骞曰‘为汉使月氏，而为匈奴所闭道。今亡，唯王使人导送我。诚得至，反汉，汉之赂遗王财物不可胜言。’”" },
  { w: "不可胜记", p: ["bù", "kě", "shèng", "jì"], e: "不能逐一记述。极言其多。", s: "南朝·宋·傅亮《为宋公求加赠刘前军表》功隐于视听，不可胜记。”" },
  { w: "不可胜道", p: ["bù", "kě", "shèng", "dào"], e: "无法尽说。极言其多。", s: "《史记·太史公自序》海外殊俗，重译款塞，请来献见者，不可胜道。”" },
  { w: "不可言传", p: ["bù", "kě", "yán", "chuán"], e: "言言语。指对某些事理只能揣摩领悟，不能用言语来表达。", s: "宋·释道原《景德传灯录》卷二十五诸法寂灭相，不可以宣言，和尚如何为人？” 明·圆极居顶《续传灯录》卷二十四妙契不可以意到，真证不可以言传。”" },
  { w: "不可言喻", p: ["bù", "kě", "yán", "yù"], e: "喻说明，告知。不能用言语来说明。", s: "宋·沈括《梦溪笔谈·象数一》其术可以心得，不可言喻。”" },
  { w: "不可言宣", p: ["bù", "kě", "yán", "xuān"], e: "言言语；宣发表，表达。指不是言语所能表达的（用在说事物的奥妙、味道）。", s: "宋·释道原《景德传灯录》卷二十五诸法寂灭相，不可以宣言，和尚如何为人？”" },
  { w: "不可言状", p: ["bù", "kě", "yán", "zhuàng"], e: "言说；状描绘。无法用言语形容。", s: "晋·葛洪《神仙记·王远》衣有文采，又非锦绮，光彩耀目，不可名状。”" },
  { w: "不同戴天", p: ["bù", "tóng", "dài", "tiān"], e: "戴加在头上或用头顶着。不愿和仇敌在一个天底下并存。形容仇恨极深。", s: "《公羊传·庄公四年》讳与仇狩也”汉何休注《礼》，父母之仇，不同戴天。”" },
  { w: "不同流俗", p: ["bù", "tóng", "liú", "sú"], e: "流俗流行的习俗。与世俗习气不同。形容品德高尚。", s: "《礼记·射义》不从流俗。”" },
  { w: "不名一文", p: ["bù", "míng", "yī", "wén"], e: "名占有。一个钱也没有。形容极其贫穷。", s: "姚雪垠《李自成》第二卷第十六章老兄明白，弟半生书剑飘零，寄食江湖，囊中不名一文。”" },
  { w: "不名一格", p: ["bù", "míng", "yī", "gé"], e: "指不局限于一种规格或一个格局。", s: "清钱泳《履园丛话·收藏·元》有元一代画家，全讲气韵，不名一格，实能超出唐、宋人刻画之习。”" },
  { w: "不名一钱", p: ["bù", "míng", "yī", "qián"], e: "名占有。一个钱也没有。形容极其贫穷。", s: "《史记·佞幸列传》竟不得名一钱，寄死人家。”汉·王充《论衡·骨相》通有盗铸钱之罪，景帝考验，通亡，寄死人家，不名一钱。”" },
  { w: "不因不由", p: ["bù", "yīn", "bù", "yóu"], e: "犹言无意之中。", s: "《金瓶梅词话》第四九回西门庆不因不由，信步走入里面观看。”" },
  { w: "不因人热", p: ["bù", "yīn", "rén", "rè"], e: "因依靠『时梁鸿不趁他人热灶烧火煮饭。比喻为人孤僻高傲。也比喻不依赖别人。", s: "《东观汉记·梁鸿传》比舍先炊已，呼鸿及热釜炊¤曰‘童子鸿不因人热者也。’灭灶更燃火。”" },
  { w: "不在话下", p: ["bù", "zài", "huà", "xià"], e: "指事物轻微，或者理所当然，不值得一提。", s: "元·秦简夫《赵礼让肥》四折以下各随次第加官赐赏，这且不在话下。”" },
  { w: "不声不吭", p: ["bù", "shēng", "bù", "kēng"], e: "指不说话；不出声。", s: "王汶石《新结识的伙伴》还在半个月前，张腊月隐隐听说，南二社有个吴淑兰的妇女队长，在不声不吭地跟她暗赛。”" },
  { w: "不声不响", p: ["bù", "shēng", "bù", "xiǎng"], e: "指不说话；不出声。", s: "茅盾《子夜》十一偶或有独自低着头不声不响的，那一定是失败者。”" },
  { w: "不声不气", p: ["bù", "shēng", "bù", "qì"], e: "指不说话；不出声。", s: "周立波《山乡巨变》上一你们只想自己的爱人像旧式妇女一样，百依百顺，不声不气，来服侍你们。”" },
  { w: "不壹而三", p: ["bù", "yī", "ér", "sān"], e: "指再三；多次。", s: "《孔子家语·弟子行》子贡既与卫将军文子言。适鲁，见孔子曰‘卫将军文子问二三子之于赐，不壹而三焉。赐也辞，不获命；以所见者对矣。’”" },
  { w: "不夷不惠", p: ["bù", "yí", "bù", "huì"], e: "夷指伯夷；惠指柳下惠。不做伯夷也不学柳下惠。比喻折衷而不偏激。", s: "汉·扬雄《法官·渊骞》不夷不惠，可否之间也。”" },
  { w: "不好意思", p: ["bù", "hǎo", "yì", "sī"], e: "①表示碍于情面而只能怎样或不便怎样。②害羞；难为情。", s: "" },
  { w: "不如归去", p: ["bù", "rú", "guī", "qù"], e: "杜鹃鸟的叫声很象不如归去”。旧时常用以作思归或催人归去之辞。也表示消极求退。", s: "宋·梅尧臣《杜鹃》诗不如归去语，亦自古来传。”" },
  { w: "不存不济", p: ["bù", "cún", "bù", "jì"], e: "指支持不住，受不住。", s: "金·董解元《西厢记诸宫调》卷七不存不济，香肌瘦损，教俺萦方寸。”" },
  { w: "不学无术", p: ["bù", "xué", "wú", "shù"], e: "学学问；术技能。原指没有学问因而没有办法。现指没有学问，没有本领。", s: "《汉书·霍光传赞》然光不学亡术，暗于大理。”" },
  { w: "不学无识", p: ["bù", "xué", "wú", "shí"], e: "指没有学问，缺乏见识。", s: "宋·叶適《故枢密参政汪公墓志铭》大理少卿朱斐对上，指大理寺为诏狱。公论‘斐不自知职业何事，不学无识’，竟罢斐。”" },
  { w: "不安于位", p: ["bù", "ān", "yú", "wèi"], e: "指不喜欢自己的职业，不安心工作。", s: "《鲁迅书信集·致郑振铎》此公在厦门趋奉校长，颜膝可怜，适异己去后，而校长又薄其为人，终于不安于位，殊可笑也。”" },
  { w: "不容分说", p: ["bù", "róng", "fēn", "shuō"], e: "分说辩白，解说。不容人分辩解释。", s: "元·武汉臣《生金阁》三折怎么不由分说，便将我飞拳走踢只是打。”" },
  { w: "不干不净", p: ["bù", "gān", "bù", "jìng"], e: "指不洁净，肮脏。也指因忌讳而感觉不洁净。也可形容语文不文明。", s: "清·曹雪芹《红楼梦》第四十六回不干不净，也不知道毛病儿，买了来三日两日，又弄鬼掉猴的。”" },
  { w: "不当不正", p: ["bù", "dāng", "bù", "zhèng"], e: "不语助词，没有实际意思。表示端端正正。", s: "元·无名氏《渔樵记》第三折老汉也分开人丛，不当不正，站在那相公马前。”" },
  { w: "不当人子", p: ["bù", "dāng", "rén", "zǐ"], e: "表示歉意或感谢的话，意思是罪过，不敢当。", s: "明·冯梦龙《醒世恒言》卷十多谢厚情，只是无功受禄，不当人子，老汉转来，定当奉酬。”" },
  { w: "不徐不疾", p: ["bù", "xú", "bù", "jí"], e: "徐慢。疾快。不快不慢，从容自然。", s: "《庄子·天道》不徐不疾，得之于手，而应于心。”" },
  { w: "不得不尔", p: ["bù", "dé", "bù", "ěr"], e: "尔如此。不得不这样。表示为环境所迫或有难言之隐而无可奈何。", s: "《三国志·魏志·司马芝传》今诸典农，各言‘留者为行者宗田计，课其力，势不得不尔。’”" },
  { w: "不得人心", p: ["bù", "dé", "rén", "xīn"], e: "心心愿，愿望。得不到群众的支持拥护；得不到众人的好评。", s: "《旧唐书·哥舒翰传》先是，翰数奏禄山虽窃河朔，而不得人心，请持重以弊之，彼自离心，因而翦灭之，可不伤兵擒兹寇矣。”" },
  { w: "不得其所", p: ["bù", "dé", "qí", "suǒ"], e: "原指未得善终，后指没有得到适当的安顿。也指不能达到目的。", s: "《谷梁传·成公八年》媵，浅事也，不志。此其志何也？以伯姬之不得其所，故尽其事也。”" },
  { w: "不得其死", p: ["bù", "dé", "qí", "sǐ"], e: "指人不得好死。也表示对恶人的诅咒。", s: "《论语·先进》若由也，不得其死然。”" },
  { w: "不得而知", p: ["bù", "dé", "ér", "zhī"], e: "得能够。没有办法知道。", s: "《后汉书·桓谭传》盖天道性命，圣人所难言也。自子贡以下，不得而闻。”唐·韩愈《争臣论》故虽谏且议，使人不得而知焉。”" },
  { w: "不忙不暴", p: ["bù", "máng", "bù", "bào"], e: "态度纵容，不忙乱，不急躁。", s: "《董西厢》卷二不紧不慌，不惊不怕，不忙不暴。”" },
  { w: "不急之务", p: ["bù", "jí", "zhī", "wù"], e: "急急迫，要紧；务事情。无关紧要的或不急于做的事情。", s: "《三国志·吴书·孙和传》诚能绝无益之欲，以奉德义之涂，弃不急之务，以修功业之基，其于名行，岂不善哉。”" },
  { w: "不恤人言", p: ["bù", "xù", "rén", "yán"], e: "不管别人的议论。表示不管别人怎么说，还是按照自己的意思去做。", s: "《旧唐书·裴度传》大则以訏谟排祸难，小则以谠正匡过失，内不虑身计，外不恤人言，古人所难也。”" },
  { w: "不恶而严", p: ["bù", "è", "ér", "yán"], e: "并不恶声恶气，但很威严，使人知敬畏。", s: "《周易·遁》君子以远小人，不恶而严。”" },
  { w: "不悱不发", p: ["bù", "fěi", "bù", "fā"], e: "悱心里想说而说不出来。发启发。指不到学生想说而说不出来时，不去启发他。这是孔子的教学方法。", s: "《论语·述而》不愤不启，不悱不发。”" },
  { w: "不情之请", p: ["bù", "qíng", "zhī", "qǐng"], e: "情情理。不合情理的请求（称自己提出请求时的客气话）。", s: "清·纪昀《阅微草堂笔记·滦阳消夏录二》不情之请，惟君图之。”" },
  { w: "不惑之年", p: ["bù", "huò", "zhī", "nián"], e: "不惑遇到事情能明辨不疑。以此作为40岁的代称。", s: "《论语·为政》有四十而不惑”的说法。" },
  { w: "不愤不启", p: ["bù", "fèn", "bù", "qǐ"], e: "愤心里想弄明白而还不明白。启启发。指不到学生们想弄明白而还没有弄明白时，不去启发他。这是孔子的教学方法。", s: "《论语·述而》不愤不启，不悱不发。”" },
  { w: "不愧不作", p: ["bù", "kuì", "bù", "zuò"], e: "愧、怍惭愧。光明正大，问心无愧。", s: "《孟子·尽心上》仰不愧于天，俯不怍于人，二乐也。”" },
  { w: "不折不扣", p: ["bù", "zhé", "bù", "kòu"], e: "折、扣出售商品时，按定价减去的成数。没有折扣，表示完全、十足的意思。", s: "老舍《女店员》第二幕如今的妇女跟男人不折不扣一样尊贵！”" },
  { w: "不拔之志", p: ["bù", "bá", "zhī", "zhì"], e: "比喻意志坚决，不可动摇。", s: "《南史·沈约传》执不拔之志，高卧东南。”" },
  { w: "不挠不折", p: ["bù", "náo", "bù", "zhé"], e: "不弯曲，不屈服。形容节操刚正，意志坚强。", s: "宋·刘炎《迩言》夫观钱塘江潮，犹猛士之肝胆决裂，义士之怒发冲冠。观仙都天柱，犹直臣之气，不挠不折，社稷之佐，拓地擎天。”" },
  { w: "不改其乐", p: ["bù", "gǎi", "qí", "lè"], e: "不改变自有的快乐。指处于困苦的境况仍然很快乐。", s: "《论语·雍也》一箪食，一飘饮，在陋巷，人不堪其扰，回出不改其乐。”" },
  { w: "不教之教", p: ["bù", "jiào", "zhī", "jiào"], e: "不以直接的教育方式而进行的教育。指在日常言行中很自然地进行的薰陶。", s: "《吕氏春秋·君守》不教之教，无言之诏。”" },
  { w: "不教而杀", p: ["bù", "jiào", "ér", "shā"], e: "教教育；杀处罚，杀死。不警告就处死。指事先不教育人，一犯错误就加以惩罚。", s: "《论语·尧曰》不教而杀谓之虐。”" },
  { w: "不敢后人", p: ["bù", "gǎn", "hòu", "rén"], e: "不愿意落在别人后面。表示不敢懈怠，奋力前进。", s: "邹韬奋《抗战以来·生活”在抗战其间贡献了什么？》凡遇党政当局对抗战建国积极方面有所号召，亦无不竭诚响应，不敢后人。”" },
  { w: "不文不武", p: ["bù", "wén", "bù", "wǔ"], e: "既不能文，又不能武。", s: "唐·韩愈《泷吏》诗不知官在朝，有益国家不？得无虱其间，不文亦不武。”" },
  { w: "不无小补", p: ["bù", "wú", "xiǎo", "bǔ"], e: "补补助，补益。多少有一点益处或多少有一点帮助。", s: "宋·朱熹《〈尚书〉一·纲领》诸家虽或浅近，要亦不无小补，但在详择之耳。”" },
  { w: "不日不月", p: ["bù", "rì", "bù", "yuè"], e: "指不计日月，没有期限。", s: "《诗经·王风·君子于役》君子于役，不日不月。”" },
  { w: "不时之需", p: ["bù", "shí", "zhī", "xū"], e: "不时不是预定的时间。说不定什么时候会出现的需要。", s: "宋·苏轼《后赤壁赋》我有斗酒，藏之久矣，以待子不时之需。”" },
  { w: "不时之须", p: ["bù", "shí", "zhī", "xū"], e: "不时之需。指随时的、不是预定时间的需要。", s: "宋·苏轼《后赤壁赋》我有斗酒，藏之久矣，以待子不时之须。”" },
  { w: "不明不白", p: ["bù", "míng", "bù", "bái"], e: "指说话含含糊糊，很不清楚。也形容行为暧昧。", s: "元·无名氏《连环计》第四折怎么不明不白，着他父子每胡厮闹了一夜。”" },
  { w: "不易一字", p: ["bù", "yì", "yī", "zì"], e: "不更动一个字。形容文章写得又快又好。", s: "宋·欧阳修《新唐书·文艺传上》勃属文，初不精思，先磨墨数升，则酣饮，引被覆面卧，及寤，援笔成篇，不易一字，时人谓勃为‘腹稿’。”" },
  { w: "不易之典", p: ["bù", "yì", "zhī", "diǎn"], e: "不变的法则。", s: "宋·颜延之《赭白马赋》教敬不易之典，训人必书之举。”" },
  { w: "不易之论", p: ["bù", "yì", "zhī", "lùn"], e: "易改变。不可更改的言论。形容论断或意见非常正确。", s: "宋·惠洪《冷斋夜话》卷一○成周三代之际，圣人多生儒中，两汉以下圣人多生佛中，此不易之论也。”" },
  { w: "不期而会", p: ["bù", "qī", "ér", "huì"], e: "①未经约定而意外地遇见。②未经约定而自动聚集。", s: "语出《榖梁传·隐公八年》不期而会曰遇。”" },
  { w: "不期而同", p: ["bù", "qī", "ér", "tóng"], e: "指不约而同。", s: "郭沫若《文艺论集整理国故的评价》仿吾教人要注重科学，他的论调与吴稚晖的虽若不期而同，但是吴稚晖所注眼的是功利问题。”" },
  { w: "不期而然", p: ["bù", "qī", "ér", "rán"], e: "期希望；然如此。不希望这样，而竟然这样。表示出乎意外。", s: "宋·郑樵《与景韦兄投宇文枢密书》盖磁石取铁，以气相合，固有不期然而然者。”" },
  { w: "不根之论", p: ["bù", "gēn", "zhī", "lùn"], e: "根根据；论言论。没有根据的言论。", s: "《汉书·严助传》朔、皋不根持论，上颇俳优畜之。”" },
  { w: "不次之位", p: ["bù", "cì", "zhī", "wèi"], e: "次顺序，等第。旧指对于有才干的人不拘等级授予重要职位。", s: "《汉书·东方朔传》武帝初即位，征天下举方正贤良文学材力之士，待以不次之位。”" },
  { w: "不次之迁", p: ["bù", "cì", "zhī", "qiān"], e: "次顺序，等第；迁官位升迁。比喻超出常规的提升官级。", s: "《汉书·东方朔传》武帝初即位，征天下举方正贤良文学材力之士，待以不次之位。”" },
  { w: "不正之风", p: ["bù", "zhèng", "zhī", "fēng"], e: "不正当的社会风气。", s: "《抱朴子·辩问》移不正之风，易流遁之俗。”" },
  { w: "不步人脚", p: ["bù", "bù", "rén", "jiǎo"], e: "不跟着别人的脚步走。比喻不因循守旧。", s: "明·李贽《又与从吾》苏长公片言只字与金玉同声，虽千古未见其比，则以其胸中绝无俗气，下笔不作寻常语，不步人脚故耳。”" },
  { w: "不死不活", p: ["bù", "sǐ", "bù", "huó"], e: "说死没死，说活未活。形容没有生气或处境尴尬。", s: "宋·朱熹《朱子语类》卷四八箕子虽不死，然便死却又到了，唯是被囚不死不活，这地位如何处，直是难。”" },
  { w: "不毛之地", p: ["bù", "máo", "zhī", "dì"], e: "不生长草木庄稼的荒地。形容荒凉、贫瘠。", s: "《公羊传·宣公十二年》锡（赐）之不毛之地．”" },
  { w: "不法常可", p: ["bù", "fǎ", "cháng", "kě"], e: "法当做模式、法则；常可长久被人们认可的成规惯例。不把常规惯例当做永远不变的模式。", s: "《韩非子·五蠹》是以圣人不期修古，不法常可。”" },
  { w: "不牧之地", p: ["bù", "mù", "zhī", "dì"], e: "不能牧养牛马的地。指荒地。", s: "汉·桓宽《盐铁论·论功》不牧之地，不羁之民。”" },
  { w: "不甘后人", p: ["bù", "gān", "hòu", "rén"], e: "不甘心落在别人后面。", s: "" },
  { w: "不生不灭", p: ["bù", "shēng", "bù", "miè"], e: "佛家语，认为佛法无生灭变迁，即常住”之异名。", s: "晋·王巾《头陁寺碑文》仰苍苍之色者，不足知其远近；况视听之外，若存若亡，心行之表，不生不灭者哉。”" },
  { w: "不疾不徐", p: ["bù", "jí", "bù", "xú"], e: "疾急速。徐缓慢。不急不慢。指处事能掌握适度的节律，不太快或不太慢。", s: "宋·黄庭坚《王纯中墓志铭》君调用财力，不疾不徐，劳民劝功，公私以济。”" },
  { w: "不白之冤", p: ["bù", "bái", "zhī", "yuān"], e: "白搞清楚。没有得到辩白或洗刷的冤屈。", s: "明·冯梦龙《东周列国志》第四十二回唅之逃，非贪生怕死，实欲为太叔伸不白之冤耳！”" },
  { w: "不直一文", p: ["bù", "zhí", "yī", "wén"], e: "鄙视之词，犹言毫无价值。比喻无能或品格卑下。", s: "宋·罗大经《鹤林玉露》卷十四士大夫若爱一文，不直一文。”" },
  { w: "不直一钱", p: ["bù", "zhí", "yī", "qián"], e: "鄙视之词，犹言毫无价值。比喻无能或品格卑下。", s: "语出《史记·魏其武安侯列传》夫无所发怒，乃骂临汝侯曰‘生平毁程不识不直一钱，今日长者为寿，乃效女儿咕嗫耳语。”" },
  { w: "不相上下", p: ["bù", "xiāng", "shàng", "xià"], e: "分不出高低好坏。形容水平相当。", s: "唐·陆龟蒙《蠹化》翳叶仰啮，如饥蚕之速，不相上下。”" },
  { w: "不知不觉", p: ["bù", "zhī", "bù", "jué"], e: "知知道；觉觉察。没有意识到，没有觉察到。现多指未加注意。", s: "明·赵弼《两教辨》遂使昏愚之徒，听其妖诞，舍正从邪，醉生梦死，不知不觉。尧舜三代以前，未闻有此教。”" },
  { w: "不知就里", p: ["bù", "zhī", "jiù", "lǐ"], e: "就里其中，内情。不知道内幕。", s: "清·宣鼎《夜雨秋灯录·麻疯女邱丽玉》生不知就里，趋近软语，代为卸妆。”" },
  { w: "不知所云", p: ["bù", "zhī", "suǒ", "yún"], e: "云说。不知道说得是些么。形容说话内容混乱，无法理解。", s: "三国·蜀·诸葛亮《出师表》临表涕泣，不知所云。”" },
  { w: "不知所以", p: ["bù", "zhī", "suǒ", "yǐ"], e: "以原因。不明白为什么是这样。指不知道原因。", s: "唐·张彦远《法书要录·购兰亭序》遽见追乎，不知所以。”" },
  { w: "不知所出", p: ["bù", "zhī", "suǒ", "chū"], e: "①不知道从哪里来的。②不知道该怎么办。", s: "《文选·宋玉》卒愕异物，不知所出。”李善注不知所从来。”" },
  { w: "不知所可", p: ["bù", "zhī", "suǒ", "kě"], e: "不知道该怎么办才好。", s: "《儿女英雄传》第三一回不想这番好意把个可左可右的安公子此时倒弄到左右不知所可。”" },
  { w: "不知所终", p: ["bù", "zhī", "suǒ", "zhōng"], e: "终最后，结局。不知道结局或下落。", s: "《庄子·田子方》日夜无隙，而不知其所终。”《国语·越语下》遂乘扁舟，以浮于五湖，莫知其所终极。”" },
  { w: "不知所言", p: ["bù", "zhī", "suǒ", "yán"], e: "形容说话内容混乱，无法理解。同不知所云”。", s: "《三国志·蜀书·诸葛亮传》臣不胜受恩感激，今当远离，临表涕零，不知所言。”" },
  { w: "不知所错", p: ["bù", "zhī", "suǒ", "cuò"], e: "错错开；处置。不知道怎么办才好。形容处境为难或心神慌乱。", s: "《管子·七臣七主》振主喜怒无度，严诛列赦，臣下振怒，不知所错，则人反其故。”" },
  { w: "不知自爱", p: ["bù", "zhī", "zì", "ài"], e: "不知道爱惜自己。", s: "" },
  { w: "不知高下", p: ["bù", "zhī", "gāo", "xià"], e: "指说话做事不知轻重。", s: "明·康海《中山狼》第三折先生，谢得您救俺也，只俺有句不知高下的话儿敢说么？”" },
  { w: "不禁不由", p: ["bù", "jīn", "bù", "yóu"], e: "指不由自主。", s: "《儿妇英雄传》第十六回果然引动了那老头儿的满肚皮牢骚，不必等人盘问。他早不禁不由口似悬河的讲将起来。”" },
  { w: "不管一二", p: ["bù", "guǎn", "yī", "èr"], e: "不论是非情由，不顾后果。", s: "明·吴承恩《西游记》第二十六回你这猴子，不管一二，到处里闯禍。”" },
  { w: "不管不顾", p: ["bù", "guǎn", "bù", "gù"], e: "指对人不照料。也指举动莽撞，不顾别人。", s: "梁晓声《泯灭》三（2）她为什么将她那么痴情那么热烈那么不管不顾的爱给予这个孤傲而冷酷的翟子卿啊！……”" },
  { w: "不约而同", p: ["bù", "yuē", "ér", "tóng"], e: "约相约。事先没有约定而相互一致。", s: "《史记·平津侯主父列传》应对而皆动，不谋而俱起，不约而同会。”" },
  { w: "不经世故", p: ["bù", "jīng", "shì", "gù"], e: "经经历；世故人情世事的变故。形容缺乏为人处世的经验。", s: "鲁迅《花边文学·序言》然而他们不经世故，偶尔‘忘其所以’也就大碰其钉子。”" },
  { w: "不经之语", p: ["bù", "jīng", "zhī", "yǔ"], e: "指荒诞无稽、没有根据的话。", s: "宋·王辟之《渑水燕谈录·杂录》神宗顾问左右‘青唇’何事，皆不能对。乃以问赵元老。元老奏‘不经之语，不敢以闻’。”" },
  { w: "不经之说", p: ["bù", "jīng", "zhī", "shuō"], e: "指荒诞无稽、没有根据的话。", s: "唐·无稹《迁庙议状》曷若削汉朝不经之说，征殷周可久之文，从亲尽则迁之常规，为万代不朽之定制。”" },
  { w: "不经之谈", p: ["bù", "jīng", "zhī", "tán"], e: "不经不合道理。荒诞无稽、没有根据的话。", s: "《史记·孟子荀卿列传》其语闳大不经。”晋·羊祜《戒子书》无传无经之谈，无听毁誉之语。”" },
  { w: "不羁之才", p: ["bù", "jī", "zhī", "cái"], e: "羁马笼头，比喻约束。非凡的、不可拘束的才能。", s: "《汉书·司马迁传》仆少负不羁之才，长无乡曲之誉。”" },
  { w: "不羁之民", p: ["bù", "jī", "zhī", "mín"], e: "不受束缚的百姓。指不甘就范的人民群众。", s: "汉·桓宽《盐铁论·论功》不牧之地，不羁之民。”" },
  { w: "不能自已", p: ["bù", "néng", "zì", "yǐ"], e: "已停止。指无法控制自己，使激动的情绪平静下来。", s: "唐·卢照邻《寄裴舍人书》慨然而咏‘富贵他人合，贫贱亲戚离’，因泣下交颐，不能自已。”" },
  { w: "不能自拔", p: ["bù", "néng", "zì", "bá"], e: "拔摆脱。不能主动地从痛苦、错误或罪恶中解脱出来。", s: "《宋书·刘义恭传》世祖前锋至新亭，劭挟义恭出战，恒录在左右，故不能自拔。”" },
  { w: "不臣之心", p: ["bù", "chén", "zhī", "xīn"], e: "不臣不守臣子的本分，封建社会中不忠君。意指不忠君的思想◇也指犯上作乱的野心。", s: "《三国志·魏书·二公孙陶四张传》是时术阴有不臣之心，不利国家有长主，外托公义以答拒之。”《晋书·周处传》闻敦有不臣之心，访恆切齿。敦虽怀逆谋，故终访之世未敢为非。”" },
  { w: "不见天日", p: ["bù", "jiàn", "tiān", "rì"], e: "比喻社会黑暗，见不到一点光明。", s: "宋·魏泰《东轩笔录》卷八福州之人，以为终世不见天日也，岂料端公赐问，然某尤为绛所苦者也。”" },
  { w: "不解之仇", p: ["bù", "jiě", "zhī", "chóu"], e: "解除不了的仇恨。", s: "" },
  { w: "不解之缘", p: ["bù", "jiě", "zhī", "yuán"], e: "缘缘分。不可分解的缘分。比喻不能解脱的联系或关系。", s: "《古诗十九首》文彩双鸳鸯，裁为合欢被，著以长相思，缘以结不解。”" },
  { w: "不言不语", p: ["bù", "yán", "bù", "yǔ"], e: "不说话，闷声不响。", s: "明·冯梦龙《醒世恒言·吴衙内邻舟赴约》秀娥一心忆着吴衙内，坐在旁边，不言不语，如醉如痴，酒也不沾一滴，箸也不动一动。”" },
  { w: "不言而信", p: ["bù", "yán", "ér", "xìn"], e: "旧指君子不用说什么就能得到别人的信任。形容有崇高的威望。", s: "《庄子·田子方》夫子不言而信，不比而周。”" },
  { w: "不言而喻", p: ["bù", "yán", "ér", "yù"], e: "喻了解，明白。不用说话就能明白。形容道理很明显。", s: "《孟子·尽心上》仁义礼智根于心，其生色也，然见于面。盎于背，施于四体，四体不言而喻。”" },
  { w: "不言而谕", p: ["bù", "yán", "ér", "yù"], e: "谕旧时指上对下的文告、指示。不用说话就能明白。形容道理很明显。", s: "宋·苏轼《却鼠刀铭》呜呼嗟夫，吾苟有之，不言而谕，是亦何劳。”" },
  { w: "不讳之路", p: ["bù", "huì", "zhī", "lù"], e: "指忠言直谏之路。", s: "《后汉书·安帝纪》间令公卿郡国举贤良方正，远求博选，开不讳之路，冀得至谋，以鉴不逮。”" },
  { w: "不讳之门", p: ["bù", "huì", "zhī", "mén"], e: "讳忌讳。指说话可以直言不讳的地方。", s: "汉·刘向《说苑·君道》规谏必看不讳之门。”" },
  { w: "不识不知", p: ["bù", "shí", "bù", "zhī"], e: "没有多少知识。旧喻民风淳朴。", s: "《列子·仲尼》尧乃微服游于于康衢，闻儿童谣曰‘立我蒸民，莫匪尔极。不识不知，顺帝之则。’”" },
  { w: "不识之无", p: ["bù", "shí", "zhī", "wú"], e: "连之”字、无”字都不认识。形容人不识字，文化水平很低。", s: "唐·白居易《与元九书》仆始生六七月时，乳母抱弄于书屏下，有指‘无’字、‘之’字示仆者，仆虽口未能言，心已默识。”" },
  { w: "不谋而合", p: ["bù", "móu", "ér", "hé"], e: "谋商量；合相符。事先没有商量过，意见或行动却完全一致。", s: "晋·干宝《搜神记》卷二二人之言，不谋而合。”" },
  { w: "不谋而同", p: ["bù", "móu", "ér", "tóng"], e: "谋商量；同相同。事先没有商量过，意见或行动却完全一致。", s: "《三国志·魏书·张既传》裴松之注引《魏略》今诸将不谋而同，似有天数。”" },
  { w: "不败之地", p: ["bù", "bài", "zhī", "dì"], e: "原意是指善于打仗的就有取胜的把握，不会落到挫败的境地◇泛指办事有成功的充分把握。", s: "《孙子·军形》善战者，立于不败之地，而不失敌之败也。”" },
  { w: "不赏之功", p: ["bù", "shǎng", "zhī", "gōng"], e: "形容功劳极大。", s: "《史记·淮阴侯列传》臣闻勇略震主者身危，而功盖天下者不赏。”" },
  { w: "不赞一词", p: ["bù", "zàn", "yī", "cí"], e: "一句话也不说。", s: "《史记·孔子世家》至于为《春秋》，笔则笔，削则削，子夏之徒，不能赞一辞。”" },
  { w: "不足为意", p: ["bù", "zú", "wéi", "yì"], e: "不值得介意。", s: "明·张居正《答郑范溪》公但自信此心，秉公任直，纷纷之言，不足为意。”" },
  { w: "不足为法", p: ["bù", "zú", "wéi", "fǎ"], e: "不值得学习、效法。", s: "清·赵翼《瓯北诗话·李青莲诗》开口便说《大雅》不作，骚人斯起，然词多哀怨，已非正声；至杨、马益流宕。建安以后更绮丽，不足为法。”" },
  { w: "不足为虑", p: ["bù", "zú", "wéi", "lǜ"], e: "不值得忧虑担心。", s: "晋·陈寿《三国志·魏志·卫臻传》且合肥城固，不足为虑。”" },
  { w: "不辞而别", p: ["bù", "cí", "ér", "bié"], e: "辞告辞；别离别。没有告辞就离开了。或悄悄溜走了。", s: "元·郑德辉《王粲登楼》第一折报老爷得知，王粲不辞而别去了。”" },
  { w: "不近人情", p: ["bù", "jìn", "rén", "qíng"], e: "不合乎人的常情。也指性情或言行怪僻。", s: "《庄子·逍遥游》大有径庭，不近人情焉。”" },
  { w: "不速之客", p: ["bù", "sù", "zhī", "kè"], e: "速邀请。指没有邀请突然而来的客人。", s: "《周易·需》有不速之客三人来，敬之终吉。”" },
  { w: "不郎不秀", p: ["bù", "láng", "bù", "xiù"], e: "原指不高不下◇比喻不成材。", s: "明·田艺蘅《留青日札·沈尤之秀》元时称人以郎、官、秀为等第，至今人之鄙人曰不郎不秀，是言不高不下也。”" },
  { w: "不问不闻", p: ["bù", "wèn", "bù", "wén"], e: "闻听。人家说的不听，也不主动去问。形容对事情不关心。", s: "清·曹雪芹《红楼梦》第四回所以这李纨虽青春丧偶，且居处于膏梁锦绣之中，竟如‘槁木死灰’一般，一概不问不闻，惟知恃亲养子。”" },
  { w: "不闻不问", p: ["bù", "wén", "bù", "wèn"], e: "闻听。人家说的不听，也不主动去问。形容对事情不关心。", s: "清·石玉昆《三侠五义》第七十六回也不想想朝廷家平空的丢了一个太守，也就不闻不问，焉有是理。”" },
  { w: "不阴不阳", p: ["bù", "yīn", "bù", "yáng"], e: "比喻态度不明朗，模棱两可。", s: "清·燕谷老人《续孽海花》第四十四回这样的不阴不阳，教我怎么好呢？”" },
  { w: "不露形色", p: ["bù", "lù", "xíng", "sè"], e: "不让思想活动从行动和表情上流露出来。", s: "刘德桂《宣统皇帝》第一章二阿玛一向城府深藏，不露形色，怎么犯了这么大的错误。”" },
  { w: "不顾一切", p: ["bù", "gù", "yī", "qiè"], e: "什么都不顾。", s: "叶圣陶《孤独》既然见到一点儿光，便不得不不顾一切地逃开。”" },
  { w: "不食之地", p: ["bù", "shí", "zhī", "dì"], e: "不食不生产粮食。指不能耕种的土地。", s: "《礼记·檀弓上》我死则择不食之地而莽我焉。”" },
  { w: "不饥不寒", p: ["bù", "jī", "bù", "hán"], e: "不挨饿受冻。生活不愁温饱。", s: "《齐桓晋文之事》老者衣帛食肉，黎民不饥不寒。”" },
  { w: "不齿于人", p: ["bù", "chǐ", "yú", "rén"], e: "齿象牙齿一样排列。不能列于人类。指被人看不起。", s: "宋·沈括《梦溪笔谈·杂志》以为士人不齿，放弃终身。”" },
  { w: "与众不同", p: ["yǔ", "zhòng", "bù", "tóng"], e: "跟大家不一样。", s: "清·李汝珍《镜花缘》这是今日令中第一个古人，必须出类拔萃，与众不同，才觉有趣。”" },
  { w: "世道人心", p: ["shì", "dào", "rén", "xīn"], e: "社会的风气，人们的思想。", s: "" },
  { w: "世道人情", p: ["shì", "dào", "rén", "qíng"], e: "泛指社会的道德风尚和人们的思想情感等。同世道人心”。", s: "" },
  { w: "东张西望", p: ["dōng", "zhāng", "xī", "wàng"], e: "张看。形容这里那里地到处看。", s: "明·冯梦龙《古今小说》卷一三巧儿只为信了卖卦先生之语，一心只想丈夫回来，从此时常走向前楼，在帘内东张西望。”" },
  { w: "东风人面", p: ["dōng", "fēng", "rén", "miàn"], e: "指一年一度的春风依旧，而当年邂逅含情之人却不得重见。", s: "清·缪艮《珠江名花小传》第三卷迨素秋过访，询知其迁徒梧江，东风人面，未尝不有崔护当年之感云。”" },
  { w: "为人师表", p: ["wéi", "rén", "shī", "biǎo"], e: "师表榜样，表率。在人品学问方面作别人学习的榜样。", s: "《北齐书·王昕书》杨愔重其德业，以为人之师表。”" },
  { w: "为人说项", p: ["wèi", "rén", "shuō", "xiàng"], e: "为替；项唐朝项斯，字子迁，为杨敬之所器重。指替人说好话。", s: "唐·杨敬之《赠项斯》平生不解藏人善，到处逢人说项斯。”" },
  { w: "为国为民", p: ["wèi", "guó", "wèi", "mín"], e: "指不谋私利，为国家和人民效力。", s: "" },
  { w: "为德不终", p: ["wéi", "dé", "bù", "zhōng"], e: "指没有把好事做到底。同为德不卒”。", s: "" },
  { w: "举世闻名", p: ["jǔ", "shì", "wén", "míng"], e: "举世全世界。全世界都知道。形容非常著名。", s: "北齐·颜之推《颜氏家训·杂艺》王逸少风流才士，萧散名人。举世但知其书，翻以能自蔽也。”" },
  { w: "义不取容", p: ["yì", "bù", "qǔ", "róng"], e: "取容讨好。为追求正义而不取悦于人。指人刚直不阿。", s: "" },
  { w: "义不容辞", p: ["yì", "bù", "róng", "cí"], e: "容允许；辞推托。道义上不允许推辞。", s: "明·冯梦龙《醒世恒言》卷十七承姑丈高谊，小婿义不容辞。”" },
  { w: "之乎者也", p: ["zhī", "hū", "zhě", "yě"], e: "这四个字都是文言虚词，讽刺人说话喜欢咬文嚼字。也形容半文不白的话或文章。", s: "宋·文莹《湘山野录》之乎者也，助得甚事？”" },
  { w: "之死不渝", p: ["zhī", "sǐ", "bù", "yú"], e: "至死不变。形容忠贞不二。同之死靡它”。", s: "宋·苏辙《祭亡婿文逸民文》女有烈志，留鞠诸孤。赋诗《柏舟》，之死不渝。”" },
  { w: "乐不可极", p: ["lè", "bù", "kě", "jí"], e: "享乐不可过分。", s: "《礼记·曲礼上》志不可满，乐不可极。”" },
  { w: "乐不可言", p: ["lè", "bù", "kě", "yán"], e: "快乐到了极点，没法用语言来表达。", s: "战国·楚·屈原《大招》魂乎归徕，乐不可言只。”" },
  { w: "乘人之危", p: ["chéng", "rén", "zhī", "wēi"], e: "乘人家危难的时候去威胁损害。", s: "《后汉书·盖勋传》谋事杀良，非忠也；乘人之危，非仁也。”" },
  { w: "乘其不意", p: ["chéng", "qí", "bù", "yì"], e: "乘趁，因；意猜想，意料。利用别人没有防备的时机动手。", s: "《新编五代史平话·晋史》敌谓我不能逆风以战，宜乘其不意，急击之，此兵之诡道也。”" },
  { w: "书不尽意", p: ["shū", "bù", "jìn", "yì"], e: "指文辞难充分达意◇多作书信结尾习用语。", s: "《北齐书·文苑传·祖鸿勋》与阳休之书曰‘……已矣哉，书不尽意。’”" },
  { w: "书不尽言", p: ["shū", "bù", "jìn", "yán"], e: "书书信。信中难以充分表达其意◇多作书信结尾习用语。", s: "《易·系辞上》子曰‘书不尽言，言不尽意。’”" },
  { w: "书生之见", p: ["shū", "shēng", "zhī", "jiàn"], e: "指读书人不切实际或不合时宜的见解。", s: "宋·邵博《闻见后录》卷一予谓议者以本朝养兵为大费，欲复寓兵于农之法，书生之见，可言而不可用者哉。”" },
  { w: "书香人家", p: ["shū", "xiāng", "rén", "jiā"], e: "指世代都是读书人的家庭。", s: "清·吴趼人《二十年目睹之怪现状》第三十六回原来是个仕宦书香人家，怪不的他得夫人那样明理。”" },
  { w: "事不关己", p: ["shì", "bù", "guān", "jǐ"], e: "事情同自己没有关系。", s: "《曹雪芹别传》当时的风气是谨言慎行，少发议论，事不关己，不必打听，因此对这一次大征战的命将出师，一直不甚了了。”" },
  { w: "事不师古", p: ["shì", "bù", "shī", "gǔ"], e: "形容做事不吸取前人经验。", s: "《书·说命下》事不师古，以克永世。”" },
  { w: "事不有余", p: ["shì", "bù", "yǒu", "yú"], e: "谓达到极点。", s: "清·文康《儿女英雄传》第四十回娘儿俩先哭了个事不有余，大家劝住，他便忙着到祠堂行礼。”" },
  { w: "事不过三", p: ["shì", "bù", "guò", "sān"], e: "指同样的事不宜连作三次。", s: "明·吴承恩《西游记》第二十七回常言道‘事不过三。’我若不去，真是个下流无耻之徒。”" },
  { w: "事出有因", p: ["shì", "chū", "yǒu", "yīn"], e: "事情的发生是有原因的。", s: "叶圣陶《得失》但是一想到事出有因，他就只好假装没有听见。”" },
  { w: "事无二成", p: ["shì", "wú", "èr", "chéng"], e: "谓公事和私事不能两全。", s: "《左传·成公八年》礼无加货，事无二成。”杜预注公私不两成。”" },
  { w: "事无大小", p: ["shì", "wú", "dà", "xiǎo"], e: "事情不分大小。形容什么事都管。", s: "《文选·诸葛亮〈出师表〉》愚以为宫中之事，事无大小，悉以咨之。”宋·司马光《资治通鉴》卷第一百八十五委萧瑀以庶政，事无大小，莫不关掌。”" },
  { w: "事无常师", p: ["shì", "wú", "cháng", "shī"], e: "谓处事没有固定不变的准则，要择善而从。", s: "春秋·王诩《鬼谷子·忤合》世无常贵，事无常师。”陶弘景注主善为师，故无常师。”" },
  { w: "二三其意", p: ["èr", "sān", "qí", "yì"], e: "即三心二意。指心意不专一，反复无常。", s: "《三国志·袁绍传》裴松之注引《汉晋春秋》是时外为御难，内实乞罪，既不见赦，而屠各二三其心，临阵叛戾。”" },
  { w: "二三君子", p: ["èr", "sān", "jūn", "zǐ"], e: "犹二三子。", s: "《左传·僖公二十四年》主晋祀者，非君而谁，天实置之，而二三子以为己力，不亦诬乎。”《汉书·楚元王传》故下明诏，试《左氏》可立不，遣近臣奉指衔命，将以辅弱扶微，与二三君子比意同力，冀得废遗。”" },
  { w: "二心三意", p: ["èr", "xīn", "sān", "yì"], e: "想这样又想那样。形容意念不专，主意不定。同三心二意”。", s: "明·方汝浩《禅真逸史》第六回念佛是一桩正事，岂有二心三意？”" },
  { w: "二话不说", p: ["èr", "huà", "bù", "shuō"], e: "不说任何别的话。指立即行动。", s: "老舍《四世同堂》九八‘日本鬼子完蛋了，投降了，’方六低声回答。丁约翰象在教堂里说‘阿门’那样，把眼睛闭了一闭。二话不说，回头就跑。”" },
  { w: "于事无补", p: ["yú", "shì", "wú", "bǔ"], e: "对事情毫无补益。", s: "" },
  { w: "于家为国", p: ["yú", "jiā", "wéi", "guó"], e: "为国家为人民。", s: "" },
  { w: "井底之蛙", p: ["jǐng", "dǐ", "zhī", "wā"], e: "井底的蛙只能看到井口那么大的一块天。比喻见识狭窄的人。", s: "《庄子·秋水》井蛙不可以语于海者，拘于虚也。”" },
  { w: "亡羊补牢", p: ["wáng", "yáng", "bǔ", "láo"], e: "亡逃亡，丢失；牢关牲口的圈。羊逃跑了再去修补羊圈，还不算晚。比喻出了问题以后想办法补救，可以防止继续受损失。", s: "《战国策·楚策》见兔而顾犬，未为晚也；亡羊而补牢，未为迟也。”" },
  { w: "人一己百", p: ["rén", "yī", "jǐ", "bǎi"], e: "别人一次就做好或学会的，自己做一百次，学一百次。比喻以百倍的努力赶上别人。", s: "《礼记·中庸》人一能之，己百之；人十能之，己千之。果能此通矣，虽愚必明，虽柔必强。”" },
  { w: "人不聊生", p: ["rén", "bù", "liáo", "shēng"], e: "聊依赖，凭借。指老百姓无法生活下去。", s: "《吴越春秋·勾践阴谋外传》民疲士苦，人不聊生。”" },
  { w: "人不自安", p: ["rén", "bù", "zì", "ān"], e: "人心惶惶，动摇不定。", s: "《魏书·慕容盛传》于是上下震局，人不自安，虽忠诚亲戚，亦佥怀离贰。”" },
  { w: "人中之龙", p: ["rén", "zhōng", "zhī", "lóng"], e: "比喻人中豪杰。", s: "《晋书·宋纤传》吾而今而后知先生人中之龙也。”" },
  { w: "人中狮子", p: ["rén", "zhōng", "shī", "zǐ"], e: "像狮子是兽中之王那样。比喻才能出众的人。", s: "《释氏要览》天竺大乘沙门佛陀斯那天才特拔，诸国独步，内外综博，无籍不练，世人咸曰人中狮子。”" },
  { w: "人之常情", p: ["rén", "zhī", "cháng", "qíng"], e: "一般人通常有的感情。", s: "南朝·粱·江淹《杂体诗三十八首·序》又贵远贱近，人心向背；重耳轻目，俗之恒弊。”" },
  { w: "人事不知", p: ["rén", "shì", "bù", "zhī"], e: "指昏迷不醒，失去知觉。同人事不省”。", s: "《红楼梦》第一二○回宝钗哭得人事不知。”" },
  { w: "人事不醒", p: ["rén", "shì", "bù", "xǐng"], e: "指昏迷不醒，失去知觉。同人事不省”。", s: "杨朔《晚凉天》有一位同志，是渔船救起来的，三天三夜人事不醒。”" },
  { w: "人人皆知", p: ["rén", "rén", "jiē", "zhī"], e: "皆都。所有的人都知道。", s: "毛泽东《中国革命战争的战略问题》人人皆知以多胜少是最好的办法。”" },
  { w: "人人自危", p: ["rén", "rén", "zì", "wēi"], e: "每个人都感到自己不安全，有危险。", s: "《史记·李斯列传》法令诛罚，日益深刻，群臣人人自危，欲畔者众。”" },
  { w: "人以群分", p: ["rén", "yǐ", "qún", "fēn"], e: "人按照其品行、爱好而形成团体，因而能互相区别。指好人总跟好人结成朋友，坏人总跟坏人聚在一起。", s: "《易·系辞上》方以类聚，物以群分，吉凶生矣。”" },
  { w: "人千人万", p: ["rén", "qiān", "rén", "wàn"], e: "形容人多。", s: "" },
  { w: "人各有志", p: ["rén", "gè", "yǒu", "zhì"], e: "指每个人各自有不同的志向愿望，不能勉为其难。", s: "汉·王粲《咏史诗》人生各有志，终不为此移，同知埋身剧，心亦有所施。”" },
  { w: "人地生疏", p: ["rén", "dì", "shēng", "shū"], e: "人事不熟，地方陌生。指初到一地，对当地的人事和地理都不熟悉。", s: "鲁迅《伪自由书·前记》《自由谈》的编辑新换了黎烈文先生了，但他才从法国回来，人地生疏，怕一时搞不起稿子，要我去投几回稿。”" },
  { w: "人尽其才", p: ["rén", "jìn", "qí", "cái"], e: "每个人都能充分发挥自己的才能。", s: "《淮南子·兵略训》若乃人尽其才，悉用其力。”" },
  { w: "人山人海", p: ["rén", "shān", "rén", "hǎi"], e: "人群如山似海。形容人聚集得非常多。", s: "明·施耐庵《水浒全传》第五十一回每日有那一般打散，或是戏舞，或是吹弹，或是歌唱，赚得那人山人海价看。”" },
  { w: "人己一视", p: ["rén", "jǐ", "yī", "shì"], e: "待别人象待自己一样。比喻待人没有私心。", s: "宋·罗大经《鹤林玉露》卷二此正无意于我，人己一视之道，实贤人君子之盛德。”" },
  { w: "人心不古", p: ["rén", "xīn", "bù", "gǔ"], e: "古指古代的社会风尚。旧时指人心奸诈、刻薄，没有古人淳厚。", s: "清·李汝珍《镜花缘》第五十五回奈近来人心不古，都尚奢华。”" },
  { w: "人心大快", p: ["rén", "xīn", "dà", "kuài"], e: "快痛快。指坏人坏事受到惩罚或打击，使大家非常痛快。", s: "明·沈德符《万历野获编·立枷》东山受恩反噬，其罪盖浮于诸龙光。当时人心大快，佐以此得缙绅闻声，然亦不云立枷。”" },
  { w: "人心如面", p: ["rén", "xīn", "rú", "miàn"], e: "心指思想、感情等。指每个人的思想也象每个人的面貌一样，各不相同。", s: "《左传·襄公三十一年》人心之不同，如其面焉，吾岂敢谓子面如吾面乎？”" },
  { w: "人心所向", p: ["rén", "xīn", "suǒ", "xiàng"], e: "向归向，向往。指人民群众所拥护的，向往的。", s: "《晋书·熊远传》人心所归，惟道与义。”" },
  { w: "人心所归", p: ["rén", "xīn", "suǒ", "guī"], e: "指众人所归向、拥护的。", s: "" },
  { w: "人情世故", p: ["rén", "qíng", "shì", "gù"], e: "为人处世的道理。", s: "宋·文天祥《送僧了敬序》姑与之委曲于人情世故之内。”明·冯梦龙《醒世恒言》第二十一卷可惜你满腹文章，看不出人情世故。”" },
  { w: "人情之常", p: ["rén", "qíng", "zhī", "cháng"], e: "通常情况下人们共有的情理或态度。", s: "宋·司马光《应诏论体要》凡用一人，必或以为贤，或以为不肖，此固人情之常，自古而然，不足怪也。”" },
  { w: "人我是非", p: ["rén", "wǒ", "shì", "fēi"], e: "是非争执，纠纷。人与人之间的各种利害关系和纠纷。", s: "元·马致远《黄粱梦》第四折一梦中十八年，见了酒色财气，人我是非，贪嗔痴爱，风霜雨雪。”" },
  { w: "人来人往", p: ["rén", "lái", "rén", "wǎng"], e: "人来来往往连续不断。也形容忙于应酬。", s: "清·曹雪芹《红楼梦》第一百十回这两三天人来人往，我瞧着那些人都照应不到，想必你没有吩咐，还得你替我们操点心儿才好。”" },
  { w: "人浮于事", p: ["rén", "fú", "yú", "shì"], e: "浮超过。原指人的才德高过所得俸禄的等级◇指工作中人员过多或人多事少。", s: "《礼记·坊记》故君子与其使食浮于人也，宁使人浮于食。”" },
  { w: "人生如梦", p: ["rén", "shēng", "rú", "mèng"], e: "人生如同一场梦。形容世事无定，人生短促。", s: "宋·苏轼《念奴娇·赤壁怀古》词人生如梦，一樽还酹江月。”" },
  { w: "人百其身", p: ["rén", "bǎi", "qí", "shēn"], e: "百其身自身死一百次。别人愿意死一百次来换取死者的复生。表示对死者极沉痛的悼念。", s: "《诗·秦风·黄鸟》如可赎兮，人百其身。”" },
  { w: "人自为政", p: ["rén", "zì", "wéi", "zhèng"], e: "各人推行自己的主张。比喻各行其是。", s: "清·李渔《闲情偶寄·词曲·格局》传奇格局，有一定而不可移者，有可仍、可改，听人自为政者。”" },
  { w: "人间天上", p: ["rén", "jiān", "tiān", "shàng"], e: "人世社会和神仙世界。指景物极美好的处所。多比喻境遇完全不同。", s: "唐·崔颢《七夕词》仙裙玉佩空自知，天上人间不相见。”" },
  { w: "人非物是", p: ["rén", "fēi", "wù", "shì"], e: "指人事变迁，景物依旧。", s: "清·洪昻《长生殿·寄情》蓬莱院月悴花憔，昭阳殿人非物是。”" },
  { w: "仁人君子", p: ["rén", "rén", "jūn", "zǐ"], e: "仁仁爱。旧称好心肠的正派人。亦用作反语讽刺伪君子。", s: "《晋书·刑法志》刑之则止，而加之斩戮，戮过其罪，死不可生，纵虐于此，岁以巨计，此乃仁人君子所不忍闻，而况行之政乎？”" },
  { w: "从一而终", p: ["cóng", "yī", "ér", "zhōng"], e: "丈夫死了不再嫁人，这时旧时束缚妇女的封建礼教。", s: "《周易·恒》曰妇人贞洁，从一而终也。”" },
  { w: "从天而下", p: ["cóng", "tiān", "ér", "xià"], e: "比喻出于意外，突然出现。", s: "《汉书·周亚夫传》直入武库，击鸣鼓。诸侯闻之，以为将军从天而下也。”" },
  { w: "从容不迫", p: ["cóng", "róng", "bù", "pò"], e: "从容不慌不忙，很镇静；不迫不急促。不慌不忙，沉着镇定。", s: "《旧唐书·刘世龙传》而思礼以为得计，从容自若，尝与相忤者，必引令枉诛。”" },
  { w: "从容自如", p: ["cóng", "róng", "zì", "rú"], e: "不慌不忙，得心应手。", s: "吴伯箫《记一辆纺车》熟练的纺手趁着一线灯光或者朦胧的月色也能摇车，抽线，上线，一切做得从容自如。”" },
  { w: "以一当十", p: ["yǐ", "yī", "dāng", "shí"], e: "当相当。一个人抵挡十个人。形容军队英勇善战。", s: "《战国策·齐策一》一而当十，十而当百，百而当千。”《史记·项羽本纪》楚战士无不一以当十，楚兵呼声动天，诸侯军无不人人惴恐。”" },
  { w: "以一知万", p: ["yǐ", "yī", "zhī", "wàn"], e: "从了解一点到推知其他许多事物。", s: "《荀子·非相》以近知远，以一知万，以微知明，此之谓也。”" },
  { w: "以人为鉴", p: ["yǐ", "rén", "wéi", "jiàn"], e: "指将别人的成败得失作为自己的鉴戒。", s: "《书·酒诰》古人有言曰‘人无于水监，当于民监。’”于，以；监，通鉴”，镜。《国语·吴语》王其盍亦鉴于人，无鉴于水。”韦昭注引《书》曰人无于水鉴，当于民鉴。”" },
  { w: "以人废言", p: ["yǐ", "rén", "fèi", "yán"], e: "以因为；废废弃。因为说话人的地位的低下或犯有错误就不采纳他所说的正确的意见。", s: "《论语·卫灵公》君子不以言举人，不以人废言。”" },
  { w: "以力服人", p: ["yǐ", "lì", "fú", "rén"], e: "力权势，武力。用强制手段使人服从。", s: "《孟子·公孙丑上》以力服人者，非心服也，力不赡也。”" },
  { w: "以古喻今", p: ["yǐ", "gǔ", "yù", "jīn"], e: "喻说明。借用古代的事来说明今天的事情或道理。", s: "《北史·长孙嵩传》昔叔孙辞沃壤之地，萧何就穷僻之乡，以古方今，无渐曩哲。”" },
  { w: "以容取人", p: ["yǐ", "róng", "qǔ", "rén"], e: "只凭容貌来衡量人的品质和才能。", s: "《韩非子·显学》孔子曰‘以容取人乎，失之子羽；以言取人乎，失之宰予。”《孔子家语·子路初见》以容取人，则失之子羽； 以辞取人，则失之宰予。”" },
  { w: "以小见大", p: ["yǐ", "xiǎo", "jiàn", "dà"], e: "从小的可以看出大的，指通过小事可以看出大节，或通过一小部分看出整体。", s: "" },
  { w: "以德服人", p: ["yǐ", "dé", "fú", "rén"], e: "以良好的德行使百姓归顺、服从统治者。", s: "" },
  { w: "以心传心", p: ["yǐ", "xīn", "chuán", "xīn"], e: "佛教禅宗用语。指离开语文文字而以慧心相传授。", s: "《六祖大师法宝坛经·行由品》法则以心传心，皆令自悟自解。”" },
  { w: "以心问心", p: ["yǐ", "xīn", "wèn", "xīn"], e: "在心中自问自盘算。", s: "明·凌濛初《初刻拍案惊奇》卷十七［知观］以心问心，忽然道‘有计了。’”" },
  { w: "以日为年", p: ["yǐ", "rì", "wéi", "nián"], e: "过一日如同过一年的时间那样漫长难熬。形容心情焦急。亦作以日为岁”。", s: "" },
  { w: "以理服人", p: ["yǐ", "lǐ", "fú", "rén"], e: "用道理来说服人。", s: "赖传珠《古田会议前后》毛党代表完全采用说服教育，以理服人的态度，而且还要我参加会议一起讨论。”" },
  { w: "以言举人", p: ["yǐ", "yán", "jǔ", "rén"], e: "根据言论来举荐人才。", s: "汉·桓宽《盐铁论·利议》［文学］议论称诵，窃商赐之辞；刺讥言治，过管晏之才。心卑卿相，志小万乘。及授之政，昏乱不治。故以言举人，若以毛相马，此其所以多不称举。”" },
  { w: "以言取人", p: ["yǐ", "yán", "qǔ", "rén"], e: "根据人的口才去判断其智能。", s: "《史记·仲尼弟子列传》孔子闻之，曰‘吾以言取人，失之宰予；以貌取人，失之子羽。’”" },
  { w: "以辞取人", p: ["yǐ", "cí", "qǔ", "rén"], e: "根据人的口才去判断其智能。同以言取人”。", s: "《孔子家语·子路初见》宰我有文雅之辞，而智不充其辩。孔子曰‘ ……以辞取人，则失之宰予。’”" },
  { w: "似有如无", p: ["sì", "yǒu", "rú", "wú"], e: "只当没有这回事。形容不在乎，不在意。", s: "明·冯惟敏《涞邑初度自述》眼见的争名夺利眉儿先皱，耳听着受职为官胆儿便虚，俺子当似有如无。”" },
  { w: "何所不为", p: ["hé", "suǒ", "bù", "wéi"], e: "用反问的语气表示无所不为。", s: "" },
  { w: "何所不有", p: ["hé", "suǒ", "bù", "yǒu"], e: "用反问的语气表示无所不有。", s: "宋·周密《齐东野语·黄婆》此事前所未闻，是知穷荒绝檄，天奇地怪，亦何所不有，未可以见闻所未及，遂以为诞也。”" },
  { w: "何所不至", p: ["hé", "suǒ", "bù", "zhì"], e: "①用反问的语气表示无所不至。指没有达不到的地方。②指什么坏事都干。", s: "" },
  { w: "何罪之有", p: ["hé", "zuì", "zhī", "yǒu"], e: "即有何罪”，有什么罪呢？用反问的语气表示清白无辜，没有过错。", s: "《墨子·公输》闻子为梯，将以攻宋，宋何罪之有？”" },
  { w: "信言不美", p: ["xìn", "yán", "bù", "měi"], e: "信真实。美美妙，漂亮。真实的话未经加工，所以不美妙动听。", s: "" },
  { w: "先天不足", p: ["xiān", "tiān", "bù", "zú"], e: "先天人或动物的胚胎时期。原指人或动物生下来体质就不好◇也指事物的根基差。", s: "清·李汝珍《镜花缘》第二十六回小弟闻得仙人与虚合体，日中无影；又老人之子，先天不足，亦或日中无影。寿麻之人无影，不知何故？”" },
  { w: "先见之明", p: ["xiān", "jiàn", "zhī", "míng"], e: "明·指眼力。事先看清问题的能力。指对事物发展的预见性。", s: "《后汉书·杨彪传》愧无日磾先见之明，犹怀老牛舐犊之爱。”" },
  { w: "全力以赴", p: ["quán", "lì", "yǐ", "fù"], e: "赴前往。把全部力量都投入进去。", s: "清·越翼《廿二史札记·五·东汉尚名节》盖当时荐徵辟，必采名誉，故凡可以得名者，必全力赴之，好为苟难，遂成风俗。”" },
  { w: "全神贯注", p: ["quán", "shén", "guàn", "zhù"], e: "贯注集中。全部精神集中在一点上。形容注意力高度集中。", s: "叶圣陶《伊和他》他指着球里嵌着的花纹，相着伊又相着花纹，全神贯注的，十分喜悦的告诉伊。”" },
  { w: "公之于众", p: ["gōng", "zhī", "yú", "zhòng"], e: "公公开；之代指事物的内容；于向；众大众。把事情真相向大家公布。", s: "" },
  { w: "兴高采烈", p: ["xìng", "gāo", "cǎi", "liè"], e: "兴原指志趣，后指兴致；采原指神采，后指精神；烈旺盛。原指文章志趣高尚，言词犀利◇多形容兴致高，精神饱满。", s: "南朝梁·刘勰《文心雕龙·体性》步夜俊侠，故兴高而采烈。”" },
  { w: "兵无常形", p: ["bīng", "wú", "cháng", "xíng"], e: "用兵无一成不变的形势。指办事要因时、因地制宜，具体问题要用具体办法去解决。", s: "《孙子·计》兵者，诡道也”三国·魏·曹操注兵无常形，以诡诈为道。”" },
  { w: "其道无由", p: ["qí", "dào", "wú", "yóu"], e: "找不到门径；无法办到。同其道亡繇”。", s: "" },
  { w: "兼而有之", p: ["jiān", "ér", "yǒu", "zhī"], e: "指同时占有或具有几种事物。", s: "《墨子·法仪》奚以知天兼而爱之，兼而利之也？以其兼而有之，兼而食之也。”" },
  { w: "再不其然", p: ["zài", "bù", "qí", "rán"], e: "犹言再不然。", s: "" },
  { w: "出一头地", p: ["chū", "yī", "tóu", "dì"], e: "指当避开此人让其高出众人一头之地◇以之比喻高人一着。", s: "宋·欧阳修《与梅圣俞书》读轼（苏轼）书，不觉汗出。快哉快哉！老夫当避路，放他出一头地也。”" },
  { w: "出人头地", p: ["chū", "rén", "tóu", "dì"], e: "指高人一等。形容德才超众或成就突出。", s: "宋·欧阳修《与梅圣俞书》老夫当避路，放他出一头地也。”" },
  { w: "出人意外", p: ["chū", "rén", "yì", "wài"], e: "出于人们的意料之外，都没想到的。", s: "明·凌濛初《初刻拍案惊奇》卷一却又有转眼贫富出人意外，眼前事分毫算不得准的哩！”" },
  { w: "出人意表", p: ["chū", "rén", "yì", "biǎo"], e: "表外。出乎人们意料之外。", s: "《南史·袁宪传》宪常招引诸生与之谈论新义，出人意表，同辈咸嗟服焉。”宋·苏轼《举何去非换文资状》其论历代所以废兴成败，皆出人意表。”" },
  { w: "出以公心", p: ["chū", "yǐ", "gōng", "xīn"], e: "指考虑事情以国家和集体的利益为出发点。", s: "" },
  { w: "出其不备", p: ["chū", "qí", "bù", "bèi"], e: "指行动出乎人的意料。", s: "清·曹雪芹《红楼梦》第73回这倒不是道家法术，倒是用兵最精的所谓‘守如处女，出如脱兔’，‘出其不备’的妙策。”" },
  { w: "出其不意", p: ["chū", "qí", "bù", "yì"], e: "其代词，对方；不意没有料到。趁对方没有意料到就采取行动。", s: "《孙子·计篇》攻其无备，出其不意。”" },
  { w: "出其不虞", p: ["chū", "qí", "bù", "yú"], e: "犹言出其不意。指行动出乎人的意料。", s: "《周书·段永传》若星驰电发，出其不虞，精骑五百，自足平殄。”" },
  { w: "出头之日", p: ["chū", "tóu", "zhī", "rì"], e: "出头摆脱困境等。指从困厄、冤屈、压抑的处境中摆脱出来的日子。", s: "元·无名氏《庞娟夜走马陵道》第三折如今佯推风疾举发，白日里与儿童作戏，到晚间共羊犬同眠。不知几时才得个出头之日。”" },
  { w: "出敌不意", p: ["chū", "dí", "bù", "yì"], e: "指行动出于敌方意料。", s: "姚雪垠《李自成》第一卷第八章不如让我去，出敌不意，拦腰插一拳，也许能够把敌阵冲乱。”" },
  { w: "出有入无", p: ["chū", "yǒu", "rù", "wú"], e: "出入于有无之中。", s: "《云笈七签》卷一○四或与众仙，策空驾虚，出有入无，分形散影，处处游集。”" },
  { w: "出言有章", p: ["chū", "yán", "yǒu", "zhāng"], e: "说话有条理。", s: "《诗经·小雅·都人士之什》 彼都人士，狐裘黄黄，其容不改，出言有章。行归于周，万民所望。”" },
  { w: "击其不意", p: ["jī", "qí", "bù", "yì"], e: "在敌人没有预料到的情况下进行攻击。", s: "《孙子·虚实》行千里而不劳者，行于无人之地也。”三国·魏·曹操注出空击虚，避其所守，击其不意。”" },
  { w: "分文不取", p: ["fēn", "wén", "bù", "qǔ"], e: "一个钱也不要。比喻不计报酬。", s: "明·冯梦龙《醒世恒言·一文钱小隙造奇冤》又且一清如水，分文不取。”" },
  { w: "分文不名", p: ["fēn", "wén", "bù", "míng"], e: "名占有。一分钱一个铜板也没有。比喻非常贫困。", s: "" },
  { w: "分文不直", p: ["fēn", "wén", "bù", "zhí"], e: "直同值”。一分钱一文钱也不值。形容没有任何价值。", s: "宋·释普济《五灯会元》卷十八有人赞叹此事，如虎带角；有人轻毁此事，一文不值，一等是恁么事，因什么毁赞不是。”" },
  { w: "分而治之", p: ["fēn", "ér", "zhì", "zhī"], e: "①分别治理。②利用手段使国家、民族或宗教等产生分裂，然后对其进行控制和统治。", s: "清·俞樾《群经平议·周官二》巫马下士二人医四人”凡邦之有疾病者，痟疡者造焉，则使医分而治之，是亦不自医也。”" },
  { w: "划一不二", p: ["huà", "yī", "bù", "èr"], e: "指按照定价卖出，不打折扣。形容做事刻板。", s: "《汉书·曹参传》萧何为法，讲若画一。”" },
  { w: "别有人间", p: ["bié", "yǒu", "rén", "jiān"], e: "犹别有天地。", s: "清·卓发之《裓园嫘史》诗序清凉山之畔，竹径数转，别有人间。”" },
  { w: "别有天地", p: ["bié", "yǒu", "tiān", "dì"], e: "天地境界。比喻另有一番境界。形容风景或艺术创作的境界引人入胜。", s: "唐·李白诗《山中问答》桃花流水窅然去，别有天地非人间。”" },
  { w: "别有用心", p: ["bié", "yǒu", "yòng", "xīn"], e: "用心居心，打算。心中另有算计。指言论或行动另有不可告人的企图。", s: "清·吴趼人《二十年目睹之怪现状》第九十九回王太尊也是说他办事可靠，那里知道他是别有用心的呢。”" },
  { w: "刻舟求剑", p: ["kè", "zhōu", "qiú", "jiàn"], e: "比喻不懂事物已发展变化而仍静止地看问题。", s: "《吕氏春秋·察今》》楚人有涉江者，其剑自舟中坠于水，遽契其舟曰‘是吾剑之所从坠。’舟止，从其所契者入水求之。舟已行矣，而剑不行，求剑若此，不亦惑乎？”" },
  { w: "前无古人", p: ["qián", "wú", "gǔ", "rén"], e: "指以前的人从来没有做过的。也指空前的。", s: "唐·陈子昂《登幽州台歌》前不见古人，后不见来者。”" },
  { w: "力不从心", p: ["lì", "bù", "cóng", "xīn"], e: "心里想做，可是力量够不上。", s: "《后汉书·西域传》今使者大兵未能得出，如诸国力不从心，东西南北自在也。”" },
  { w: "力不能及", p: ["lì", "bù", "néng", "jí"], e: "力量达不到。", s: "元·无名氏《武王伐纣平话》卷下一城百姓见城自摧破，自来搜捉纣王，纣王见兵势甚大，力不能及。”" },
  { w: "力不自胜", p: ["lì", "bù", "zì", "shèng"], e: "胜经得住。由于力量不够而使得自己经受不起。", s: "" },
  { w: "力所不及", p: ["lì", "suǒ", "bù", "jí"], e: "及达到。凭自己的力量不能做到。", s: "宋·释惠洪《石门文字禅》平生所未见之文，公力所不及之义，备聚其中。”" },
  { w: "加人一等", p: ["jiā", "rén", "yī", "děng"], e: "加超过。超过别人一等。比喻学问才能超过一般人。也指争强好胜。", s: "《礼记·檀弓上》献子加于人一等矣。”" },
  { w: "动不失时", p: ["dòng", "bù", "shī", "shí"], e: "时时宜，时机。行动不失时机。指不做不切合时宜的事。", s: "汉·刘安《淮南子·人间训》圣人敬小慎微，动不失机。”" },
  { w: "动之以情", p: ["dòng", "zhī", "yǐ", "qíng"], e: "用感情来打动他的心。", s: "" },
  { w: "势不可当", p: ["shì", "bù", "kě", "dāng"], e: "当抵挡。形容来势十分迅猛，不能抵挡。", s: "《晋书·郗鉴传》群逆纵逸，其势不可当，可以算屈，难以力竞。”明·罗贯中《三国演义》第一百十九回山上数处精兵杀下，势不可当，前军大败。”" },
  { w: "十全十美", p: ["shí", "quán", "shí", "měi"], e: "十分完美，毫无欠缺。", s: "" },
  { w: "十发十中", p: ["shí", "fā", "shí", "zhòng"], e: "射十次皆中的。形容善射。", s: "" },
  { w: "十指连心", p: ["shí", "zhǐ", "lián", "xīn"], e: "十个指头连着心。表示身体的每个小部分都跟心有不可分的关系。比喻亲人跟自身休戚相关。", s: "明·许仲琳《封神演义》第七回十指连心，可怜昏死在地。”" },
  { w: "十死一生", p: ["shí", "sǐ", "yī", "shēng"], e: "形容生命非常危险。", s: "《汉书·孝宣许皇后传》妇人免乳大故，十死一生。”" },
  { w: "十死不问", p: ["shí", "sǐ", "bù", "wèn"], e: "指即使犯十次死罪也予宽恕。", s: "" },
  { w: "千人一面", p: ["qiān", "rén", "yī", "miàn"], e: "众多人一个脸谱。多用以讥讽文艺创作上的雷同。", s: "" },
  { w: "千人所指", p: ["qiān", "rén", "suǒ", "zhǐ"], e: "千人众人，许多人；指指责。为众人所拇，。", s: "《汉书·王嘉传》千人所指，无病而死。”" },
  { w: "千金之子", p: ["qiān", "jīn", "zhī", "zǐ"], e: "旧指富贵人家的子弟。", s: "《史记·袁盎晁错列传》臣闻千金之子，坐不垂堂。”" },
  { w: "半三不四", p: ["bàn", "sān", "bù", "sì"], e: "指心神不定，无精打采。", s: "《西湖二集·李凤娘酷妒遭天谴》勾引得官家一心在你身上，就在我身边，也是半三不四。”" },
  { w: "半途而废", p: ["bàn", "tú", "ér", "fèi"], e: "废停止。指做事不能坚持到底，中途停顿，有始无终。", s: "《礼记·中庸》君子遵道而行，半途而废，吾弗难已矣。”" },
  { w: "华而不实", p: ["huá", "ér", "bù", "shí"], e: "华开花。花开得好看，但不结果实。比喻外表好看，内容空虚。", s: "《晏子春秋·外篇·不合经术者》东海之中，有水而赤，其中有枣，华而不实，何也。”《左传·文公五年》且华而不实，怨之所聚也。”" },
  { w: "却之不恭", p: ["què", "zhī", "bù", "gōng"], e: "却推却。指对别人的邀请、赠与等，如果拒绝接受，就显得不恭敬。", s: "《孟子·万章下》却之却之为不恭。”" },
  { w: "口不应心", p: ["kǒu", "bù", "yìng", "xīn"], e: "应符合。心口不一致。", s: "明·冯梦龙《醒世恒言》卷八官人，你昨夜恁般说了，却又口不应心，做下那事！”" },
  { w: "可有可无", p: ["kě", "yǒu", "kě", "wú"], e: "可以有，也可以没有。指有没有都无关紧要。", s: "清·曹雪芹《红楼梦》第二十回因此把一切都看成浊物，可有可无。”" },
  { w: "史不绝书", p: ["shǐ", "bù", "jué", "shū"], e: "书指记载。史书上不断有记载。过去经常发生这样的事情。", s: "《左传·襄公二十九年》鲁之于晋也，职贡不乏，玩好时至，公卿大夫相继于朝，史不绝书。”" },
  { w: "叶公好龙", p: ["yè", "gōng", "hào", "lóng"], e: "叶公春秋时楚国贵族，名子高，封于叶（古邑名，今河南叶县）。比喻口头上说爱好某事物，实际上并不真爱好。", s: "汉·刘向《新序·杂事》记载叶公子高非常喜欢龙，器物上刻着龙，房屋上也画着龙。真龙知道了，来到叶公家里，把头探进窗子。叶公一见，吓得拔腿就跑。" },
  { w: "合二为一", p: ["hé", "èr", "wéi", "yī"], e: "指将两者合为一个整体。", s: "清·袁枚《新齐谐·佟觭角》一人劈面来，急走如飞，势甚猛，傅不及避，两胸相撞，竟与己身合二为一。”" },
  { w: "同年而语", p: ["tóng", "nián", "ér", "yǔ"], e: "犹言相提并论。把不同的人或不同的事放在一起谈论或看待。", s: "" },
  { w: "同德一心", p: ["tóng", "dé", "yī", "xīn"], e: "指全心全意为共同目标努力。", s: "" },
  { w: "同德同心", p: ["tóng", "dé", "tóng", "xīn"], e: "谓思想行动完全一致。同同心同德”。", s: "《旧唐书·马燧传》长城压境，巨舰济川，同德同心，扶危持颠。”明·罗贯中《平山冷燕》第一回然君臣同德同心，于兹可见。”" },
  { w: "同心一力", p: ["tóng", "xīn", "yī", "lì"], e: "团结一致，共同努力。同同心协力”。", s: "" },
  { w: "同心一德", p: ["tóng", "xīn", "yī", "dé"], e: "指思想统一，信念一致。同同心同德”。", s: "" },
  { w: "同心一意", p: ["tóng", "xīn", "yī", "yì"], e: "指心志一致。", s: "《三国志·吴志·鲁肃传》肃请得奉命吊表二子……及说备使抚表众，同心一意，共治曹操。”" },
  { w: "同心同德", p: ["tóng", "xīn", "tóng", "dé"], e: "同德为同一目的而努力。指思想统一，信念一致。", s: "《尚书·泰誓中》予有乱臣十人，同心同德。”" },
  { w: "同日而言", p: ["tóng", "rì", "ér", "yán"], e: "把不同的人或不同的事放在一起谈论或看待。同同日而论”。", s: "《晋书·郗鉴传》及愍怀太子之废，可谓柔而有正。武秋失节之士，何可同日而言！”" },
  { w: "同日而论", p: ["tóng", "rì", "ér", "lùn"], e: "犹言相提并论。把不同的人或不同的事放在一起谈论或看待。", s: "" },
  { w: "同日而语", p: ["tóng", "rì", "ér", "yǔ"], e: "指相提并论。", s: "《战国策·赵策二》夫破人之与破于人也，臣人之与臣于人也，岂可同日而言之哉？”" },
  { w: "同日而道", p: ["tóng", "rì", "ér", "dào"], e: "把不同的人或不同的事放在一起谈论或看待。同同日而论”。", s: "" },
  { w: "同然一辞", p: ["tóng", "rán", "yī", "cí"], e: "犹异口同声。指大家说得都一样。", s: "" },
  { w: "名不虚传", p: ["míng", "bù", "xū", "chuán"], e: "虚假。传出的名声不是虚假的。指实在很好，不是空有虚名。", s: "《史记·游侠列传》然其私意廉洁退让，有足称者，名不虚言，士不虚附。”" },
  { w: "名不虚得", p: ["míng", "bù", "xū", "dé"], e: "指盛名非凭空取得。", s: "" },
  { w: "名重一时", p: ["míng", "zhòng", "yī", "shí"], e: "名名声；一时当代。一个时期内名声很大，受到广泛重视。", s: "宋·释惟白《续传灯录》卷二十七师住径山时，名重一时，如侍郎张公子韶，状元汪公圣锡少卿、冯公济川俱问道。”" },
  { w: "后生小子", p: ["hòu", "shēng", "xiǎo", "zǐ"], e: "指年轻晚辈。", s: "宋·俞文豹《吹剑四录》恐数十年后老成凋丧，后生小子，不知根柢，耳濡目染，目变而复还。”" },
  { w: "后继无人", p: ["hòu", "jì", "wú", "rén"], e: "继继承。没有后人来继承前人的事业。", s: "" },
  { w: "后继有人", p: ["hòu", "jì", "yǒu", "rén"], e: "继继承。有后人继承前人的事业。", s: "艾芜《鞍钢呵，我回来了》这是后继有人，令人喜悦不止。”" },
  { w: "君子之交", p: ["jūn", "zǐ", "zhī", "jiāo"], e: "贤者之间的交情，平淡如水，不尚虚华。", s: "《庄子·山木》且君子之交淡若水，小人之交甘若醴；君子淡以亲，小人甘以绝。”" },
  { w: "听之任之", p: ["tīng", "zhī", "rèn", "zhī"], e: "听、任随，任凭；之代词，代人或事物。任凭事物存在发展而不去过问。", s: "毛泽东《反对自由主义》见损害群众利益的行为不愤恨，不劝告，不制止，不解释，听之任之。”" },
  { w: "周而不比", p: ["zhōu", "ér", "bù", "bǐ"], e: "周亲和、调合；比勾结。关系密切，但不勾结。指与众相合，但不做坏事。", s: "《论语·为政》子曰‘君子周而不比。’”" },
  { w: "和而不同", p: ["hé", "ér", "bù", "tóng"], e: "和和睦；同苟同⊥睦地相处，但不随便附和。", s: "《论语·子路》君子和而不同，小人同而不和。”" },
  { w: "和而不唱", p: ["hé", "ér", "bù", "chàng"], e: "赞同别人的意见，不坚持自己的说法。", s: "《庄子·德充符》和而不唱，知不出乎四城。”" },
  { w: "品而第之", p: ["pǐn", "ér", "dì", "zhī"], e: "品品评，区分；第等第，等级。品评优劣而后确定他的等级。", s: "《晋书·苻坚载记上》坚亲临太学，考学生经义优劣，品而第之。”" },
  { w: "喻之以理", p: ["yù", "zhī", "yǐ", "lǐ"], e: "喻晓喻，开导。用道理来开导说服人。", s: "" },
  { w: "四战之国", p: ["sì", "zhàn", "zhī", "guó"], e: "指四面平坦，无险可守，容易受攻击的地方。", s: "《商君书·兵守》四战之国贵守战，负海之国贵攻战。”《史记·乐毅列传》赵，四战之国也，其民习兵，伐之不可。”" },
  { w: "四战之地", p: ["sì", "zhàn", "zhī", "dì"], e: "指四面平坦，无险可守，容易受攻击的地方。", s: "《史记·乐毅列传》赵，四战之地也，其民习兵，伐之不可。”《后汉书·荀彧传》颖川，四战之地也，天下有变，常为兵冲。”" },
  { w: "四方之志", p: ["sì", "fāng", "zhī", "zhì"], e: "志志向。指远大的志向。亦作志在四方”。", s: "" },
  { w: "四时之气", p: ["sì", "shí", "zhī", "qì"], e: "本指一年四季的气象，后以备四时之气”喻指人的气度弘远。", s: "" },
  { w: "回天之力", p: ["huí", "tiān", "zhī", "lì"], e: "原比喻言论正确，极有力量，影响深远。现多比喻能挽回严重局势的力量。", s: "《魏书·帝纪篇末史臣总论》佞阉处当轴之权，婢媪擅回天之力，卖官鬻狱，乱政淫刑。”《新唐书·张玄素传》张公论事，有回天之力。”" },
  { w: "回天无力", p: ["huí", "tiān", "wú", "lì"], e: "回天比喻力量大，能移转极难挽回的时势；无力没有力量。比喻局势或病情严重，已无法挽救。", s: "清·冯起凤《昔柳摭谈·秋风自悼》后探得的耗，万箭攒心，脏腑欲裂。但木已成舟，回天乏术。”" },
  { w: "因人成事", p: ["yīn", "rén", "chéng", "shì"], e: "因依靠。依靠别人的力量办成事情。", s: "《史记·平原君虞卿列传》公等碌碌，所谓因人成事者也。”" },
  { w: "因人而异", p: ["yīn", "rén", "ér", "yì"], e: "因人的不同而有所差异。", s: "鲁迅《准风月谈·难得糊涂》然而风格和情绪、倾向之类，不但因人而异，而且因事而异，因时而异。”" },
  { w: "困而不学", p: ["kùn", "ér", "bù", "xué"], e: "困困惑，不明白。困惑不明白却不肯学习。", s: "《论语·季氏》生而知之者，上也；学而知之者，次也；困而学之，又其次也；困而不学，民斯为下矣。”" },
  { w: "困而学之", p: ["kùn", "ér", "xué", "zhī"], e: "困困惑。遇到困惑的时候就学习。", s: "《论语·季氏》生而知之者，上也；学而知之者，次也；困而学之，又其次也；困而不学，民斯为下矣。”" },
  { w: "国将不国", p: ["guó", "jiāng", "bù", "guó"], e: "国家将无法维持下去了。指国家的局势很坏，有亡国的危险。", s: "清·曾朴《孽海花》第三十二回庄寿香号称名臣，听说在和议开始时，他主张把台湾赠英……国将不国，这才是糊涂到底了呢！”" },
  { w: "国无二君", p: ["guó", "wú", "èr", "jūn"], e: "一个国家不能有两个皇帝。", s: "《礼记·丧服四制》天无二日，土无二王，国无二君，家无二尊。”" },
  { w: "在天之灵", p: ["zài", "tiān", "zhī", "líng"], e: "尊称死者的精神。", s: "鲁迅《而已集·黄花节的杂感》我并非说，大家都须天天去痛哭流涕，以凭吊先烈的‘在天之灵’，一年中有一天记住他们就可以了。”" },
  { w: "在所不辞", p: ["zài", "suǒ", "bù", "cí"], e: "决不推辞（多用在冒险犯难）。", s: "郭沫若《郑成功》第二章国姓爷和你是我的重生父母，只要能够为你们效劳，我就献出生命，在所不辞。”" },
  { w: "地利人和", p: ["dì", "lì", "rén", "hé"], e: "地利地理的优势；人和得人心。表示优越的地理条件和群众基础。", s: "《孟子·公孙丑下》天时不如地利，地利不如人和。”" },
  { w: "塞翁失马", p: ["sài", "wēng", "shī", "mǎ"], e: "塞边界险要之处；翁老头。比喻一时虽然受到损失，也许反而因此能得到好处。也指坏事在一定条件下可变为好事。", s: "《淮南子·人间训》近塞上之人有善术者，马无故亡而入胡。人皆吊之。其父曰‘此何遽不为铬？’居数月，其马将胡骏马而归。人皆贺之。…故福之为祸，祸之为福，化不可极，深不可测也。”" },
  { w: "备而不用", p: ["bèi", "ér", "bù", "yòng"], e: "准备好了，以备急用，眼下暂存不用。", s: "清·吴趼人《糊涂世界》虽说备而不用，到得那时候，听凭兵丁造一句谣言，开上几排枪，那人可就死了不少。”" },
  { w: "多事之秋", p: ["duō", "shì", "zhī", "qiū"], e: "多事事故或事变多；秋时期。事故或事变很多的时期。", s: "宋·孙光宪《北梦琐言》卷十二所以多事之秋，灭迹匿端，无为绿林之嚆矢也。”" },
  { w: "大人虎变", p: ["dà", "rén", "hǔ", "biàn"], e: "虎变如虎身花纹的变化。比喻居上位者出处行动变化莫测。", s: "《周易·革》大人虎变，未占有孚。”" },
  { w: "大失人望", p: ["dà", "shī", "rén", "wàng"], e: "指在群众中严重丧失威望，威信扫地。", s: "《史记·高祖本记》秦人大失望。”" },
  { w: "大得人心", p: ["dà", "dé", "rén", "xīn"], e: "人心即民心。指受百姓热烈拥护。", s: "《魏书·昭成子孙传》太祖命督屯田于河北，自五原至棝杨塞外，分农稼，大得人心。”" },
  { w: "大快人心", p: ["dà", "kuài", "rén", "xīn"], e: "快痛快。指坏人坏事受到惩罚或打击，使大家非常痛快。", s: "明·许三阶《节侠记·诛佞》李秦授这厮，今日圣旨杀他，大快人心；兄请正坐了，就决了他，使小弟得以快睹。”" },
  { w: "大方之家", p: ["dà", "fāng", "zhī", "jiā"], e: "大方大道理。原指懂得大道理的人◇泛指见识广博或学有专长的人。", s: "《庄子·秋水》吾长见笑于大方之家。”" },
  { w: "大是大非", p: ["dà", "shì", "dà", "fēi"], e: "指带有原则性、根本性的是非问题。", s: "徐迟《歌德巴赫猜想》一页一页的历史写出来了，大是大非，终于有了无私的公论。”" },
  { w: "大有人在", p: ["dà", "yǒu", "rén", "zài"], e: "形容某一种人为数不少。", s: "《资治通鉴·隋纪炀帝大业十一年》帝至东都，顾眄街衢，谓侍臣曰‘犹大有人在。’意谓向日平杨玄感，杀人尚少故也。”" },
  { w: "大有可观", p: ["dà", "yǒu", "kě", "guān"], e: "指很值得看，很值得重视。", s: "" },
  { w: "大有文章", p: ["dà", "yǒu", "wén", "zhāng"], e: "指话语、文章、或已表露的现象之中，很有令人难以捉摸的意思或别的情况。", s: "清·无名氏《三侠五义》艾虎听了，暗暗思忖道‘这话语之中大有文章。’”" },
  { w: "大有见地", p: ["dà", "yǒu", "jiàn", "dì"], e: "很有见解。", s: "" },
  { w: "大而化之", p: ["dà", "ér", "huà", "zhī"], e: "化改变，转变。原指大行其道，使天下化之◇形容做事情不小心谨慎。", s: "《孟子·尽心下》大而化之之谓圣。”" },
  { w: "大言不惭", p: ["dà", "yán", "bù", "cán"], e: "说大话，不感到难为情。", s: "《论语·宪问》子曰‘其言之不怍，则为之也难。’”宋·朱熹注大言不惭，则无必为之志，而不自度其能否也。欲践其言，其不难哉！”" },
  { w: "大辩不言", p: ["dà", "biàn", "bù", "yán"], e: "大辩善于辩论。有口才、善于辩论的人，并不多说话以显示自己。", s: "《庄子·齐物论》大辩不言，大仁不仁。”" },
  { w: "大逆不道", p: ["dà", "nì", "bù", "dào"], e: "逆叛逆；道指封建道德；不道违反封建道德。旧时统治阶级对破坏封建秩序的人所加的重大罪名。", s: "《史记·高祖本纪》天下所不容，大逆无道。”《汉书·杨恽传》为妖恶言，大逆不道，请逮捕治。”" },
  { w: "天上人间", p: ["tiān", "shàng", "rén", "jiān"], e: "一个在天上，一个在人间。多比喻境遇完全不同。", s: "南唐·李煜《浪淘沙》词流水落花春去也，天上人间。”" },
  { w: "天下一家", p: ["tiān", "xià", "yī", "jiā"], e: "视天下人为一家，和睦相处。也指全国统一。", s: "《礼记·礼运》故圣人耐以天下为一家，以中国为一人者，非意之也。”" },
  { w: "天下无敌", p: ["tiān", "xià", "wú", "dí"], e: "普天之下，没有敌手。形容战无不胜，没有对手。", s: "《孟子·离娄上》夫国君好仁，天下无敌。”" },
  { w: "天下第一", p: ["tiān", "xià", "dì", "yī"], e: "形容没有人能比得上。", s: "《后汉书·胡广传》试以章奏，安帝以广为天下第一。”" },
  { w: "天不作美", p: ["tiān", "bù", "zuò", "měi"], e: "天不成全美事。多指要进行的事情因刮风下雨而受到了影响。", s: "孙犁《芸斋琐谈（四）》天不作美，忽然飘起雪花来。”" },
  { w: "天不假年", p: ["tiān", "bù", "jiǎ", "nián"], e: "假给予。天公不给以寿命。指寿命不长。", s: "清·平步青《霞外裙屑》卷六予以先生此考，为一生心力所瘁，成以行世，足为读史者一助，惜天不假年，积四十六年之岁月，仅成全史三之一。”" },
  { w: "天不绝人", p: ["tiān", "bù", "jué", "rén"], e: "天不使人处于绝境。常指绝处逢生或得救。", s: "" },
  { w: "天与人归", p: ["tiān", "yǔ", "rén", "guī"], e: "旧指帝王受命于天，并得到人民拥护。", s: "《孟子·万章上》‘然则舜有天下也，孰与之？’曰‘天与之。’”明·史可法《复清摄政睿亲王书》名正言顺，天与人归。”" },
  { w: "天之骄子", p: ["tiān", "zhī", "jiāo", "zǐ"], e: "骄子父母溺爱骄纵的儿子。老天爷的宠儿。原指强盛的北方民族胡人，后也指为父母溺爱、放肆不受管束的儿子。", s: "《汉书·匈奴传上》南有大汉，北有强胡→者，天之骄子也。”" },
  { w: "天人之际", p: ["tiān", "rén", "zhī", "jì"], e: "天自然规律；人人事；际际遇。自然和人事之间的相互关系。", s: "汉·司马迁《报任少卿书》亦欲以究天人之际，通古今之变，成一家之言。”" },
  { w: "天从人原", p: ["tiān", "cóng", "rén", "yuán"], e: "指事情的发展恰如所望。", s: "" },
  { w: "天作之合", p: ["tiān", "zuò", "zhī", "hé"], e: "合配合∶象是上天给予安排，很完美地配合到一起。祝人婚姻美满的话。", s: "《诗经·大雅·大明》天监在下，有命既集，文王初载，天作之合。”" },
  { w: "天地不容", p: ["tiān", "dì", "bù", "róng"], e: "天地天地之间，人世间。容宽容。天地所不能容纳。指大逆不道、罪孽深重的人与事。", s: "" },
  { w: "天外有天", p: ["tiān", "wài", "yǒu", "tiān"], e: "指某一境界之外更有无穷无尽的境界。多用来表示人的眼界受客观条件的限制，认识的领域需要不断扩大。也表示美好的境界阅历不尽。亦作山外有山”、峰外有峰”", s: "《敦煌曲·何满子四首》其四金河一去路千千，欲到天边更有天。”" },
  { w: "天大地大", p: ["tiān", "dà", "dì", "dà"], e: "形容极大。", s: "" },
  { w: "天年不遂", p: ["tiān", "nián", "bù", "suì"], e: "指未享天年。", s: "《后汉书·安帝纪》岂意卒然颠沛，天年不遂，悲痛断心。”《乐府诗集·相和歌辞十四·雁门太守行一》天年不遂，早就奄昏。”" },
  { w: "天年不齐", p: ["tiān", "nián", "bù", "qí"], e: "指命运和流年不相配合，以致运道不好。", s: "明·施耐庵《水浒传》第八回张教头道‘贤婿，甚么言语！你是天年不齐，遭了横事，又不是你作将出来的。’”" },
  { w: "天无二日", p: ["tiān", "wú", "èr", "rì"], e: "日太阳，比喻君王。天上没有两个太阳。旧喻一国不能同时有两个国君。比喻凡事应统于一，不能两大并存。", s: "《礼记·曾子问》天无二日，土无二王，家无二主，尊无二上。”" },
  { w: "天王老子", p: ["tiān", "wáng", "lǎo", "zǐ"], e: "比喻至尊至贵、最有权威的人。", s: "" },
  { w: "天理不容", p: ["tiān", "lǐ", "bù", "róng"], e: "天理天道；容容忍、宽容。旧指做事残忍，灭绝人性，为天理所不容。", s: "元·无名氏《朱砂担》第四折才见得冤冤相报，方信道天理难容。”" },
  { w: "天理人情", p: ["tiān", "lǐ", "rén", "qíng"], e: "天然的道理和人的常情。", s: "清·文康《儿女英雄传》第三十六回你可晓得一念不违天理人情，天地鬼神会暗中阿护；一念背了天理人情，天地鬼神也就会立刻不容。”" },
  { w: "天道人事", p: ["tiān", "dào", "rén", "shì"], e: "天道天理。人事人力所能做到的事。天道人事不可违背。意谓大势所趋。", s: "《元史·谦希宪传》因为书与宋四川统制余玠，谕以天道人事，玠得书愧感自守，不敢复轻动。”" },
  { w: "天道无亲", p: ["tiān", "dào", "wú", "qīn"], e: "亲亲近。公正，不偏不倚。", s: "《老子》第七十九章天道无亲，常与善人。”" },
  { w: "天高地下", p: ["tiān", "gāo", "dì", "xià"], e: "①比喻尊卑有别。②比喻各种情势。", s: "" },
  { w: "太平无事", p: ["tài", "píng", "wú", "shì"], e: "指时世安宁和平，也指生活清静无忧。", s: "明·焦竑《玉堂丛语·方正》惟高堂厚禄身享太平无事之日者，见月则乐也。”" },
  { w: "夫子自道", p: ["fū", "zǐ", "zì", "dào"], e: "指本意是说别人好处，而事实上却正道着了自己。也用在不好的一面，意思是指摘别人，却正指摘了自己。", s: "《论语·宪问》子曰‘君子有道者三，我无能焉；仁者不忧，智者不惑，勇者不惧。’子贡曰‘夫子自道也。’”" },
  { w: "头一无二", p: ["tóu", "yī", "wú", "èr"], e: "唯一，只有一个。", s: "" },
  { w: "头面人物", p: ["tóu", "miàn", "rén", "wù"], e: "指在社会上有较大名声或势力而又经常抛头露面的人。", s: "王蒙《悠悠寸草心》小小的理发室也反映着人世的沧桑，何况到这里来整容的颇多头面人物。”" },
  { w: "好恶不同", p: ["hǎo", "è", "bù", "tóng"], e: "爱好和憎恶各不相同。形容人的志趣、志向和思想感情各异。", s: "" },
  { w: "好梦不长", p: ["hǎo", "mèng", "bù", "cháng"], e: "指不切实际的幻想是不能实现的，只能存在于梦幻之中。", s: "" },
  { w: "如出一口", p: ["rú", "chū", "yī", "kǒu"], e: "象从一张嘴里说出来的。形容许多人说法一样。", s: "《韩非子·内储说下》州侯相荆，贵而主断，荆王疑之，因问左右，左右对曰‘无有’，如出一口也。”" },
  { w: "如无其事", p: ["rú", "wú", "qí", "shì"], e: "象没有那回事一样。形容遇事沉着镇定或不把事情放在心上。", s: "清·李宝嘉《官场现形记》第十八回统领听不见，庄大老爷也听不见，就作为如无其事，不去提他了。”" },
  { w: "如有所失", p: ["rú", "yǒu", "suǒ", "shī"], e: "好像丢失了什么似的。形容心神不安的样子。也形容心里感到空虚。", s: "南朝·宋·刘义庆《世说新语·德行》则鄙吝之心已复生矣。”南朝宋·刘孝标注怅然若有所失。”" },
  { w: "妇人之仁", p: ["fù", "rén", "zhī", "rén"], e: "仕仁慈。妇女的软心肠。旧指处事姑息优柔，不识大体。", s: "《史记·淮阴侯列传》项王见人，恭敬慈爱，言语呕呕，人有疾病，涕泣分食饮，至使人有功，当封爵者，印刓弊，忍不能予，此所谓妇人之仁也。”" },
  { w: "妙不可言", p: ["miào", "bù", "kě", "yán"], e: "妙美妙。形容好得难以用文字、语言表达。", s: "晋·郭璞《江赋》经纪天地，错综人术，妙不可尽之于言，事不可穷之于笔。”" },
  { w: "妙处不传", p: ["miào", "chù", "bù", "chuán"], e: "指精微奥妙的地方不是言语和笔墨所能表达的。", s: "宋·黄庭坚《戏题小雀飞虫画扇》诗丹青妙处不可传，轮扁斫轮如此用。”" },
  { w: "存而不论", p: ["cún", "ér", "bù", "lùn"], e: "存保留。指把问题保留下来，暂不讨论。", s: "《庄子·齐物论》六合之外，圣人存而不论。”" },
  { w: "学而不厌", p: ["xué", "ér", "bù", "yàn"], e: "厌满足。学习总感到不满足。形容好学。", s: "《论语·述而》默而识之，学而不厌，诲人不倦，何有于我哉？”" },
  { w: "守株待兔", p: ["shǒu", "zhū", "dài", "tù"], e: "株露出地面的树根。原比喻希图不经过努力而得到成功的侥幸心理。现也比喻死守狭隘经验，不知变通。", s: "《韩非子·五蠹》记载战国时宋国有一个农民，看见一只兔子撞在树根上死了，便放下锄头在树根旁等待，希望再得到撞死的兔子。" },
  { w: "安然无事", p: ["ān", "rán", "wú", "shì"], e: "犹言平安无事。", s: "清·夏敬渠《野叟曝言》第三十二回四嫂不来聒噪，耳根清净，倒也安然无事，除非把你两家合成一家，我一个人就好照顾了。”" },
  { w: "安身之地", p: ["ān", "shēn", "zhī", "dì"], e: "存身的地方。批在某地居住、生活，或以某地作为建业的根基。", s: "明·罗贯中《三国演义》第四十回近闻刘景升病在危笃，可乘此机会，取得荆州为安身之地。”" },
  { w: "害人不浅", p: ["hài", "rén", "bù", "qiǎn"], e: "给别人的损害非常之大。", s: "清·李汝珍《镜花缘》第九十五回即如今人凡遇小儿惊风，害人不浅。”" },
  { w: "家至人说", p: ["jiā", "zhì", "rén", "shuō"], e: "传到每一家，人人都知道。", s: "《汉书·匡衡传》臣闻教化之流之流，非家至而人说之也。”" },
  { w: "容膝之地", p: ["róng", "xī", "zhī", "dì"], e: "形容居室的狭窄。", s: "" },
  { w: "寂若无人", p: ["jì", "ruò", "wú", "rén"], e: "寂寂静。寂静得就像没有人一样。", s: "南朝·宋·刘义庆《世说笺本·德行下》傅茂远泊然静处，不妄交游民，袁司徒第经其户，辄叹曰‘经其户寂若无人，披其帷，其人斯在。岂得非名贤。’”" },
  { w: "对牛弹琴", p: ["duì", "niú", "tán", "qín"], e: "讥笑听话的人不懂对方说得是什么。用以讥笑说话的人不看对象。", s: "汉·牟融《理惑论》公明仪为牛弹清角之操，伏食如枚。非牛不闻，不合其耳矣。”" },
  { w: "将心比心", p: ["jiāng", "xīn", "bǐ", "xīn"], e: "设身处地地为别人着想。", s: "宋·朱熹《朱子语类·大学三》俗语所谓将心比心，如此则各得其平矣。”" },
  { w: "将无作有", p: ["jiāng", "wú", "zuò", "yǒu"], e: "把没有的事情当作有。", s: "元·康进之《李逵负荆》第一折不要你将无来作有，则要你依前来依后。”" },
  { w: "将无做有", p: ["jiāng", "wú", "zuò", "yǒu"], e: "把没有的事情当作有。同将无作有”。", s: "" },
  { w: "小人得志", p: ["xiǎo", "rén", "dé", "zhì"], e: "小人指道德低下或行为不正派的人。指人格卑下的人人取得了权势。", s: "南朝·宋·何承天《为谢晦檄京邑》若使小人得志，君子道消。”" },
  { w: "小大由之", p: ["xiǎo", "dà", "yóu", "zhī"], e: "指用途可大可小。", s: "《论语·学而》礼之用，和为贵。……小大由之。”" },
  { w: "小子后生", p: ["xiǎo", "zǐ", "hòu", "shēng"], e: "泛指少年后辈。", s: "唐·韩愈《送温处士赴河阳军序》小子后生，于何考德而问业焉。”" },
  { w: "小小不言", p: ["xiǎo", "xiǎo", "bù", "yán"], e: "指细微的，不值得一提的。", s: "清·李宝嘉《官场现形记》第四十四回我同你老实说彼此顾交情，留下脸，小小不言的事情，我也不追究了。”" },
  { w: "小心翼翼", p: ["xiǎo", "xīn", "yì", "yì"], e: "翼翼严肃谨慎。本是严肃恭敬的意思。现形容谨慎小心，一点不敢疏忽。", s: "《诗经·大雅·大明》维此文王，小心翼翼。”" },
  { w: "就事论事", p: ["jiù", "shì", "lùn", "shì"], e: "按照事物本身的性质来评定是非得失。现常指仅从事物的表面现象孤立、静止、片面地议论。", s: "明·沈德符《万历野获编·词臣论劾首揆》夺情大事，有关纲常，且就事论事，未尝旁及云。”" },
  { w: "尽如人意", p: ["jìn", "rú", "rén", "yì"], e: "尽全；如依照，符合。事情完全符合人的心意。", s: "宋·刘克庄《后村全集·李艮翁礼部墓志铭》然议者但以为恩泽侯挟贵临民，安得尽如人意。”" },
  { w: "局外之人", p: ["jú", "wài", "zhī", "rén"], e: "局外原指棋局之外，引申为事外。指与某件事情没有关系的人。", s: "宋·刘克庄《象弈》君看橘中戏，妙不出局外。”" },
  { w: "居之不疑", p: ["jū", "zhī", "bù", "yí"], e: "居处于；不疑不疑惑。对自己所处的地位，毫不怀疑。", s: "清·李宝嘉《文明小史》第五十五回且说秦凤梧跟了张露竹洋行里那班人，天天闹在一起，吃喝顽笑，大家知道他是个有钱的财主，恭维他观察长，观察短，秦凤梧也居之不疑。”" },
  { w: "居大不易", p: ["jū", "dà", "bù", "yì"], e: "本为唐代诗人顾况以白居易的名字开玩笑◇比喻居住在大城市，生活不容易维持。", s: "唐·张固《幽闲鼓吹》白尚书应举，初至京，以诗谒著作顾况，顾睹姓名，熟视白公曰‘米价方贵，居亦弗易。’”" },
  { w: "平安无事", p: ["píng", "ān", "wú", "shì"], e: "平平安安，没出什么事故。", s: "元·无名氏《昊天塔孟良盗骨》第二折哥哥将令，着兄弟巡界河去，平安无事，回哥哥的话来。”" },
  { w: "应天从人", p: ["yìng", "tiān", "cóng", "rén"], e: "应顺，顺应。上顺天命，下适应民意。旧常用作颂扬建立新的朝代。亦作应天从民”、应天从物”。", s: "" },
  { w: "度外之人", p: ["dù", "wài", "zhī", "rén"], e: "度外心在计度之外。指与某人或某集团没有关系或关系不近的人。即局外人。", s: "《三国志·魏志·杨阜传》曹公有雄才远略，决机无疑，法一而兵精，能用度外之人，所任各尽其力，必能济大事者也。”" },
  { w: "引而不发", p: ["yǐn", "ér", "bù", "fā"], e: "引拉弓；发射箭。拉开弓却不把箭射出去。比喻善于启发引导。也比喻做好准备暂不行动，以待时机。", s: "《孟子·尽心上》君子引而不发，跃如也。中道而立，能者从之。”" },
  { w: "张大其事", p: ["zhāng", "dà", "qí", "shì"], e: "张夸张。把原来的事情夸大。形容言过其实。亦作张皇其事”、张大其辞（词）”、张扬其事”。", s: "唐·韩愈《送杨少尹序》太史氏又能张大其事，为传继二疏踪迹否？”" },
  { w: "当之无愧", p: ["dāng", "zhī", "wú", "kuì"], e: "无愧毫无愧色。当得起某种称号或荣誉，无须感到惭愧。", s: "宋·欧阳修《回丁判官书》夫人有厚己而自如者，恃其中有所以当之而不愧也。”" },
  { w: "得人死力", p: ["dé", "rén", "sǐ", "lì"], e: "死力以死效力。得到别人以死来效力。形容非常得人拥护。", s: "" },
  { w: "得失在人", p: ["dé", "shī", "zài", "rén"], e: "指人生的胜利失败就取决与本人的努力与否。强调人的主观能动性。", s: "" },
  { w: "得意之作", p: ["dé", "yì", "zhī", "zuò"], e: "指自己认为非常满意的作品。", s: "曹靖华《哪有闲情话年月》作者仿佛要为我开小型展览会似的，把自己的得意之作都陈列在我面前了。”" },
  { w: "得意之色", p: ["dé", "yì", "zhī", "sè"], e: "得意称心如意。因非常称心如意而露出傲慢的神色。", s: "鲁迅《书信集·答有恒先生》血的游戏已经开头，而角色又是青年，并且有得意之色。”" },
  { w: "心上心下", p: ["xīn", "shàng", "xīn", "xià"], e: "形容心神不安。", s: "巴金《家》二三觉新连忙到房里去把信写好，叫袁成送去。但是这也还不能使众人安心。众人还是心上心下的，害怕送信的袁成还没有回来，一连兵就开进来了。”" },
  { w: "心不两用", p: ["xīn", "bù", "liǎng", "yòng"], e: "指一个人的心思一时只能专注于一事。", s: "北齐·刘昼《新论·专学》使左手画方，右手画圆，令一时具成，虽执规矩之心，回剟劂之手，而不能者，由心不两用，则手不并运也。”" },
  { w: "心不在焉", p: ["xīn", "bù", "zài", "yān"], e: "心思不在这里。指思想不集中。", s: "《礼记·大学》心不在焉，视而不见，听而不闻，食而不知其味。”" },
  { w: "心不应口", p: ["xīn", "bù", "yīng", "kǒu"], e: "心里想的和嘴里说的不一致。指为人虚伪。", s: "明·杨德芳《步步娇·闺怨》曲恨他心不应口，把欢娱翻成僝僽。情儿泛泛，浑如江水流。”" },
  { w: "心不由意", p: ["xīn", "bù", "yóu", "yì"], e: "指不出于本意。", s: "《红楼梦》第七二回那彩霞之母满心纵不愿意，见风姐亲自和他说，何等体面，便心不由意的满口应了出去。”" },
  { w: "心中无数", p: ["xīn", "zhōng", "wú", "shù"], e: "指对情况了解不清楚，心里没有底。", s: "姚雪垠《李自成》第二卷第三十一章周后心中无数，说‘象这样小事，你自己斟酌去办，用不着向我请旨。’”" },
  { w: "心中有数", p: ["xīn", "zhōng", "yǒu", "shù"], e: "对情况和问题有基本的了解，处理事情有一定把握。", s: "冯德英《迎春花》第八章春玲要先同儒春谈一次，摸摸他的底，心中有数，为她去和老东山交锋做准备。”" },
  { w: "心口不一", p: ["xīn", "kǒu", "bù", "yī"], e: "心里想的和嘴上说的不一样。形容人的虚伪、诡诈。", s: "《醒世姻缘传》第八十二回我是这们个直性子，媳就说媳，不是这们心口不一的。”" },
  { w: "心口如一", p: ["xīn", "kǒu", "rú", "yī"], e: "心里想的和嘴里说的一样。形容诚实直爽。", s: "清·李汝珍《镜花缘》第六十五回紫芝妹妹嘴虽厉害，好在心口如一，直截了当，倒是一个极爽快的。”" },
  { w: "心无二用", p: ["xīn", "wú", "èr", "yòng"], e: "指做事要专心，注意力必须集中。", s: "汉·桓谭《新论·专学》使左手画方，右手画圆，令一时俱成，虽执规矩之心，回剟劂之手，而不能成者，由心不两用，则手不并运也。”" },
  { w: "心比天高", p: ["xīn", "bǐ", "tiān", "gāo"], e: "形容心地高傲或所想超过现实。", s: "清·曹雪芹《红楼梦》第五回霁月难逢，彩云易散。心比天高，身为下贱。”" },
  { w: "心知其意", p: ["xīn", "zhī", "qí", "yì"], e: "意意义。心中领会了文章的主旨或技艺的要领。", s: "《史记·五帝本纪》书缺有间矣，心知其意，固难为浅见寡闻道也。”" },
  { w: "心神不定", p: ["xīn", "shén", "bù", "dìng"], e: "定安定。心里烦躁，精神不安。", s: "清·曹雪芹《红楼梦》第一百十三回便把丰儿等支开，叫刘老老坐在床前，告诉他心神不宁，如见鬼的样子。”" },
  { w: "必不得已", p: ["bì", "bù", "dé", "yǐ"], e: "必然不能得止。指形势使得非如此不可。表示无可奈何的意思。", s: "《论语·颜渊》子贡问政。子曰‘足食，足兵，民信之矣。’子贡曰‘必不得已而去，于斯三者何先？’曰‘去兵。’”" },
  { w: "急人之困", p: ["jí", "rén", "zhī", "kùn"], e: "热心主动帮助别人解决困难。", s: "《史记·魏公子列传》胜所以自附为婚姻者，以公子之高义，为能急人之困。”" },
  { w: "急人之难", p: ["jí", "rén", "zhī", "nán"], e: "热心主动帮助别人解决困难。", s: "《诗经·小雅·常棣》脊令在原，兄弟急难。”《史记·魏公子列传》胜所以自附为婚姻者，以公子之高义，为能急人之困。”" },
  { w: "总而言之", p: ["zǒng", "ér", "yán", "zhī"], e: "总的说起来。", s: "《容斋随笔·卷六·洗儿金钱》若总而言之，殆不可胜算。”" },
  { w: "恋恋不舍", p: ["liàn", "liàn", "bù", "shě"], e: "恋恋爱慕，留恋。原形容极其爱慕，不能丢开。现多形容非常留恋，舍不得离开。", s: "《史记·范睢传》然公之所以得无死者，以绨袍恋恋，有故人之间，故释公。”宋·王明清《挥尘后录》卷六（蔡）元度送之郊外，促膝剧谈，恋恋不能舍。”" },
  { w: "悔之不及", p: ["huǐ", "zhī", "bù", "jí"], e: "后悔也来不及了。", s: "《后汉书·光武帝纪》反水不收，后悔无及。”" },
  { w: "情不可却", p: ["qíng", "bù", "kě", "què"], e: "情面上不能推却。", s: "清·李汝珍《镜花缘》第六十回闺臣、红蕖众姊妹也再再相留，紫菱情不可却，只得应允。”" },
  { w: "情不自已", p: ["qíng", "bù", "zì", "yǐ"], e: "犹情不自禁。感情激动得不能控制。强调完全被某种感情所支配。", s: "" },
  { w: "情不自禁", p: ["qíng", "bù", "zì", "jīn"], e: "禁抑制。感情激动得不能控制。强调完全被某种感情所支配。", s: "南朝梁·刘遵《七夕穿针》诗步月如有意，情来不自禁。”" },
  { w: "情同一家", p: ["qíng", "tóng", "yī", "jiā"], e: "比喻情谊深厚，如同一家。", s: "" },
  { w: "情有可原", p: ["qíng", "yǒu", "kě", "yuán"], e: "按情理，有可原谅的地方。", s: "《后汉书·霍胥传》光之所至，情既可原，而守阙连年，终不见理。”" },
  { w: "惊弓之鸟", p: ["jīng", "gōng", "zhī", "niǎo"], e: "被弓箭吓怕了的鸟不容易安定。比喻经过惊吓的人碰到一点动静就非肠怕。", s: "《战国策·楚策四》；《晋书·王鉴传》黩武之众易动，惊弓之鸟难安。”" },
  { w: "惨无人理", p: ["cǎn", "wú", "rén", "lǐ"], e: "犹言惨无人道。指残酷狠毒到极点，如野兽一样。", s: "孙中山《临时大总统宣告各友邦书》严弄峻制，惨无人理。任法吏之妄为，丝毫不加限制，人命呼吸，悬于法官之意旨。”" },
  { w: "惨无人道", p: ["cǎn", "wú", "rén", "dào"], e: "惨狠毒，残暴。残酷狠毒到极点，如野兽一样。", s: "蔡东藩《唐史演义》第五十二回将妃、主等人，一一剖心致祭，惨无人道。”" },
  { w: "意想不到", p: ["yì", "xiǎng", "bù", "dào"], e: "料想不到，没有料到。", s: "清·李汝珍《镜花缘》第二回今日这般寒冷，满天雪片飘扬，仙姑忽来下顾，真是意想不到。”" },
  { w: "愚公移山", p: ["yú", "gōng", "yí", "shān"], e: "比喻坚持不懈地改造自然和坚定不移地进行斗争。", s: "《列子·汤问》记载愚公家门前有两大座山挡着路，他决心把山平掉，另一个老人智叟笑他太傻，认为不能能。愚公说我死了有儿子，儿子死了还有孙子，子子孙孙是没有穷尽的，两座山终究会凿平。" },
  { w: "成事不说", p: ["chéng", "shì", "bù", "shuō"], e: "说解说。原指事情已成，不要在解说；后指事情已过，不要再解说。", s: "《论语·八佾》子闻之曰‘成事不说，遂事不谏，既往不咎。’”邢昺疏‘事已成不可复说也。’" },
  { w: "成人之善", p: ["chéng", "rén", "zhī", "shàn"], e: "成全别人做善事。", s: "《魏书·礼志四》况乃官历士流，当训章之运，而以庶叔之嫌，替其嫡重之位，未是成人之善也。”" },
  { w: "成人之美", p: ["chéng", "rén", "zhī", "měi"], e: "成成就。成全别人的好事。", s: "《论语·颜渊》君子成人之美，不成人之恶。小人反是。”" },
  { w: "战无不克", p: ["zhàn", "wú", "bù", "kè"], e: "攻战没有不取胜的。形容强大无比，可以战胜一切。", s: "清·昭梿《啸亭续录·转庵和尚》将军之事吴王亦至矣，为之辟地攻城，战无不克，数月之间招徕数郡。”" },
  { w: "战无不胜", p: ["zhàn", "wú", "bù", "shèng"], e: "形容强大无比，可以战胜一切。也比喻办任何事情都能成功。", s: "《战国策·齐策二》战无不胜而不知止者，身且死，爵且后归，犹为蛇足也。”" },
  { w: "手不应心", p: ["shǒu", "bù", "yīng", "xīn"], e: "犹言力不从心。心里想做，可是力量够不上。", s: "明·冯梦龙《警世通言》第三十二卷日往月来，不觉一年有余，李公子囊箧渐渐空虚，手不应心，妈妈也就怠慢了。”" },
  { w: "持之有故", p: ["chí", "zhī", "yǒu", "gù"], e: "持持论，主张；有故有根据。指所持的见解和主张有一定的根据。", s: "《荀子·非十二子》然而其持之有故，其言之成理。”" },
  { w: "指不胜屈", p: ["zhǐ", "bù", "shèng", "qū"], e: "指手指；屈弯曲。扳着指头数也数不过来。形容为数很多。", s: "清·陈康祺《郎潜记闻》本朝大臣夺情任事者，指不胜屈。”" },
  { w: "指事类情", p: ["zhǐ", "shì", "lèi", "qíng"], e: "谓阐述事理，譬喻情状。", s: "《史记·老子韩非列传》然善属书离辞，指事类情，用剽剥儒、墨，虽当世宿学不能自解免。”" },
  { w: "指日可下", p: ["zhǐ", "rì", "kě", "xià"], e: "表示不久就可以攻下。", s: "郭沫若《革命春秋·北伐途次》这最后的抵抗如被冲破，武昌城便指日可下。”" },
  { w: "指日而待", p: ["zhǐ", "rì", "ér", "dài"], e: "指不久即可实现。同指日可待”。", s: "清·褚人获《隋唐演义》第七十一回将来执掌昭阳，可指日而待，为何夫人双眉反蹙起来？”" },
  { w: "掩耳盗铃", p: ["yǎn", "ěr", "dào", "líng"], e: "掩遮蔽，遮盖；盗偷。偷铃铛怕别人听见而捂住自己的耳朵。比喻自己欺骗自己，明明掩盖不住的事情偏要想法子掩盖。", s: "《吕氏春秋·自知》百姓有得钟者，欲负而走，则钟大不可负。以椎毁之，钟况然有声。恐人闻之而夺己也，遽掩其耳。”" },
  { w: "政令不一", p: ["zhèng", "lìng", "bù", "yī"], e: "发出的命令不统一。形容军务或政务混乱。", s: "《左传·昭公二十三年》帅贱多宠，政令不壹。”《三国志·魏志·武帝纪 》吾知绍之为人，志大而智小，色厉而胆薄，忌克而少威，兵多而分画不明，将骄而政令不一，土地虽广粮食虽丰，适足以为吾奉也。”" },
  { w: "政清人和", p: ["zhèng", "qīng", "rén", "hé"], e: "政治清明，人心归向，上下团结。", s: "《晋书·诸葛恢传》会稽内史诸葛恢莅官三年，政清人和，为诸郡首。”" },
  { w: "故人之意", p: ["gù", "rén", "zhī", "yì"], e: "故人旧友。指老朋友的情意。", s: "西汉·司马迁《史记·范雎蔡泽列传》然公之所以得无死者，以绨袍恋恋，有故人之意，故释公。”" },
  { w: "敬而远之", p: ["jìng", "ér", "yuǎn", "zhī"], e: "表面上表示尊敬，实际上不愿接近。也用作不愿接近某人的讽刺话。", s: "《论语·雍也》务民之义，敬鬼神而远之。”" },
  { w: "文人学士", p: ["wén", "rén", "xué", "shì"], e: "泛指文人、文士。", s: "" },
  { w: "文人相轻", p: ["wén", "rén", "xiāng", "qīng"], e: "指文人之间互相看不起。", s: "三国魏·曹丕《典论·论文》文人相轻，自古而然。”" },
  { w: "文似其人", p: ["wén", "sì", "qí", "rén"], e: "文章的风格与作者本人相似。", s: "" },
  { w: "文如其人", p: ["wén", "rú", "qí", "rén"], e: "指文章的风格同作者的性格特点相似。", s: "宋·苏轼《答张文潜书》子由之文实胜仆，而世俗不知，乃以为不如；其为人深不愿人知之，其文如其为人。”" },
  { w: "文武之道", p: ["wén", "wǔ", "zhī", "dào"], e: "指周文王、周武王治理国家的方法。", s: "先秦·孔子《论语·子张》文武之道未坠于地，在人，贤者识其大者。”" },
  { w: "文理不通", p: ["wén", "lǐ", "bù", "tōng"], e: "指文章在词句和内容方面都行不通。", s: "《旧五代史·选举志》况此等多不究义，唯攻帖书，文理既不甚通，名第岂可妄与？”" },
  { w: "文风不动", p: ["wén", "fēng", "bù", "dòng"], e: "一点儿也不动。形容没有丝毫损坏或改变。", s: "清·曹雪芹《红楼梦》第二十九回偏生那玉坚硬非常，摔了一下，竟文风不动。”" },
  { w: "斗南一人", p: ["dǒu", "nán", "yī", "rén"], e: "斗南北斗星以南。指天下，海内。指天下绝无仅有的人才。形容品德或才识独一无二。", s: "《新唐书·狄仁杰传》狄公之贤，北斗之南，一人而已。”" },
  { w: "新人新事", p: ["xīn", "rén", "xīn", "shì"], e: "具有新的道德品质的人和体现新的高尚社会风尚的事。", s: "" },
  { w: "方外之人", p: ["fāng", "wài", "zhī", "rén"], e: "方外世外。原指言行超脱于世俗礼教之外的人◇指僧道。", s: "《庄子·大宗师》彼游方之外者也。”" },
  { w: "旁若无人", p: ["páng", "ruò", "wú", "rén"], e: "身旁好象没有人。形容态度傲慢，不把别人放在眼里。", s: "《史记·刺客列传》荆轲嗜酒，日与狗屠及高渐离饮于燕市，酒酣以往，高渐离击筑，荆柯和而歌市中，相乐也，已而相泣，旁若无人者。”" },
  { w: "无一不备", p: ["wú", "yī", "bù", "bèi"], e: "指样样齐全。", s: "清·李汝珍《镜花缘》第二十一回真是吃的，喝的，穿的，戴的，无一不精，无一不备。”" },
  { w: "无一不知", p: ["wú", "yī", "bù", "zhī"], e: "没有什么不知道的。形容知识丰富。", s: "《云笈七签》卷四九引《五符经》知一者，无一之不知也。不知一者，无一能知也。一者，至贵无偶之号也。”" },
  { w: "无与为比", p: ["wú", "yǔ", "wéi", "bǐ"], e: "犹无与伦比，无可比拟。", s: "" },
  { w: "无中生有", p: ["wú", "zhōng", "shēng", "yǒu"], e: "道家认为，天下万物生于有，有生于无。把没有的说成有。比喻毫无事实，凭空捏造。", s: "《老子》天下万物生于有，有生于无。”" },
  { w: "无为之治", p: ["wú", "wéi", "zhī", "zhì"], e: "指道家顺应自然，不求有所作为的治理方法。", s: "" },
  { w: "无为而成", p: ["wú", "wéi", "ér", "chéng"], e: "指不倚外力而自然有所成就。", s: "" },
  { w: "无为自化", p: ["wú", "wéi", "zì", "huà"], e: "指无为而治。", s: "语出《老子》我无为而民自化。”" },
  { w: "无为自成", p: ["wú", "wéi", "zì", "chéng"], e: "指不倚外力而自然有所成就。同无为而成”。", s: "" },
  { w: "无乎不可", p: ["wú", "hū", "bù", "kě"], e: "犹无可无不可。指听任。", s: "" },
  { w: "无了无休", p: ["wú", "le", "wú", "xiū"], e: "没完没了，没有终了。", s: "" },
  { w: "无事生事", p: ["wú", "shì", "shēng", "shì"], e: "犹言无事生非。无缘无故找岔子，存心制造麻烦。", s: "" },
  { w: "无事生非", p: ["wú", "shì", "shēng", "fēi"], e: "无缘无故找岔子，存心制造麻烦。", s: "清·李汝珍《镜花缘》第五十八回有不安本分的强盗，有无事生非的强盗。”" },
  { w: "无亲无故", p: ["wú", "qīn", "wú", "gù"], e: "没有亲属和故旧。形容孤单。", s: "" },
  { w: "无人之地", p: ["wú", "rén", "zhī", "dì"], e: "没有人居住的地方。同无人之境”。", s: "" },
  { w: "无人之境", p: ["wú", "rén", "zhī", "jìng"], e: "没有人居住的地方。", s: "宋·杨万里《国势中》不茸一垒，不置一卒，使寇之去来，如入无人之境。”" },
  { w: "无休无了", p: ["wú", "xiū", "wú", "le"], e: "没完没了，没有终了。同无了无休”。", s: "" },
  { w: "无何有乡", p: ["wú", "hé", "yǒu", "xiāng"], e: "无何有之乡。", s: "" },
  { w: "无其伦比", p: ["wú", "qí", "lún", "bǐ"], e: "指事物非常完美，没有能跟它相比的。同无与伦比”。", s: "清·陈田《明诗纪事丁签·边贡》海岳之才，无其伦比。”" },
  { w: "无动为大", p: ["wú", "dòng", "wéi", "dà"], e: "以不变动为至善。无为而治”的一种政治主张。", s: "" },
  { w: "无动于中", p: ["wú", "dòng", "yú", "zhōng"], e: "心里一点儿也没有触动。指对应该关心、注意的事情毫不关心，置之不理。", s: "清·李宝嘉《官场现形记》第三十三回以至顶到如今，偏偏碰着这位制军是不轻容易见客的，他见也好，不见也好，便也漠然无动于中了。”" },
  { w: "无千无万", p: ["wú", "qiān", "wú", "wàn"], e: "指不计其数；极多。", s: "明·施耐庵《水浒传》第十七回杨提辖，且住!你听我说我在东京太师府里做奶公时，门下官军，见了无千无万，都向着我喏喏连声。”" },
  { w: "无可不可", p: ["wú", "kě", "bù", "kě"], e: "①无所不可，都能做到。②犹言不知如何是好。形容情绪激动至极。", s: "" },
  { w: "无可如何", p: ["wú", "kě", "rú", "hé"], e: "没有什么办法。", s: "" },
  { w: "无可比伦", p: ["wú", "kě", "bǐ", "lún"], e: "没有可以相比的。", s: "" },
  { w: "无可比拟", p: ["wú", "kě", "bǐ", "nì"], e: "比拟比较。没有可以相比的。", s: "毛泽东《新民主主义论》这是一个绝大的变化，这是自有世界历史和中国历史以来无可比拟的大变化。”" },
  { w: "无可比象", p: ["wú", "kě", "bǐ", "xiàng"], e: "没有什么可与譬比。", s: "" },
  { w: "无名之师", p: ["wú", "míng", "zhī", "shī"], e: "没有正当理由出征的军队。", s: "" },
  { w: "无名之朴", p: ["wú", "míng", "zhī", "pǔ"], e: "①道家指质朴自然、玄默无为之道”为无名之朴”。②未出名的璞玉。比喻不为人知的才识之士。亦作无名之璞”。", s: "" },
  { w: "无地可容", p: ["wú", "dì", "kě", "róng"], e: "指无处藏身，形容慌乱、羞愧至极，处境窘迫。", s: "清·曹雪芹《红楼梦》第94回李纨正要劝解，丫头来说，太太来了。袭人等此时无地可容，宝玉等赶忙出来迎接。”" },
  { w: "无地自处", p: ["wú", "dì", "zì", "chǔ"], e: "犹无地自容。形容非常羞愧。", s: "" },
  { w: "无地自容", p: ["wú", "dì", "zì", "róng"], e: "没有地方可以让自己容身。形容非常羞愧。", s: "《三国志·魏志·管宁传》夙宵战怖，无地自厝。”" },
  { w: "无声无息", p: ["wú", "shēng", "wú", "xī"], e: "没有声音，没有气味。比喻没有名声，不被人知道。", s: "《诗经·大雅·文王》上天之载，无声无臭。”" },
  { w: "无声无色", p: ["wú", "shēng", "wú", "sè"], e: "没有声音和色彩。形容平淡不动人。", s: "" },
  { w: "无大不大", p: ["wú", "dà", "bù", "dà"], e: "指极大。", s: "" },
  { w: "无大无小", p: ["wú", "dà", "wú", "xiǎo"], e: "①无论大小。指举国上下。②不分年长年幼、辈份大辈份小。", s: "" },
  { w: "无天无日", p: ["wú", "tiān", "wú", "rì"], e: "犹言不见天日。比喻社会黑暗，见不到一点光明。", s: "" },
  { w: "无头无尾", p: ["wú", "tóu", "wú", "wěi"], e: "没有线索；没有来由。", s: "" },
  { w: "无奇不有", p: ["wú", "qí", "bù", "yǒu"], e: "什么奇怪的事物都有。", s: "清·吴趼人《二十年目睹之怪现状》第九回上海地方，无奇不有，倘能在那里多盘桓些日子，新闻还多着呢。”" },
  { w: "无如之何", p: ["wú", "rú", "zhī", "hé"], e: "没有任何办法。", s: "《礼记·大学》小人之使为国家。灾害并至，虽有善者，亦无如之何矣。”" },
  { w: "无如之奈", p: ["wú", "rú", "zhī", "nài"], e: "犹无如之何。没有任何办法。", s: "" },
  { w: "无孔不入", p: ["wú", "kǒng", "bù", "rù"], e: "孔小洞。比喻有空子就钻。", s: "清·李宝嘉《官场现形记》第三十五回况且上海办捐的人，钻头觅缝，无孔不入。”" },
  { w: "无家无室", p: ["wú", "jiā", "wú", "shì"], e: "指孤身一人，无妻小。", s: "" },
  { w: "无尽无休", p: ["wú", "jìn", "wú", "xiū"], e: "没完没了。", s: "曹禺《北京人》第三幕终于沉闷地听着远处的更锣声、风声、树叶声，和偶尔才肯留心到的身旁思懿的无尽无休的言语。”" },
  { w: "无尽无穷", p: ["wú", "jìn", "wú", "qióng"], e: "没有止境，没有限度。同无穷无尽”。", s: "" },
  { w: "无平不颇", p: ["wú", "píng", "bù", "pō"], e: "指凡事没有始终平直而不遇险阻的。", s: "" },
  { w: "无形之罪", p: ["wú", "xíng", "zhī", "zuì"], e: "犹言莫须有之罪。指凭空捏造的罪行。", s: "" },
  { w: "无形无影", p: ["wú", "xíng", "wú", "yǐng"], e: "①不见形迹；完全消失。②形容虚构的事物。", s: "" },
  { w: "无影无形", p: ["wú", "yǐng", "wú", "xíng"], e: "不同形迹；完全消失。也形容虚构的事物。见无形无影”。", s: "" },
  { w: "无往不克", p: ["wú", "wǎng", "bù", "kè"], e: "无论到哪里，没有不胜利的。", s: "" },
  { w: "无往不利", p: ["wú", "wǎng", "bù", "lì"], e: "所到之处，没有不顺利的。指处处行得通，办得好。", s: "清·李汝珍《镜花缘》第九十回贫道今日幸把些尘垢全都拭净，此后是皓月当空，一无渣滓，诸位才女定是无往不利。”" },
  { w: "无往不复", p: ["wú", "wǎng", "bù", "fù"], e: "指未有往而不返的。指事物的运动是循环反复的。同无平不顾”。", s: "《易·泰》无平不陂，无往不复。”孔颖达疏初始往者必将有反复也。”" },
  { w: "无往不胜", p: ["wú", "wǎng", "bù", "shèng"], e: "无论到哪儿没有不胜利的。", s: "京剧《红色娘子军》第二场连长，我们军民一心，就无往不胜！”" },
  { w: "无征不信", p: ["wú", "zhēng", "bù", "xìn"], e: "征证据，验证。没有证据的话或事不可信。", s: "《礼记·中庸》上焉者，虽善无征，无征不信，不信民弗从。”" },
  { w: "无微不至", p: ["wú", "wēi", "bù", "zhì"], e: "微微细；至到。没有一处细微的地方不照顾到。形容关怀、照顾得非常细心周到。", s: "宋·魏了翁《辞免督视军马乞以参赞军事从丞相行奏札》臣窃念主忧臣辱，义不得辞，踨蹐受命，退而差辟官吏、条列事目、调遣将士，凡所以为速发之计者，靡微不周。”" },
  { w: "无德而称", p: ["wú", "dé", "ér", "chēng"], e: "①无何恩德可以称道。②指德高不可言状。", s: "" },
  { w: "无思无虑", p: ["wú", "sī", "wú", "lǜ"], e: "没有什么可放在心上的。形容胸襟开阔，也形容无所用心。", s: "《周易·系辞下》天下何思何虑，天下同归而殊途，一致而百虑。”《庄子·天地》德人者，居无思，行无虑，不藏是非美恶。”" },
  { w: "无怨无德", p: ["wú", "yuàn", "wú", "dé"], e: "既没有怨恨，也没有恩德。指彼此间没有恩怨关系。", s: "《左传·成公三年》无怨无德，不知所报。”" },
  { w: "无恶不为", p: ["wú", "è", "bù", "wéi"], e: "没有哪件坏事不干的。指干尽了坏事。同无恶不作”。", s: "" },
  { w: "无恶不作", p: ["wú", "è", "bù", "zuò"], e: "没有哪件坏事不干的。指干尽了坏事。", s: "清·郑燮《范县署中寄舍弟墨书》五宋自绍兴以来，主和议，增岁币，送尊号，处卑朝，括民膏，戮大将，无恶不作，无陋不为。”" },
  { w: "无恶不造", p: ["wú", "è", "bù", "zào"], e: "没有哪件坏事不干的。指干尽了坏事。同无恶不作”。", s: "" },
  { w: "无情无义", p: ["wú", "qíng", "wú", "yì"], e: "没有一点情义。形容冷酷无情。", s: "清·曹雪芹《红楼梦》第八十二回好！宝玉，我今日才知道你是个无情无义的人了！”" },
  { w: "无情无彩", p: ["wú", "qíng", "wú", "cǎi"], e: "犹无精打彩。形容不高兴，提不起劲儿。", s: "" },
  { w: "无情无绪", p: ["wú", "qíng", "wú", "xù"], e: "没有心思，苦闷无聊。", s: "元·王实甫《西厢记》第二本第一折姐姐往常不曾如此无情无绪。”" },
  { w: "无所不作", p: ["wú", "suǒ", "bù", "zuò"], e: "没有不干的事情。指什么坏事都干。同无所不为”。", s: "" },
  { w: "无所不包", p: ["wú", "suǒ", "bù", "bāo"], e: "没有什么不被包括。形容包含的东西非常多。", s: "清·无名氏《杜诗言志》卷一‘荡胸’句，言其量之无所不包。”" },
  { w: "无所不及", p: ["wú", "suǒ", "bù", "jí"], e: "没有地方不能达到。", s: "" },
  { w: "无所不可", p: ["wú", "suǒ", "bù", "kě"], e: "没有什么不可的。", s: "汉·荀悦《前汉记·武帝纪一》蚡事魏其侯无所不可，而爱数顷田？”" },
  { w: "无所不在", p: ["wú", "suǒ", "bù", "zài"], e: "到处都存在，到处都有。", s: "" },
  { w: "无所不备", p: ["wú", "suǒ", "bù", "bèi"], e: "没有什么不具备的。", s: "" },
  { w: "无所不容", p: ["wú", "suǒ", "bù", "róng"], e: "没有什么不能容纳。极言其宽广。", s: "" },
  { w: "无所不晓", p: ["wú", "suǒ", "bù", "xiǎo"], e: "什么事情都知道，没有不懂得的。", s: "元·吴昌龄《东坡梦》第一折此女甚是聪慧……便是三教九流的说话，无所不通，无所不晓。”" },
  { w: "无所不有", p: ["wú", "suǒ", "bù", "yǒu"], e: "什么都有（多指不好的事物）。", s: "唐·李朝威《柳毅传》始见台阁相向，门户千万，奇草珍木，无所不有。”" },
  { w: "无所不知", p: ["wú", "suǒ", "bù", "zhī"], e: "什么事情都知道，没有不懂得的。", s: "《列子·黄帝》圣人无所不知，无所不通，故得引而使之焉。”" },
  { w: "无所不能", p: ["wú", "suǒ", "bù", "néng"], e: "没有什么不能做的。指样样能做。", s: "宋·沈括《梦溪笔谈》卷二十一近岁迎紫姑者极多，大率多能文章歌诗，有极工者，予屡见之，多自称蓬莱谪仙，医卜无所不能，棋与国手为敌。”" },
  { w: "无所不至", p: ["wú", "suǒ", "bù", "zhì"], e: "至到。指没有不到的地方。也指什么坏事都做绝了。", s: "《论语·阳货》既得之，患失之，苟患失之，无所不至矣。”" },
  { w: "无所不通", p: ["wú", "suǒ", "bù", "tōng"], e: "通通晓。没有什么不通晓。形容知道的东西很多。", s: "《孝经·感应》孝悌之至，通于神明，光于四海，无所不通。”" },
  { w: "无所事事", p: ["wú", "suǒ", "shì", "shì"], e: "事事前一事”为动词，做；后一事”为名词，事情。闲着什么事都不干。", s: "" },
  { w: "无所容心", p: ["wú", "suǒ", "róng", "xīn"], e: "不在意，不留意。", s: "" },
  { w: "无所用之", p: ["wú", "suǒ", "yòng", "zhī"], e: "没有地方可以用上它。", s: "" },
  { w: "无所用心", p: ["wú", "suǒ", "yòng", "xīn"], e: "没有地方用他的心。指不动脑筋，什么事情都不关心。", s: "《论语·阳货》饱食终日，无所用心，难矣哉。”" },
  { w: "无敌天下", p: ["wú", "dí", "tiān", "xià"], e: "天下都没有对手。", s: "先秦·孟轲《孟子·公孙丑上》则无敌于天下。”" },
  { w: "无方之民", p: ["wú", "fāng", "zhī", "mín"], e: "古指不知礼法的人。", s: "" },
  { w: "无施不可", p: ["wú", "shī", "bù", "kě"], e: "用在任何地方均甚得当。", s: "" },
  { w: "无施不效", p: ["wú", "shī", "bù", "xiào"], e: "指施行的每项策略都收效。", s: "" },
  { w: "无旧无新", p: ["wú", "jiù", "wú", "xīn"], e: "不分是旧交还是新交。", s: "《尚书大传》卷二上各安其宅，各田其田，毋故毋新。”" },
  { w: "无时无刻", p: ["wú", "shí", "wú", "kè"], e: "时时刻刻。表示毫不间断。", s: "明·凌濛初《初刻拍案惊奇》卷六自是行忘止，食忘餐，却象掉下了一件什么东西的，无时无刻不在心上。”" },
  { w: "无明无夜", p: ["wú", "míng", "wú", "yè"], e: "犹言不分昼夜。", s: "《二刻拍案惊奇》卷八所以一耽了这件的滋味，定是无明无夜，抛家失业，失魂落魄，忘飧废寝的。”" },
  { w: "无有伦比", p: ["wú", "yǒu", "lún", "bǐ"], e: "没有比得上。", s: "" },
  { w: "无法无天", p: ["wú", "fǎ", "wú", "tiān"], e: "旧指不顾国法和天理，任意干坏事。现多形容违法乱纪，不受管束。", s: "清·曹雪芹《红楼梦》第三十三回你在家不读书也罢了，怎么又做出这无法无天的事来。”" },
  { w: "无济于事", p: ["wú", "jì", "yú", "shì"], e: "济补益，帮助。对事情没有什么帮助或益处。比喻不解决问题。", s: "清·李宝嘉《官场现形记》第五十二回如今远水救不得近火，就是我们再帮点忙，至多再凑了几百银子，也无济于事。”" },
  { w: "无父无君", p: ["wú", "fù", "wú", "jūn"], e: "孟轲斥责墨翟、杨朱之语◇以讥刺无伦常者。", s: "" },
  { w: "无相无作", p: ["wú", "xiāng", "wú", "zuò"], e: "①佛教语。指弃绝众相，不事造作。②泛指不务空言。", s: "" },
  { w: "无私之光", p: ["wú", "sī", "zhī", "guāng"], e: "比喻帝王的德泽。", s: "语本《礼记·孔子闲居》天无私覆，地无私载，日月无私照。”" },
  { w: "无私有意", p: ["wú", "sī", "yǒu", "yì"], e: "自己虽无私心，别人则将认为有意。意为要避嫌疑。", s: "" },
  { w: "无稽之言", p: ["wú", "jī", "zhī", "yán"], e: "没有根据、无从查证的话。", s: "" },
  { w: "无穷无尽", p: ["wú", "qióng", "wú", "jìn"], e: "穷完。没有止境，没有限度。", s: "宋·晏殊《踏莎行》无穷无尽是离愁，天涯地角寻思遍。”" },
  { w: "无空不入", p: ["wú", "kōng", "bù", "rù"], e: "比喻有空子就钻。同无孔不入”。", s: "" },
  { w: "无端生事", p: ["wú", "duān", "shēng", "shì"], e: "无端没有理由。无缘无故地捣乱闹事。", s: "" },
  { w: "无缘无故", p: ["wú", "yuán", "wú", "gù"], e: "没有一点原因。", s: "清·曹雪芹《红楼梦》第四十四回好好儿的，从那里说起！无缘无故白受了一场气！”" },
  { w: "无肠公子", p: ["wú", "cháng", "gōng", "zǐ"], e: "指螃蟹。", s: "晋·葛洪《抱朴子·登涉》称无肠公子者，蟹也。”" },
  { w: "无般不识", p: ["wú", "bān", "bù", "shí"], e: "犹百般，用尽方法。", s: "" },
  { w: "无虑无思", p: ["wú", "lǜ", "wú", "sī"], e: "犹言无忧无虑。没有一点忧愁和顾虑。", s: "" },
  { w: "无衣之赋", p: ["wú", "yī", "zhī", "fù"], e: "以之为出师相援、同仇敌忾之典。", s: "春秋末，吴破楚，楚大夫申包胥乞师秦廷，倚庭墙而哭，七日勺饮不入。秦哀公乃赋《无衣》诗，并出兵救楚。事见《左传·定公四年》。" },
  { w: "无补于事", p: ["wú", "bǔ", "yú", "shì"], e: "补益处，裨益，对事情没有什么益处。", s: "" },
  { w: "无言可对", p: ["wú", "yán", "kě", "duì"], e: "对对答，回答。没有话来回答。", s: "宋·释普济《五灯会元》卷四师曰‘这老和尚被我一问直得无言可对。’”" },
  { w: "无论如何", p: ["wú", "lùn", "rú", "hé"], e: "不管怎样。表示不管条件怎样变化，其结果始终不变。", s: "" },
  { w: "日不我与", p: ["rì", "bù", "wǒ", "yǔ"], e: "时日不等待我。极言应抓紧时间。", s: "三国·魏·曹植《与吴季重书》然日不我与，曜灵急节，面有过景之速，别有参商之阔。”" },
  { w: "日以为常", p: ["rì", "yǐ", "wéi", "cháng"], e: "经常做某件事，成了惯例常规。", s: "" },
  { w: "日出不穷", p: ["rì", "chū", "bù", "qióng"], e: "形容接连不断地出现。", s: "清·裘廷梁《论白话为维新之本》而新书新报日出不穷者，无愚智皆读之。”" },
  { w: "时不再来", p: ["shí", "bù", "zài", "lái"], e: "时时机。时机错过就不会再来了。指行事不要放过时机。", s: "《国语·越语下》得时无怠，时不再来，天予不取，反为之灾。”" },
  { w: "时不可失", p: ["shí", "bù", "kě", "shī"], e: "时时机，机会；失错过。抓住时机，不可错过。", s: "《战国策·秦策四》臣闻敌不可易，时不可失。”" },
  { w: "时不我与", p: ["shí", "bù", "wǒ", "yǔ"], e: "我与与我”的倒装；与等待。时间不会等待我们的。嗟叹时机错过，追悔不及。", s: "《论语·阳货》日月逝矣，岁不我与。”" },
  { w: "时不我待", p: ["shí", "bù", "wǒ", "dài"], e: "我待待我”的倒装，等待我。时间不会等待我们。指要抓紧时间。", s: "《论语·阳货》日月逝矣，岁不我与。”" },
  { w: "时无再来", p: ["shí", "wú", "zài", "lái"], e: "时机错过，不会再来。激励人要抓紧时机。", s: "宋·邵雍《不再吟》春无再至，花无再开；人无再少，时无再来。”" },
  { w: "旷古一人", p: ["kuàng", "gǔ", "yī", "rén"], e: "旷古空前；从古到今。自古以来只此一人。形容绝无仅有。", s: "五代·王定保《唐摭言·以其人不称才试而后惊》北面而师之者，可谓旷古一人而已！”" },
  { w: "明教不变", p: ["míng", "jiào", "bù", "biàn"], e: "教令明确，让老百姓有所适从，便不会发生变乱。", s: "《商君书·赏刑》夫明赏不费，明刑不戮，明教不变，而民知于民务，国无异俗。”" },
  { w: "是非之心", p: ["shì", "fēi", "zhī", "xīn"], e: "分辨是非得失的能力。", s: "" },
  { w: "月下老人", p: ["yuè", "xià", "lǎo", "rén"], e: "原指主管婚姻的神仙◇泛指媒人。简称月老”。", s: "唐·李复言《续幽怪录》记载传说故事唐朝的韦固路过宋城，遇一老人在月光下翻检一本书。询问后，知道老人是专管人间婚姻的神，翻检的书是婚姻簿子。" },
  { w: "有一得一", p: ["yǒu", "yī", "dé", "yī"], e: "不加也不减，有多少是多少。", s: "" },
  { w: "有一无二", p: ["yǒu", "yī", "wú", "èr"], e: "只有一个，不会有第二个。指事物独特，极难得。", s: "明·姚子翼《遍地锦传奇·劝主》似这等才调也算得有一无二的了。”" },
  { w: "有事之秋", p: ["yǒu", "shì", "zhī", "qiū"], e: "指战争或多事故的年头。", s: "" },
  { w: "有口无心", p: ["yǒu", "kǒu", "wú", "xīn"], e: "嘴上说了，心里可没那样想。指不是有心说的。", s: "清·张南庄《何典·序》总属有口无心，安用设身处地。”" },
  { w: "有名无实", p: ["yǒu", "míng", "wú", "shí"], e: "光有空名，实际上并不是那样。", s: "《庄子·则阳》有名有实，是物之居；无名无实，在物之虚。”《国语·晋语八》吾有卿之名而无其实。无以从二三子，吾是以忧，子贺我何故？”" },
  { w: "有嘴无心", p: ["yǒu", "zuǐ", "wú", "xīn"], e: "犹言有口无心。指不是有心说的。", s: "" },
  { w: "有声无实", p: ["yǒu", "shēng", "wú", "shí"], e: "犹言有名无实。光有空名，实际上并不是那样。", s: "《魏书·李崇传》今若基宇不修，仍同丘畎，即使高皇神享，阙于国阳，宗事之典，有声无实，此臣子所以匪宁，亿兆所以失望也。”" },
  { w: "有声无气", p: ["yǒu", "shēng", "wú", "qì"], e: "①形容人气息奄奄。②形容说话无精打采。", s: "明·凌濛初《二刻拍案惊奇》卷二十一王禄多说了几句话，渐渐有声无气，挨到黄昏，只有出的气，没有入的气，呜呼哀哉，伏维尚飨。”" },
  { w: "有声有色", p: ["yǒu", "shēng", "yǒu", "sè"], e: "形容说话或表演精彩生动。", s: "清·洪亮吉《北江诗话》卷一写月有声有色如此，后人复何着笔耶？”" },
  { w: "有天无日", p: ["yǒu", "tiān", "wú", "rì"], e: "比喻社会非弛暗，没有公道。", s: "元·康进之《李逵负荆》第二折元来个梁山泊有天无日。”" },
  { w: "有天没日", p: ["yǒu", "tiān", "méi", "rì"], e: "比喻说话毫无畏惧和顾忌。", s: "清·曹雪芹《红楼梦》第七回众小厮见说出来的话有天没日的，吓得魂飞魄丧，把他捆起来。”" },
  { w: "有头无尾", p: ["yǒu", "tóu", "wú", "wěi"], e: "有开头没有收尾。指没有把事情做完。", s: "宋·释普济《五灯会元》卷五曰‘有头无尾时如何？’师曰‘吐得黄金堪作什么？’”《朱子语类》若是有头无尾底人，便是忠也不久。”" },
  { w: "有害无利", p: ["yǒu", "hài", "wú", "lì"], e: "只有坏处没有好处。", s: "" },
  { w: "有己无人", p: ["yǒu", "jǐ", "wú", "rén"], e: "自私自利，只顾自己，不顾别人。", s: "" },
  { w: "有年无月", p: ["yǒu", "nián", "wú", "yuè"], e: "指日子拖得长久，没有确定的期限。", s: "蔡东藩《后汉演义》第二回百姓又怕当兵，最怕输粮……舟子车夫，又没有多少工资，统皆畏缩不前，眼见得有年无月，不能成事。”" },
  { w: "有心无力", p: ["yǒu", "xīn", "wú", "lì"], e: "有愿望和打算，但没有力量付诸实现。", s: "南朝·梁·惠皎《高僧传·义解·竺法旷》贫道必当尽诚上答，正恐有心无力耳。”" },
  { w: "有心有意", p: ["yǒu", "xīn", "yǒu", "yì"], e: "犹言诚心诚意。形容十分真挚诚恳。", s: "" },
  { w: "有志之士", p: ["yǒu", "zhì", "zhī", "shì"], e: "士对人的尊称。指有理想有抱负的人。", s: "宋·陆九渊《与曾宅之书》惟其生于后世，学绝道丧，异端邪说充塞弥满，遂使有志之士罹此患害，乃与世间凡庸恣情纵欲之人均其陷溺，此岂非以学术杀天下哉。”" },
  { w: "有志无时", p: ["yǒu", "zhì", "wú", "shí"], e: "有抱负而时运不济。", s: "《后汉书·赵歧传》汉有逸人，姓赵名嘉。有志无时，命也奈何！”" },
  { w: "有意无意", p: ["yǒu", "yì", "wú", "yì"], e: "又像是有意的，又像是无意的。存心与不经意。", s: "南朝·宋·刘义庆《世说新语·文学》庾子嵩作意赋成，从子文康见，问曰若有意邪？非赋之所尽，若无意邪？复何所赋？答曰正在有意无意之间。”" },
  { w: "有我无人", p: ["yǒu", "wǒ", "wú", "rén"], e: "极言其自傲而轻视他人。", s: "蔡东藩《五代史演义》第二回[朱温]到了难星已过，依然趾高气扬，有我无人。”" },
  { w: "有所作为", p: ["yǒu", "suǒ", "zuò", "wéi"], e: "可以做事情，并能取得较大的成绩。", s: "先秦·孟轲《孟子·离娄下》人有不为也，而后可以有为。”" },
  { w: "有才无命", p: ["yǒu", "cái", "wú", "mìng"], e: "有才能但遭遇不好。指不得志。", s: "唐·杜甫《寄狄明府博济》诗比看书父四十人，有才无命百寮底。”" },
  { w: "有无相通", p: ["yǒu", "wú", "xiāng", "tōng"], e: "互通有无，互相接济。", s: "宋·文天祥《刘定伯墓志铭》朋友有无相通，急难于我乎赴。”" },
  { w: "有朝一日", p: ["yǒu", "zhāo", "yī", "rì"], e: "将来有那么一天。", s: "元·无名氏《博望烧屯》第一折有朝一日，我出矛庐指点世人迷，凭着我剑挥星斗，我志逐风雷。”" },
  { w: "有本有原", p: ["yǒu", "běn", "yǒu", "yuán"], e: "指有根源；源源本本。亦作有本有源”。", s: "唐·韩愈《原毁》虽然，为是者有本有原，怠与忌之谓也。”" },
  { w: "有来无回", p: ["yǒu", "lái", "wú", "huí"], e: "只要来了，就回不去。指彻底被消灭。", s: "周立波《暴风骤雨》第一部十三有这玩艺儿，慢说他‘种殃军’，他洋爸爸鬼子来，也给他有来无回。”" },
  { w: "有来有往", p: ["yǒu", "lái", "yǒu", "wǎng"], e: "指对等行动。所指因文而异。", s: "陶行知《怎样做小先生》十一你既虚心的请教他，他也会虚心的请教你。最好的教育是有来有往。”" },
  { w: "有死无二", p: ["yǒu", "sǐ", "wú", "èr"], e: "表示意志坚定，虽死不变。", s: "《左传·僖公十五年》必报德，有死无二。”" },
  { w: "有气无力", p: ["yǒu", "qì", "wú", "lì"], e: "形容说话声音微弱，作事精神不振。也形容体弱无力。", s: "明·冯梦龙《醒世恒言·吴衙内邻舟赴约》正不知舱中另有个替吃饭的，还饿得有气无力哩。”" },
  { w: "有物有则", p: ["yǒu", "wù", "yǒu", "zé"], e: "指天地间凡事物皆有其法则、规律。", s: "《诗·大雅·焌民》天生焌民，有物有则。”" },
  { w: "有生之年", p: ["yǒu", "shēng", "zhī", "nián"], e: "一生之中最后的年月，即余年。", s: "清·李汝珍《镜花缘》第68回俾臣得保蚁命，此后有生之年，莫非主上所赐，惟求格外垂怜。”" },
  { w: "有生以来", p: ["yǒu", "shēng", "yǐ", "lái"], e: "从出生到现在。", s: "清·曹雪芹《红楼梦》第一百十八回况你自有生以来，自去世的老太太，以至老爷、太太，视如珍宝。”" },
  { w: "有言在先", p: ["yǒu", "yán", "zài", "xiān"], e: "有话说在头里。指事先打了招呼。", s: "明·冯梦龙《醒世恒言》卷二十二他有言在先，你今日不须惊怕。”" },
  { w: "有识之士", p: ["yǒu", "shí", "zhī", "shì"], e: "具有才能和远见卓识的人。", s: "汉·刘向《说苑·善说》天下有识之士，无不为足下寒心酸鼻者，千秋万岁之后，庙堂必不血食矣。”" },
  { w: "有说有笑", p: ["yǒu", "shuō", "yǒu", "xiào"], e: "连说带笑。形容十分欢快。", s: "清·吴趼人《情变》第五回想起昨天晚上，还是有说有笑，相亲相爱的何等有趣，今天晚上变了这个情形。”" },
  { w: "有风有化", p: ["yǒu", "fēng", "yǒu", "huà"], e: "指有教育意义。", s: "明·汤显祖《牡丹亭·闺塾》论《六经》，《诗经》最葩，闺门内许多风雅……有风有化，宜室宜家。”" },
  { w: "望梅止渴", p: ["wàng", "méi", "zhǐ", "kě"], e: "原意是梅子酸，人想吃梅子就会流涎，因而止渴◇比喻愿望无法实现，用空想安慰自己。", s: "南朝宋·刘义庆《世说新语·假谲》魏武行役失汲道，军皆渴，乃令曰‘前有大梅林，饶子，甘酸可以解渴。’士卒闻之，口皆出水，乘此得及前源。”" },
  { w: "未为不可", p: ["wèi", "wéi", "bù", "kě"], e: "不是不可以。委婉地肯定。", s: "" },
  { w: "机不容发", p: ["jī", "bù", "róng", "fā"], e: "比喻时机紧迫。", s: "" },
  { w: "来之不易", p: ["lái", "zhī", "bù", "yì"], e: "来之使之来。得到它不容易。表示财物的取得或事物的成功是不容易的。", s: "明·朱柏庐《治家格言》一粥一饭，当思来处不易；半丝半缕，恒念物力维艰。”" },
  { w: "来历不明", p: ["lái", "lì", "bù", "míng"], e: "来历由来。人或事物的来历与经过不清楚。", s: "宋·周密《癸辛杂识·前集·郑仙姑》适新建县有阙氏者，雇一婢，来历不明。”" },
  { w: "来处不易", p: ["lái", "chù", "bù", "yì"], e: "表示事情的成功或财物的取得，经过了艰苦努力。", s: "明·朱柏庐《治家格言》一粥一饭，当思来处不易；半丝半缕，恒念物力维艰。”" },
  { w: "来者不善", p: ["lái", "zhě", "bù", "shàn"], e: "善亲善，友好。强调来人不怀好意，要警惕防范。", s: "《老子》善者不辩，辩者不善。”" },
  { w: "杯弓蛇影", p: ["bēi", "gōng", "shé", "yǐng"], e: "将映在酒杯里的弓影误认为蛇。比喻因疑神疑鬼而引起恐惧。", s: "汉·应劭《风俗通义·世间多有见怪》时北壁上有悬赤弩照于杯，形如蛇。宣畏恶之，然不敢不饮。”" },
  { w: "极而言之", p: ["jí", "ér", "yán", "zhī"], e: "从最极端的情况来说。指把话说到头。", s: "" },
  { w: "果不其然", p: ["guǒ", "bù", "qí", "rán"], e: "果然如此。指事物的发展变化跟预料的一样。", s: "清·吴敬梓《儒林外史》第三回我说姑老爷今非昔比，少不得有人把银子送上门去给他用，只怕姑老爷还不稀罕哩，今日果不其然。”" },
  { w: "栩栩如生", p: ["xǔ", "xǔ", "rú", "shēng"], e: "栩栩活泼生动的样子。指艺术形象非常逼真，如同活的一样。", s: "《庄子·齐物论》昔者庄周梦为胡蝶，栩栩然胡蝶也，自喻适志与！不知周也。俄然觉，则茫茫然周也。”" },
  { w: "正人君子", p: ["zhèng", "rén", "jūn", "zǐ"], e: "旧时指品行端正的人。现多作讽刺的用法，指假装正经的人。", s: "《旧唐书·崔胤传》胤所悦者阘茸下辈，所恶者正人君子。人人悚惧，朝不保夕。”" },
  { w: "比众不同", p: ["bǐ", "zhòng", "bù", "tóng"], e: "与大家相比，大不一样。", s: "明·吴承恩《西游记》第四回原来悟空筋斗云比众不同，十分快疾，把个金星撇在脑后，先至南天门外。”" },
  { w: "比年不登", p: ["bǐ", "nián", "bù", "dēng"], e: "比屡屡；频频。农业连年歉收。亦作比岁不登”。", s: "《晋书·傅玄传》时比年不登，羌胡扰边，诏公卿会议，玄应对所问，陈事切直。”" },
  { w: "比比皆是", p: ["bǐ", "bǐ", "jiē", "shì"], e: "比比一个挨一个。到处都是，形容极其常见。", s: "《战国策·秦策一》犯白刃，蹈煨炭，断死于前者，比是也。”宋·包拯《请救济江淮饥民疏》年亢旱，民食艰阻，流亡者比比皆是。”" },
  { w: "比比皆然", p: ["bǐ", "bǐ", "jiē", "rán"], e: "比比处处。到处都是。形容多。同比比皆是”。", s: "清·褚人获《隋唐演义》第五十三回将无固守之志，兵无敢死之心，人情趋利，比比皆然。”" },
  { w: "水滴石穿", p: ["shuǐ", "dī", "shí", "chuān"], e: "水不停地滴，石头也能被滴穿。比喻只要有恒心，不断努力，事情就一定能成功。", s: "《汉书·枚乘传》泰山之靋穿石，单极之绠断干。水非石之钻，索非木之锯，渐靡使之然也。”" },
  { w: "求之不得", p: ["qiú", "zhī", "bù", "dé"], e: "想找都找不到。原指急切企求，但不能得到◇多形容迫切希望得到。", s: "《诗·周南·关雎》求之不得，寤寐思服。”" },
  { w: "没而不朽", p: ["méi", "ér", "bù", "xiǔ"], e: "没同殁”，死。指人的身体虽死，但其精神、业绩、文章永存人间。", s: "" },
  { w: "泛泛之人", p: ["fàn", "fàn", "zhī", "rén"], e: "泛泛平常，一般。一般的人。指不是什么有所作为有才干的人物。", s: "姚雪垠《李自成》第二卷第四十一章［李信］他明白在杞县境内停留着耽误时间对他十分不利，也相信李闯王大概不是泛泛之人，但是他更明白，去投闯王，这是他兄弟和红娘子的一生大事，不能不特别慎重。”" },
  { w: "津津有味", p: ["jīn", "jīn", "yǒu", "wèi"], e: "津津兴趣浓厚的样子。指吃得很有味道或谈得很有兴趣。", s: "汉·王褒《洞箫赋》哀悁悁之可怀兮，良醰醰而有味。”" },
  { w: "浮而不实", p: ["fú", "ér", "bù", "shí"], e: "形容知识浅薄，基础不扎实；形容作风浮泛，不深入不踏实。", s: "" },
  { w: "深得人心", p: ["shēn", "dé", "rén", "xīn"], e: "得到广大人民的热烈拥护。", s: "" },
  { w: "清静无为", p: ["qīng", "jìng", "wú", "wéi"], e: "道家语。春秋时期道家的一种哲学思想和治术。指一切听其自然，人力不必强为。", s: "唐·贾至《虙子贱碑颂》鸣琴汤汤，虙子之堂，清静无为，邑人以康。”" },
  { w: "渔人之利", p: ["yú", "rén", "zhī", "lì"], e: "渔人比喻第三者。比喻双方争执不下，两败俱伤，让第三者占了便宜。", s: "《战国策·燕策二》记载蚌张开壳晒太阳，鹬去啄它，嘴被蚌壳夹住，两方面都不相让。渔翁来了，把两个都捉住了。" },
  { w: "满不在意", p: ["mǎn", "bù", "zài", "yì"], e: "全然不放在心上，不当一回事。", s: "巴金《复仇集·不幸的人》这是一只破旧的提琴，他拿着弓满不在意地拉着。”" },
  { w: "爱人以德", p: ["ài", "rén", "yǐ", "dé"], e: "爱人爱护别人；德德行。按照道德标准去爱护人。泛指对人不偏私偏爱，不姑息迁就。", s: "《礼记·檀弓上》君子之爱人也以德，细人之爱人也以姑息。”" },
  { w: "物是人非", p: ["wù", "shì", "rén", "fēi"], e: "东西还是原来的东西，可是人已不是原来的人了。多用于表达事过境迁。因而怀念故人。", s: "宋·李清照《武陵春》词物是人非事事休，欲语泪先流。”" },
  { w: "独一无二", p: ["dú", "yī", "wú", "èr"], e: "没有相同的或没有可以相比的。", s: "宋·延寿辑《宗镜录》卷三十一独一无二，即真解脱。”" },
  { w: "独得之见", p: ["dú", "dé", "zhī", "jiàn"], e: "与众不同的创造性的见解。", s: "明·归有光《送王子敬之任建宁序》近世一二君子，乃起而争自为说，创为独得之见。”" },
  { w: "王公大人", p: ["wáng", "gōng", "dà", "rén"], e: "国君重臣◇泛指高官贵人。", s: "" },
  { w: "理所不容", p: ["lǐ", "suǒ", "bù", "róng"], e: "道理所不能允许。", s: "" },
  { w: "生不逢时", p: ["shēng", "bù", "féng", "shí"], e: "生下来没有遇到好时候。旧时指命运不好。", s: "《诗·大雅·桑柔》 我生不辰，逢天僤怒。”" },
  { w: "生不遇时", p: ["shēng", "bù", "yù", "shí"], e: "生下来没有遇到好时候。旧时指命运不好。", s: "《诗经·大雅·桑柔》 我生不辰，逢天僤怒。”汉·袁康《越绝书·越绝德序外传记》吾先得荣后僯者，非智衰也；先遇明后遭险，君之易移也已矣，生不遇时，复何言哉。”" },
  { w: "生生不已", p: ["shēng", "shēng", "bù", "yǐ"], e: "生生中国哲学术语，指变化和新生事物的发生；不已没有终止。形容一切生物新陈代谢，永无停止。", s: "《周易·系辞上》生生之谓易。”宋·周敦颐《太极图说》二气交感，化生万物，万物生生而变化无穷焉。”" },
  { w: "生生不息", p: ["shēng", "shēng", "bù", "xī"], e: "生生中国哲学术语，指变化和新生事物的发生；不已没有终止。不断地生长、繁殖。", s: "《周易·系辞上》生生之谓易。”宋·周敦颐《太极图说》二气交感，化生万物，万物生生而变化无穷焉。”" },
  { w: "生而知之", p: ["shēng", "ér", "zhī", "zhī"], e: "生下来就懂得知识和道理。这是唯心主义者的观点。", s: "《论语·述而》子曰‘我非生而知之者，好古敏以求之者也。’”" },
  { w: "用一当十", p: ["yòng", "yī", "dāng", "shí"], e: "比喻以寡敌众。", s: "宋·陈善《扪虱新活·张巡杀爱妾刘昌斩孤甥》君以孤城，用一当十，何以能守？”" },
  { w: "用之不竭", p: ["yòng", "zhī", "bù", "jié"], e: "竭尽。无限取用而不会使用完。", s: "宋·苏轼《前赤壁赋》唯江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭。”" },
  { w: "用武之地", p: ["yòng", "wǔ", "zhī", "dì"], e: "形容地形险要，利于作战的地方。比喻可以施展自己才能的地方或机会。", s: "《晋书·姚襄载记》洛阳虽小，山河四塞，亦是用武之地。”" },
  { w: "用非其人", p: ["yòng", "fēi", "qí", "rén"], e: "任用了不适当的人才。指用人不当。", s: "" },
  { w: "画一之法", p: ["huà", "yī", "zhī", "fǎ"], e: "指全体遵行、无一例外的法令政策。", s: "《后汉书·王充王符等传论》太叔致猛政之褒，国子流遗爱之娣，宣孟改冬日之和，平阳循画一之法。”" },
  { w: "画蛇添足", p: ["huà", "shé", "tiān", "zú"], e: "画蛇时给蛇添上脚。比喻做了多余的事，非但无益，反而不合适。也比喻虚构事实，无中生有。", s: "《战国策·齐策二》蛇固无足，子安能为之足？” 明·施耐庵《水浒全传》第一百十回将军功绩已成，威声大震，可以止矣。今若前进，倘不如意，正如‘画蛇添足’也。”。" },
  { w: "画龙点睛", p: ["huà", "lóng", "diǎn", "jīng"], e: "原形容梁代画家张僧繇作画的神妙◇多比喻写文章或讲话时，在关键处用几句话点明实质，使内容生动有力。", s: "唐·张彦远《历代名画记·张僧繇》金陵安乐寺四白龙不点眼睛，每云‘点睛即飞去。’人以为妄诞，固请点之。须臾，雷电破壁，两龙乘云腾去上天，二龙未点眼者见在。”" },
  { w: "百不一存", p: ["bǎi", "bù", "yī", "cún"], e: "一百个里面没有留下一个。表示丧失殆尽。", s: "北周·宇文逌《〈庾信集〉序》昔在阳都，有集十四卷，值太清罹乱，百不一存。”《南史·蔡廓传附蔡兴宗》时士庶危惧，衣冠咸欲远徙，后皆流离外难，百不一存。”" },
  { w: "百不一遇", p: ["bǎi", "bù", "yī", "yù"], e: "一百次中遇不到一次。形容极其难得。", s: "汉·荀悦《汉纪·哀帝纪下》言立策成，终无咎悔，若此之事，百不一遇，其知之所见，万不及一也。”" },
  { w: "百不失一", p: ["bǎi", "bù", "shī", "yī"], e: "一百次中无一次失误。表示射箭或打枪命中率高，或做事有充分把握。", s: "汉·王充《论衡·须颂》从门应庭，听堂室之言，什而失九，如升堂窥室，百不失一。”" },
  { w: "百不当一", p: ["bǎi", "bù", "dāng", "yī"], e: "当抵挡。一百个抵挡不住一个。", s: "汉·荀悦《汉纪·文帝纪下》平易相远，山谷幽涧，仰高临下，此弓弩之地也，短兵百不当一。”" },
  { w: "百不获一", p: ["bǎi", "bù", "huò", "yī"], e: "一百个里面也得不到一个。形容人或物的难得或所得极少。", s: "清·李绿园《歧路灯》第一百五回人品自会端正，文移自会清顺，晓畅，然着实是百不获一的。”" },
  { w: "百世一人", p: ["bǎi", "shì", "yī", "rén"], e: "指极难得的人才。", s: "宋·苏轼《祭司马君实文》百世一人，千载一时，惟时与人，鲜偶常奇。”" },
  { w: "百事无成", p: ["bǎi", "shì", "wú", "chéng"], e: "犹言一事无成。什么事情都没成功。", s: "唐·刘禹锡《陪崔大尚书及诸阁老宴杏园》诗更将何面上春台，百事无成老又催。”" },
  { w: "百发百中", p: ["bǎi", "fā", "bǎi", "zhòng"], e: "形容射箭或打枪准确，每次都命中目标。也比喻做事有充分把握。", s: "《战国策·西周策》楚有养由基者，善射，去柳叶百步而射之，百发百中。”" },
  { w: "百年之后", p: ["bǎi", "nián", "zhī", "hòu"], e: "死的讳称。", s: "《曹操集·卷二·军谯令》为存者立庙，使视其先人。魂而有灵，吾百年之后何恨哉！”元·武汉臣《老生儿》第三折俺女儿百年之后，可往俺刘家坟里埋也，去他张家坟里埋？”" },
  { w: "百年之好", p: ["bǎi", "nián", "zhī", "hǎo"], e: "永久的好合。指男女结为夫妇。", s: "宋·罗烨《醉翁谈录·张氏夜奔吕星哥》今宁随君远奔，以结百年之好。”明·凌濛初《初刻拍案惊奇》卷三十二我方壮年，未曾娶妻。倘蒙不弃，当与子缔百年之好。”" },
  { w: "百折不回", p: ["bǎi", "zhé", "bù", "huí"], e: "折挫折。比喻意志坚强，无论受到多少次挫折，毫不动摇退缩。", s: "汉·蔡邕《太尉乔玄碑》其性庄，疾华尚朴，有百折不挠，临大节而不可夺之风。”" },
  { w: "百无一失", p: ["bǎi", "wú", "yī", "shī"], e: "形容有充分把握，绝对不会出差错。", s: "汉·王充《论衡·须颂》从门应庭，听堂室之言，什而失九，如升堂窥室，百不失一。”" },
  { w: "百无一成", p: ["bǎi", "wú", "yī", "chéng"], e: "百一切。形容一切的努力和作为没有一样成功，即毫无成就。", s: "清·曾国藩《圣哲画象记》志学不早……驽缓多病，百无一成。”" },
  { w: "百无一是", p: ["bǎi", "wú", "yī", "shì"], e: "干一百件事，也没有做对一件。形容全都做错了，一无是处。", s: "宋·袁采《袁氏世范》至于百无一是，且朝夕以此相临，极为难处。”" },
  { w: "百无一用", p: ["bǎi", "wú", "yī", "yòng"], e: "百样之中无一有用的。形容毫无用处。", s: "清·黄景仁《杂感》十有九人堪白眼，百无一用是书生。”" },
  { w: "百无一能", p: ["bǎi", "wú", "yī", "néng"], e: "能能力，胜任。什么都不会做。", s: "明·施耐庵《水浒全传》第三十二回宋江道‘我自百无一能，虽有忠心，不能得进步。’”" },
  { w: "百无所成", p: ["bǎi", "wú", "suǒ", "chéng"], e: "犹言一事无成。", s: "明·王守仁《教条示龙场诸生》今学者旷废隳惰，玩岁愒时而百无所成，皆由于志之未立耳。”" },
  { w: "百无是处", p: ["bǎi", "wú", "shì", "chù"], e: "犹言一无是处。形容全都是错的，没有一点对的地方。", s: "宋·辛弃疾《浣溪沙·漫兴作》词一似旧时春意思，百无是处老形骸，也曾头上带花来。”" },
  { w: "目不知书", p: ["mù", "bù", "zhī", "shū"], e: "指读书很少或没读过书；不甚识字或不识字。同目不识书”。", s: "" },
  { w: "目不识书", p: ["mù", "bù", "shí", "shū"], e: "指读书很少或没读过书；不甚识字或不识字。", s: "" },
  { w: "目中无人", p: ["mù", "zhōng", "wú", "rén"], e: "眼里没有别人。形容骄傲自大，看不起人。", s: "明·冯梦龙《东周列国志》第九十六回赵奢子赵括，自少喜谈兵法，家传《六韬》、《三略》之书，一览而尽；尝与父奢论兵，指天画地，目中无人，虽奢亦不能难也。”" },
  { w: "目瞪口呆", p: ["mù", "dèng", "kǒu", "dāi"], e: "形容因吃惊或害怕而发愣的样子。", s: "元·无名氏《赚蒯通》第一折吓得项王目瞪口呆，动弹不得。”" },
  { w: "相与为一", p: ["xiāng", "yǔ", "wéi", "yī"], e: "相与相互。相互结合成为一体。", s: "汉·贾谊《过秦论》诸侯恐惧，同盟而谋弱秦，不爱珍器重宝肥饶之地，以致天下之士，合从缔交，相与为一。”汉·董仲舒《春秋繁露》卷第十谓之性情，性情相与为一瞑，情亦性也，谓性已善，奈其情何？”" },
  { w: "相安无事", p: ["xiāng", "ān", "wú", "shì"], e: "相互相；安安稳。指彼此相处没有什么争执或冲突，还过得去。", s: "宋·邓牧《伯牙琴·吏道》古者君民间相安无事者，固不得无吏，而为员不多。”" },
  { w: "相对无言", p: ["xiāng", "duì", "wú", "yán"], e: "指彼此相对说不出话来。", s: "宋·苏轼《江城子·乙卯正月二十日夜记梦》词夜来幽梦忽还乡，小轩窗，正梳妆，相顾无言，唯有泪千行。”" },
  { w: "相持不下", p: ["xiāng", "chí", "bù", "xià"], e: "双方对立，彼此相持，不肯让步。", s: "《史记·项羽本纪》楚汉久相持未决，丁壮苦军旅，老弱罢（疲）转漕。”" },
  { w: "知人下士", p: ["zhī", "rén", "xià", "shì"], e: "知识别。下士屈己尊人。能识别人才并礼贤下士。", s: "" },
  { w: "知人之明", p: ["zhī", "rén", "zhī", "míng"], e: "能看出人的品行才能的眼力。", s: "" },
  { w: "知人论世", p: ["zhī", "rén", "lùn", "shì"], e: "原指了解一个人并研究他所处的时代背景。现也指鉴别人物的好坏，议论世事的得失。", s: "《孟子·万章下》颂其诗，读其书，不知其人可乎？是以论其世也。”" },
  { w: "知情不举", p: ["zhī", "qíng", "bù", "jǔ"], e: "举检举。了解情况而不揭发。", s: "清·吴璿《飞龙全传》第一回我为巡城之职，理宜奏闻；若为朋友之情，匿而不奏，这知情不举的罪名，亦所不免。”" },
  { w: "知无不言", p: ["zhī", "wú", "bù", "yán"], e: "凡是知道的没有不说的。", s: "宋·苏洵《衡论·远虑》知无不言，言无不尽，百人誉之不加密，百人毁之不加疏。”" },
  { w: "破釜沉舟", p: ["pò", "fǔ", "chén", "zhōu"], e: "比喻下决心不顾一切地干到底。", s: "《史记·项羽本纪》项羽乃悉引兵渡河，皆沉船，破釜甑，烧庐舍，持三日粮，以示士卒必死，无一还心。”" },
  { w: "硕大无比", p: ["shuò", "dà", "wú", "bǐ"], e: "形容极大。同硕大无朋”。", s: "" },
  { w: "礼无不答", p: ["lǐ", "wú", "bù", "dá"], e: "礼礼数。一方以礼相待，另一方不能不以礼相报。亦指不受他人之礼，必以报答。", s: "《礼记·燕义》君举旅于宾，及君所赐爵，皆降再拜稽首，升成拜，明臣礼也。君答拜之，礼无不答，明君上之礼也。”" },
  { w: "神而明之", p: ["shén", "ér", "míng", "zhī"], e: "指表面玄妙的事理。", s: "《周易·系辞上》化而裁之，存乎变；推而行之，存乎通；神而明之，存乎其人。”" },
  { w: "秀而不实", p: ["xiù", "ér", "bù", "shí"], e: "秀庄稼吐穗开花；实结果实。开花不结果。比喻只学到一点皮毛，实际并无成就。", s: "《论语·子罕》苗而不秀者有矣夫。秀而不实者有矣夫。”" },
  { w: "秘而不言", p: ["mì", "ér", "bù", "yán"], e: "严守秘密，不肯吐露。同秘而不露”。", s: "" },
  { w: "积不相能", p: ["jī", "bù", "xiāng", "néng"], e: "积积久而成的；能亲善。指一向不和睦。", s: "《左传·襄公二十一年》栾桓子娶于范宣子，生怀子，范鞅以其亡也，怨栾氏，故与栾盈为公族大夫而不相能。”《后汉书·吴汉传》子与刘公积不相能，而信其虚谈，不为之备，终受制矣。”" },
  { w: "立人达人", p: ["lì", "rén", "dá", "rén"], e: "立建树，成就；达发达，显贵。旧指帮助人建立功业，提高地拉。", s: "《论语·雍也》夫仁者，己欲立而立人，己欲达而达人。能近取譬，可谓仁之方也已！”" },
  { w: "等而上之", p: ["děng", "ér", "shàng", "zhī"], e: "按某一等级，由此再往上。", s: "宋·朱燮《絜斋集·高鞅论》古者五家置一比长，等而上之，为闾，为旅，为党，皆置官焉。”" },
  { w: "等而下之", p: ["děng", "ér", "xià", "zhī"], e: "由这一等逐级往下。指跟某一事物比较起来更差。", s: "宋·朱熹《朱子语类》卷六十五等而下之，如医技养生家之说，皆不离阴阳二者。”" },
  { w: "经国之才", p: ["jīng", "guó", "zhī", "cái"], e: "经治理。有治理国家的才能。形容才能卓著。", s: "晋·葛洪《抱朴子·外篇自序》一时莫论，经国之才。”" },
  { w: "缺一不可", p: ["quē", "yī", "bù", "kě"], e: "少一样也不行。", s: "明·施耐庵《水浒传》第二十回林冲道‘只今番克敌制胜，便见得先生妙法。正是鼎分三足，缺一不可，先生不必推却。’”" },
  { w: "罗之一目", p: ["luó", "zhī", "yī", "mù"], e: "网之一孔。比喻局部在整体中才能起其作用；脱离了整体，局部便不起作用。", s: "《淮南子·说山训》有鸟将来，张罗而待之，得鸟者罗之一目也。今非昔比为一目之罗，则无时得鸟矣。”" },
  { w: "置之不理", p: ["zhì", "zhī", "bù", "lǐ"], e: "之代词，它；理理睬。放在一边，不理不睬。", s: "清·黄小配《廿载繁华梦》第十六回各人听了，反不以为是，就有说他是嫌钱多的，又有说他是愿贫不愿富的，邓仪卿种种置之不理而已。”" },
  { w: "置之不顾", p: ["zhì", "zhī", "bù", "gù"], e: "置放着；之代词；顾照管。放在那儿不管。", s: "清·曹雪芹《红楼梦》第80回那薛蟠得了宝蟾，如获珍宝，一概都置之不顾。”" },
  { w: "美中不足", p: ["měi", "zhōng", "bù", "zú"], e: "大体很好，但还有不足。", s: "明·凌濛初《初刻拍案惊奇》卷二十七破镜重圆，离而复合，固是好事；但王夫人所遭不幸，失身为妾，又不曾根究奸人，报仇雪恨，尚为美中不足。”" },
  { w: "美言不信", p: ["měi", "yán", "bù", "xìn"], e: "信信实，真实。词藻华美的言辞、文章，内容往往不真实。", s: "" },
  { w: "老大无成", p: ["lǎo", "dà", "wú", "chéng"], e: "老大年老。年纪已老，无所成就。", s: "清·李汝珍《镜花缘》第十回既不能显亲扬名，又不能兴邦定业，碌碌人世，殊愧老大无成。”" },
  { w: "老而不死", p: ["lǎo", "ér", "bù", "sǐ"], e: "本是孙子骂旧友原壤年老无德可称术的话，后亦指年老而不利于社会国家或拖累后辈。", s: "《论语·宪问》子曰‘幼而不孙弟，长而无述焉，老而不死是为贼。”" },
  { w: "者也之乎", p: ["zhě", "yě", "zhī", "hū"], e: "者、也、之、乎都是古汉语里常用的虚词。指讲话或写文章咬文嚼字‖讽刺意。", s: "元·马致远《荐福碑》第一折问黄金谁买《长门赋》，好不直钱也者也之乎。”" },
  { w: "而今而后", p: ["ér", "jīn", "ér", "hòu"], e: "而语助词。从今以后。", s: "《吕氏春秋·恃君览·长利》臣而今而后知吾先君周公之不若太公望封之知也。”《旧唐书·卢藏用传》而今而后，焚蓍龟，毁律历，废六合，斥五行，浩然清虑，则将奚若？”" },
  { w: "而立之年", p: ["ér", "lì", "zhī", "nián"], e: "人到三十岁可以自立的年龄◇为三十岁的代称。", s: "《论语·为政》吾十有五而志于学，三十而立，四十而不惑。”" },
  { w: "胸有成竹", p: ["xiōng", "yǒu", "chéng", "zhú"], e: "原指画竹子要在心里有一幅竹子的形象◇比喻在做事之前已经拿定主意。", s: "宋·苏轼《文与可画筼箉谷偃竹记》故画竹，必先得成竹于胸中。”" },
  { w: "能上能下", p: ["néng", "shàng", "néng", "xià"], e: "指干部不计较职位高低，不论处于领导岗位或在基层从事实际工作，都能踏踏实实地干。实行能上能下，是对干部职务终身制的一项重要改革。", s: "" },
  { w: "脸无人色", p: ["liǎn", "wú", "rén", "sè"], e: "形容极端恐惧。", s: "" },
  { w: "自不待言", p: ["zì", "bù", "dài", "yán"], e: "大家心里明白，不必再用言语解释。", s: "" },
  { w: "自作解人", p: ["zì", "zuò", "jiě", "rén"], e: "指不明真意而乱发议论的人。", s: "南朝宋·刘义庆《世说新语·文学》非但能言人不可得，正索解人亦不得。”" },
  { w: "自出一家", p: ["zì", "chū", "yī", "jiā"], e: "指在某一方面的学问或技术有独到的见解或独特的做法，能自成体系。", s: "《魏书·祖莹传》文章须自出机杼，成一家风骨，何能共人同生活也。”" },
  { w: "自愧不如", p: ["zì", "kuì", "bù", "rú"], e: "弗不。自己惭愧不如别人。", s: "《战国策·齐策一》明日徐公来，熟视之，自以为不如。”" },
  { w: "自成一家", p: ["zì", "chéng", "yī", "jiā"], e: "指在某一方面的学问或技术有独到的见解或独特的做法，能自成体系。", s: "《北史·祖莹传》作文须自出机杼，成一家风骨。”" },
  { w: "自有公论", p: ["zì", "yǒu", "gōng", "lùn"], e: "指事情的是非曲直公众自然会有评论。", s: "南朝·宋·刘义庆《世说新语·品藻》抜庾公呴又问‘何者居其右？’王曰‘自有人。’又问‘何者是？’王曰‘噫！其自有公论。’”明·罗贯中《三国演义》第一回朝廷自有公论，汝岂可造次？”" },
  { w: "自然而然", p: ["zì", "rán", "ér", "rán"], e: "自由发展，必然这样。指非人力干预而自然如此。", s: "《牟子理惑篇》夫吉凶之与善恶，犹善恶之乘形声，自然而然，不得相免也。”" },
  { w: "自相矛盾", p: ["zì", "xiāng", "máo", "dùn"], e: "矛进攻敌人的刺击武器；盾保护自己的盾牌。比喻自己说话做事前后抵触。", s: "《韩非子·难一》楚人有鬻盾与矛者，誉之曰‘吾盾之坚，莫之能陷也。’又誉其矛曰‘吾矛之利，于物无不陷也。’或曰‘以子之矛陷子之盾，何如？’其人勿能应也。”" },
  { w: "自知之明", p: ["zì", "zhī", "zhī", "míng"], e: "自知自己了解自己；明看清事物的能力。指了解自己的情况，对自己有正确的估计。", s: "《老子》第三十三章知人者智也，自知者明也。”" },
  { w: "自言自语", p: ["zì", "yán", "zì", "yǔ"], e: "自己一个人低声嘀咕。", s: "元·无名氏《桃花女》第四折你这般鬼促促的，在这自言自语，莫不要出城去砍那桃树吗？”" },
  { w: "自高自大", p: ["zì", "gāo", "zì", "dà"], e: "自以为了不起。", s: "北齐·颜之推《颜氏家训·勉学》见人读数十卷书，便自高大，凌忽长者，轻慢同列。”" },
  { w: "至人无梦", p: ["zhì", "rén", "wú", "mèng"], e: "至人指思想道德等方面达到最高境界的人。品德高尚的人，不会做想入非非的梦。", s: "清·钱彩《说岳全传》第五十九回自古至人无梦，梦境忽来，未必无兆。”" },
  { w: "至高无上", p: ["zhì", "gāo", "wú", "shàng"], e: "至最。高到顶点，再也没有更高的了。", s: "《淮南子·缪称训》道至高无上，至深无下，平乎准，直乎绳，圆乎规，方乎矩。”汉·许慎《说文解字·一部》天，颠也。至高无上，从一大。”" },
  { w: "舍己为人", p: ["shě", "jǐ", "wèi", "rén"], e: "舍弃自己的利益去帮助别人。", s: "《论语·先进》夫子喟然叹曰‘吾与点也。’”朱熹注初无舍己为人之意，而其胸次悠然，直与天地万物上下同流，各得其所之妙。”" },
  { w: "若无其事", p: ["ruò", "wú", "qí", "shì"], e: "象没有那回事一样。形容遇事沉着镇定或不把事情放在心上。", s: "冯德英《苦菜花》第三章王柬芝若无其事地闩上门，又叫她点着灯，他那双眼睛四处巡视着。”" },
  { w: "若有若无", p: ["ruò", "yǒu", "ruò", "wú"], e: "形容事物不清晰或关系不亲密。", s: "明·洪应明《菜根谭·闲适》若有若无，半真半幻，最足以悦人心目而豁人性灵。真天地间一妙境也。”" },
  { w: "苦不可言", p: ["kǔ", "bù", "kě", "yán"], e: "痛苦或困苦到了极点，已经不能用言语来表达。", s: "宋·李昌龄《乐善录·刘贡父》晚年得恶疾，须眉堕落，鼻梁断坏，苦不可言。”" },
  { w: "表里不一", p: ["biǎo", "lǐ", "bù", "yī"], e: "表面与内在不一样。", s: "《逸周书·谥法解》行见中外曰悫。”" },
  { w: "要而言之", p: ["yào", "ér", "yán", "zhī"], e: "要简要。概括地说，简单地说。", s: "晋·陆机《五等论》且要而言之，五等之君为己思治，郡县之长为利图物。”" },
  { w: "要而论之", p: ["yào", "ér", "lùn", "zhī"], e: "犹言要而言之。概括地说，简单地说。", s: "《天讨·豕韦之裔〈普告汉人〉》要而论之，满人之人中国也，据其土地山河，窃棋子女玉帛……固古人所谓倒行逆施者矣。”" },
  { w: "见事生风", p: ["jiàn", "shì", "shēng", "fēng"], e: "形容遇到事情，兴风作浪。", s: "清·和邦额《夜谭随录·棘闱志异》第少年喜事，每捕风捉影，见事生风。”" },
  { w: "见事风生", p: ["jiàn", "shì", "fēng", "shēng"], e: "指遇事雷厉风行。", s: "" },
  { w: "见所不见", p: ["jiàn", "suǒ", "bù", "jiàn"], e: "看到从来没有看到过的。形容事物十分稀罕。同见所未见”。", s: "" },
  { w: "视人如子", p: ["shì", "rén", "rú", "zǐ"], e: "形容帝王、官吏爱护百姓。同视民如子”。", s: "" },
  { w: "视而不见", p: ["shì", "ér", "bù", "jiàn"], e: "指不注意，不重视，睁着眼却没看见。也指不理睬，看见了当作没看见。", s: "《礼记·大学》心不在焉，视而不见，听而不闻，食而不知其味。”" },
  { w: "解人难得", p: ["jiě", "rén", "nán", "dé"], e: "解人原指通达言语或文辞意趣的人，借指知己；难得不易得到。比喻知己难得。", s: "南朝·宋·刘义庆《世说新语·文学》谢安年少时，请阮光禄道《白马论》，为论以示谢，于时，谢不即解阮语，重相咨尽。阮乃叹曰‘非但能言人不可得，正索解人亦不得。’”" },
  { w: "言不及义", p: ["yán", "bù", "jí", "yì"], e: "及涉及；义正经的道理。指净说些无聊的话，没有一句正经的。", s: "《论语·魏灵公》群居终日，言不及义，好行小慧，难矣哉！”" },
  { w: "言不尽意", p: ["yán", "bù", "jìn", "yì"], e: "情意曲折深远，言语难以全部表达。常用于书信末尾，表示说的话没能把意思都表达出来。", s: "《易·系辞上》书不尽言，言不尽意。”" },
  { w: "言不由中", p: ["yán", "bù", "yóu", "zhōng"], e: "指心口不一致。同言不由衷”。", s: "清·蒲松龄《聊斋志异·贾奉雉》实相告此言不由中，转瞬即去，便受夏楚，不能复忆之也。”" },
  { w: "言不达意", p: ["yán", "bù", "dá", "yì"], e: "说的话不能准确地表达思想内容。亦作言不逮意”。", s: "《明史·广西土司传二·思明》以译者言不达意，复为书晓之。”" },
  { w: "言之不预", p: ["yán", "zhī", "bù", "yù"], e: "没有预先说明。", s: "毛泽东《新民主主义论》七这是我们共产党人的衷心劝告，‘勿谓言之不预也’。”" },
  { w: "言之成理", p: ["yán", "zhī", "chéng", "lǐ"], e: "之代词，指所说的话。话说得有一定道理。", s: "《荀子·非十二子》然而其持之有故，其言之成理，足以欺惑愚众。”" },
  { w: "言之无物", p: ["yán", "zhī", "wú", "wù"], e: "指文章或言论空空洞洞，没有实际内容。", s: "毛泽东《反对党八股》空话连篇言之无物的演说，是必须停止的。”" },
  { w: "言之有序", p: ["yán", "zhī", "yǒu", "xù"], e: "说话和写文章很有条理。", s: "《周易·艮》言有序，悔亡。”" },
  { w: "言之有故", p: ["yán", "zhī", "yǒu", "gù"], e: "所说的话有根据。同言之成理”。", s: "清·魏源《默觚下·治篇六》其言之有故，其持之成理，上傅会乎经义，使人主中其腊毒而不自知，君子所深恶也。”" },
  { w: "言之有物", p: ["yán", "zhī", "yǒu", "wù"], e: "物内容。文章或讲话有具体内容。", s: "《周易·家人》君子以言有物而行有恒。”" },
  { w: "言之有理", p: ["yán", "zhī", "yǒu", "lǐ"], e: "说的话有道理。", s: "明·吴承恩《西游记》第四十八回陈老道‘言之有理。’”" },
  { w: "言之有礼", p: ["yán", "zhī", "yǒu", "lǐ"], e: "说的话有道理。", s: "" },
  { w: "言人人殊", p: ["yán", "rén", "rén", "shū"], e: "殊不同。说的话个个不同。指各人有各人的意见。", s: "《史记·曹相国世家》尽召长老诸生，问所以安集百姓，如齐故诸儒以百数，言人人殊。参未知所定。”" },
  { w: "言外之意", p: ["yán", "wài", "zhī", "yì"], e: "指有这个意思，但没有在话里明说出来。", s: "宋·欧阳修《六一诗话》必能状难写之景，如在目前，含不尽之意，见于言外，然后为至矣。”宋·叶梦得《石林诗话》七言难于气象雄浑，句中有力而纡余，不失言外之意。”" },
  { w: "言无不尽", p: ["yán", "wú", "bù", "jìn"], e: "把内心的话说尽，毫不保留。", s: "《北齐书·高德政传》德政与帝旧相昵爱，言无不尽。”" },
  { w: "言是人非", p: ["yán", "shì", "rén", "fēi"], e: "指言论无可非议，但为人不可取。", s: "明·李贽《史纲评要·宋纪·太祖》徐铉、张洎言是人非。”" },
  { w: "言者不知", p: ["yán", "zhě", "bù", "zhī"], e: "指多言多语的人缺乏智能。", s: "《老子》知者不言，言者不知。”河上公注知者贵行不贵言也。驷不及舌，多言多患。”一本作言者弗知”。" },
  { w: "言而不信", p: ["yán", "ér", "bù", "xìn"], e: "说话不讲信用。", s: "《淮南子·泰族训》施而不仁，言而不信，怒而不威，是以外貌为之者也。”" },
  { w: "言而无信", p: ["yán", "ér", "wú", "xìn"], e: "说话不算数，没有信用。", s: "《谷梁传·僖公二十二年》言之所以为言者，信也。言而不信，何以为言？”" },
  { w: "言而有信", p: ["yán", "ér", "yǒu", "xìn"], e: "说话靠得住，有信用。", s: "《论语·学而》与朋友交，言而有信。”" },
  { w: "计无复之", p: ["jì", "wú", "fù", "zhī"], e: "指再无别的办法可想，不得不这样。", s: "西汉·司马迁《史记·季布栾布列传论》夫婢妾贱人感慨而自杀者，非能勇也，其计画无复之耳。”" },
  { w: "计无所之", p: ["jì", "wú", "suǒ", "zhī"], e: "犹言计无所出。想不出什么办法。", s: "" },
  { w: "计无所出", p: ["jì", "wú", "suǒ", "chū"], e: "计计策，办法。想不出什么办法。", s: "《三国志·蜀志·谯周传》后主使群臣会议，计无所出。”" },
  { w: "论世知人", p: ["lùn", "shì", "zhī", "rén"], e: "犹言知人论世。指了解一个人并研究他所处的时代。亦泛指鉴别人物，评论世事。", s: "" },
  { w: "诗以言志", p: ["shī", "yǐ", "yán", "zhì"], e: "用诗歌表达自己的思想和志趣。亦作诗言志”、诗以道志”。", s: "" },
  { w: "诗礼人家", p: ["shī", "lǐ", "rén", "jiā"], e: "世代读书以传统封建礼教为行为准则的人家。", s: "" },
  { w: "话不虚传", p: ["huà", "bù", "xū", "chuán"], e: "指传言不假，与实际相符。", s: "" },
  { w: "说一不二", p: ["shuō", "yī", "bù", "èr"], e: "说怎么样就怎么样。形容说话算数。", s: "清·张春帆《宦海》第四回这个时候的邵孝廉，就是个小小的制台一般，说一是一，说二是二，庄制军没有一回驳过他的。”" },
  { w: "谈不容口", p: ["tán", "bù", "róng", "kǒu"], e: "犹言赞不绝口。不住口地称赞。", s: "" },
  { w: "谋事在人", p: ["móu", "shì", "zài", "rén"], e: "谋谋划，安排。根据个人的能力策划事情。", s: "明·罗贯中《三国演义》孔明叹曰‘谋事在人，成事在天，不可强也！’”" },
  { w: "贵不可言", p: ["guì", "bù", "kě", "yán"], e: "旧时多用以称人贵有帝王、母后之相。此话不能直言，故婉称之。", s: "" },
  { w: "赤子之心", p: ["chì", "zǐ", "zhī", "xīn"], e: "赤子初生的婴儿。比喻人心地纯洁善良。", s: "《孟子·离娄下》大人者，不失其赤子之心者也。”" },
  { w: "足不出门", p: ["zú", "bù", "chū", "mén"], e: "不出大门一步。指闭门自守。", s: "明·凌濛初《初刻拍案惊奇》卷二十五却说苏盼奴自赵司户去后，足不出门，一客不见，只等襄阳来音。”" },
  { w: "身无分文", p: ["shēn", "wú", "fēn", "wén"], e: "形容非常贫穷。", s: "" },
  { w: "迥不犹人", p: ["jiǒng", "bù", "yóu", "rén"], e: "指卓然超绝，不同于人。", s: "清·梁章锯《浪迹丛谈·二十四桥》玉生曾受业于方茶山先生，故其诗笔迥不犹人。”" },
  { w: "迫不及待", p: ["pò", "bù", "jí", "dài"], e: "近紧急。急迫得不能等待。形容心情急切。", s: "清·李汝珍《镜花缘》第六回且系酒后游戏，该仙子何以迫不急待。”" },
  { w: "述而不作", p: ["shù", "ér", "bù", "zuò"], e: "述阐述前人学说；作创作。指只叙述和阐明前人的学说，自己不创作。", s: "《论语·述而》述而不作，信而好古。”" },
  { w: "通家之好", p: ["tōng", "jiā", "zhī", "hǎo"], e: "指两家交情深厚，象一家人一样。", s: "元·秦简夫《东堂老》第四折有西邻赵国器，是这扬州奴父亲，与老夫三十载通家之好。”" },
  { w: "道不相谋", p: ["dào", "bù", "xiāng", "móu"], e: "指思想志向不同的人不会在一起共事。", s: "语出《论语·卫灵公》子曰‘道不同，不相为谋。’”" },
  { w: "道在人为", p: ["dào", "zài", "rén", "wéi"], e: "犹言事在人为。", s: "《金瓶梅词话》第三一回净云不打紧，道在人为，你见那里又一位王勃殿试来了。”" },
  { w: "道而不径", p: ["dào", "ér", "bù", "jìng"], e: "道走路。径小路。走路要走大路而不走小路，以免遇到危险。", s: "《吕氏春秋·孝行览》故舟而不游，道而不径，能全支体以守宗庙，可谓孝矣。”" },
  { w: "长生不死", p: ["cháng", "shēng", "bù", "sǐ"], e: "生命长存，永不死亡。", s: "晋·葛洪《抱朴子·辨问》长生不死，以此责圣人，何其多乎？”" },
  { w: "长生不老", p: ["cháng", "shēng", "bù", "lǎo"], e: "长生永生。原为道教的话，后也用作对年长者的祝愿语。", s: "《太上纯阳真经·了三得一经》天一生水，人同自然，肾为北极之枢，精食万化，滋养百骸，赖以永年而长生不老。”" },
  { w: "闻一知十", p: ["wén", "yī", "zhī", "shí"], e: "听到一点就能理解很多。形容善于类推。", s: "《论语·公冶长》赐也何敢望回？回也闻一以知十，赐也闻一以知二。”" },
  { w: "阒其无人", p: ["qù", "qí", "wú", "rén"], e: "阒空。指空荡荡，没有一人。", s: "《周易·丰》窥其户，阒其无人。”" },
  { w: "阒无一人", p: ["qù", "wú", "yī", "rén"], e: "阒空。指空荡荡，没有一人。", s: "清·刘献廷《广阳杂记》卷四曾梦至一处，见禅床几杖萧然，而阒无一人。”" },
  { w: "难于上天", p: ["nán", "yú", "shàng", "tiān"], e: "比上天还难。形容极其困难，不易实现。", s: "汉·枚乘《上书谏吴王》必若所欲为，危于累卵，难于上天。”" },
  { w: "难以为情", p: ["nán", "yǐ", "wéi", "qíng"], e: "指情面上过不去。", s: "" },
  { w: "集矢之的", p: ["jí", "shǐ", "zhī", "de"], e: "比喻众人所指摘的对象。", s: "" },
  { w: "雪中送炭", p: ["xuě", "zhōng", "sòng", "tàn"], e: "在下雪天给人送炭取暖。比喻在别人急需时给以物质上或精神上的帮助。", s: "宋·范成大《大雪送炭与芥隐》诗不是雪中须送炭，聊装风景要诗来。”" },
  { w: "面不改容", p: ["miàn", "bù", "gǎi", "róng"], e: "指脸色不改变。形容遇到危难时，镇定自若。", s: "" },
  { w: "面无人色", p: ["miàn", "wú", "rén", "sè"], e: "脸色没有一点血色。形容恐惧到极点或非常虚弱。", s: "《汉书·李广传》广为匈奴所败，吏士皆无人色，广意气自若。”" },
  { w: "风云人物", p: ["fēng", "yún", "rén", "wù"], e: "指活跃一时，言论行为能影响大局的人物。", s: "毛泽东《别了，司徒雷登》因此被马歇尔看中，做了驻华大使，成为马歇尔系统中的风云人物之一。”" },
  { w: "风流人物", p: ["fēng", "liú", "rén", "wù"], e: "风流英俊的、杰出的。指对一个时代有很大影响的人物。有时也指举止潇洒或惯于调情的人。", s: "宋·苏轼《念奴娇·赤壁怀古》词大江东去，浪淘尽，千古风流人物。”" },
  { w: "食而不化", p: ["shí", "ér", "bù", "huà"], e: "吃了没有消化。比喻对所学知识理解得不深不透，没有吸收成为自己的东西。", s: "" },
  { w: "高下在心", p: ["gāo", "xià", "zài", "xīn"], e: "高下比喻伸和屈。原意是做事要斟酌情况，采取适当办法◇形容能胸有成竹地处理事情。", s: "《左传·宣公十五年》天方授楚，未可与争，虽晋之强，能违天乎？谚曰高下在心。”" },
  { w: "高人一等", p: ["gāo", "rén", "yī", "děng"], e: "比别人高出一个等级。指高过一般人。", s: "《礼记·檀弓上》献子加于人一等矣。”" },
  { w: "高人一筹", p: ["gāo", "rén", "yī", "chóu"], e: "高人比一般人高；筹筹码。比一般人高出一个筹码。指胜过别人。", s: "明·归有光《震川集·别集·七·与沈敬甫七首》圹志、子建云亦似。但千古哭声未尝不同，何论前世有屈原，贾生耶？以发吾之愤愤而已！钦甫云更似高人一筹也。”" },
  { w: "高而不危", p: ["gāo", "ér", "bù", "wēi"], e: "身居高位而没有倾覆的危险。", s: "" },
  { w: "鸦雀无声", p: ["yā", "què", "wú", "shēng"], e: "连乌鸦麻雀的声音都没有。形容非常静。", s: "宋·释道原《景德传灯录》卷四公曰‘鸦去无声，又何言闻？’”宋·苏轼《绝句三首》天风吹雨入阑干，乌鹊无声夜向阑。”" },
  { w: "鹤立鸡群", p: ["hè", "lì", "jī", "qún"], e: "象鹤站在鸡群中一样。比喻一个人的仪表或才能在周围一群人里显得很突出。", s: "晋·戴逵《竹林七贤论》嵇绍入洛，或谓王戎曰‘昨于稠人中始见嵇绍，昂昂然若野鹤之在鸡群。’”南朝·宋·刘义庆《世说新语·容止》嵇延祖卓卓如野鹤之在鸡群。”" }
];
